INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (4, 'PM Kisan Samman Nidhi', 'pm-kisan', 'Ministry of Agriculture & Farmers Welfare', 2018, NULL, 3, 'Direct income support scheme providing Rs 6,000 per year in three equal installments to small and marginal farmer families.', 'Provide income support of Rs 6,000/year to all farmer families. Cover 14.5 crore farmer families across India.', '14.5 crore small and marginal farmer families', 2024, 175000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (5, 'Beti Bachao Beti Padhao', 'bbbp', 'Ministry of Women and Child Development', 2015, NULL, 9, 'National programme to address the declining Child Sex Ratio and promote the welfare of girl children. Launched in Panipat, Haryana.', 'Prevent gender-biased sex selective elimination. Ensure survival and protection of the girl child. Ensure education and participation of the girl child.', '100 districts with lowest Child Sex Ratios across India', 2020, 848.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (10, 'Jal Jeevan Mission', 'jal-jeevan', 'Ministry of Jal Shakti', 2019, 'National Rural Drinking Water Programme', 8, 'Mission to provide safe and adequate drinking water through tap connections to all rural households by 2024. Renamed from NRDWP.', 'Provide Har Ghar Jal (tap water to every household). Connect 19.26 crore rural households with tap water by 2024.', '19.26 crore rural households', 2024, 360000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (14, 'Startup India', 'startup-india', 'Department for Promotion of Industry and Internal Trade', 2016, NULL, 11, 'Initiative to build a strong ecosystem for nurturing innovation and startups in India, drive sustainable economic growth and generate employment.', 'Create 7.5 lakh startups by 2020. Generate employment for 20 lakh people. Launch Rs 10,000 crore Fund of Funds.', 'Entrepreneurs, startups, innovation ecosystems across India', 2020, 10000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (1, 'Pradhan Mantri Awas Yojana (Urban)', 'pmay-urban', 'Ministry of Housing and Urban Affairs', 2015, 'Rajiv Awas Yojana', 1, 'Aims to provide affordable housing to urban poor through financial assistance. Previously known as Rajiv Awas Yojana and Indira Awas Yojana in its rural form.', 'Housing for All by 2022. Provide pucca houses to all eligible urban families. Target: construct 1.12 crore houses in urban areas.', '1.12 crore urban households living in slums and economically weaker sections', 2022, 200000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (2, 'Swachh Bharat Mission (Urban)', 'swachh-bharat-urban', 'Ministry of Housing and Urban Affairs', 2014, 'Nirmal Bharat Abhiyan', 7, 'Flagship sanitation programme launched on 2 October 2014. Aims to eliminate open defecation and improve solid waste management in urban areas.', 'Make India Open Defecation Free (ODF) by 2 October 2019. Construct 66 lakh household toilets and 5 lakh community toilets.', '4,041 statutory towns across India', 2019, 62009.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (11, 'Namami Gange Programme', 'namami-gange', 'Ministry of Jal Shakti', 2014, 'National Ganga River Basin Authority (NGRBA)', 5, 'Integrated conservation mission to accomplish effective abatement of pollution, conservation and rejuvenation of the Ganga river.', 'Reduce pollution in Ganga to acceptable limits by 2022. Nirmal Ganga (clean Ganga) by 2020. Aviral Ganga (continuous flow) throughout.', 'Population living along the Ganga basin; 5 main-stem states', 2022, 20000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (9, 'Saubhagya (Pradhan Mantri Sahaj Bijli Har Ghar Yojana)', 'saubhagya', 'Ministry of Power', 2017, NULL, 5, 'Scheme to provide electricity connections to all un-electrified households in rural areas and poor households in urban areas. Replaced RGGVY.', 'Achieve universal household electrification by December 2018. Provide free electricity connections to BPL families.', 'All un-electrified households: approximately 4 crore households', 2018, 16320.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (3, 'Ayushman Bharat – PM Jan Arogya Yojana', 'pmjay', 'Ministry of Health and Family Welfare', 2018, 'Rashtriya Swasthya Bima Yojana', 2, 'World''s largest health insurance scheme providing health cover of Rs 5 lakh per family per year for secondary and tertiary care hospitalization. Renamed from RSBY.', 'Cover 10 crore poor and vulnerable families (approximately 50 crore beneficiaries) for health expenses. Reduce out-of-pocket health expenditure.', '10 crore families from bottom 40% of Indian population', 2023, 64000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (13, 'Pradhan Mantri Kaushal Vikas Yojana (PMKVY)', 'pmkvy', 'Ministry of Skill Development and Entrepreneurship', 2015, 'Skill Development Initiative Scheme (SDIS)', 10, 'India''s flagship demand-driven skill certification scheme, now in its fourth phase (2022–26). Trains youth in industry-relevant short-term courses (STT) and certifies existing workers through Recognition of Prior Learning (RPL). Run through a network of NSDC-accredited training centres and Skill India Digital Hub.', 'PMKVY 1.0 (2015-16): 24 lakh candidates. PMKVY 2.0 (2016-20): 1 crore candidates, ₹12,000 crore. PMKVY 3.0 (2020-21): 8 lakh candidates, ₹948 crore. PMKVY 4.0 (2022-26): Industry 4.0 skills (AI, drones, green energy, coding) with on-the-job training, ₹6,000 crore; cumulative target of 1.4 crore additional candidates.', 'School/college dropouts and unemployed youth (STT); employed informal workers seeking formal certification (RPL); special focus on North-East, hill states and tribal districts', 2026, 6000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (7, 'PM Ujjwala Yojana', 'pmuy', 'Ministry of Petroleum and Natural Gas', 2016, 'Rajiv Gandhi Gramin LPG Vitaran Yojana', 5, 'Scheme to provide free LPG connections to women from BPL households. Aims to replace unclean cooking fuels with clean LPG.', 'Provide 8 crore LPG connections to BPL women by 2020. Safeguard health of women and children from pollution caused by traditional cooking fuels.', 'Women from BPL households across rural India', 2020, 12800.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (16, 'Digital India Programme', 'digital-india', 'Ministry of Electronics and Information Technology', 2015, 'National e-Governance Plan (NeGP)', 11, 'Flagship programme to transform India into a digitally empowered society and knowledge economy. Covers digital infrastructure, digital services, and digital literacy.', 'Broadband highways to all gram panchayats. Universal mobile connectivity. Public internet access. e-Governance. Cashless economy. Digital literacy for 6 crore rural households.', 'All citizens; focus on rural India', 2022, 113000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (15, 'Smart Cities Mission', 'smart-cities', 'Ministry of Housing and Urban Affairs', 2015, 'Jawaharlal Nehru National Urban Renewal Mission (JNNURM)', 7, 'Mission to develop 100 smart cities as models of urban development for the rest of India through area-based development and pan-city initiatives.', 'Develop 100 smart cities by 2023 with smart solutions. Improve quality of life for urban residents. Total investment of Rs 2 lakh crore.', '100 selected cities across India', 2023, 200000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (31, 'UDAN (Ude Desh ka Aam Naagrik)', 'udan', 'Ministry of Civil Aviation', 2016, NULL, 7, 'Regional connectivity scheme to make air travel affordable for common citizens and connect tier-2 and tier-3 cities. Uses viability gap funding for airlines.', 'Connect 100 unserved/underserved airports by 2019. Provide airfare capped at Rs 2,500 for 1-hour journey. Operationalise 1,000 routes by 2024.', 'Common citizens in tier-2 and tier-3 cities; first-time flyers', 2024, 4500.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (28, 'Samagra Shiksha Abhiyan', 'samagra-shiksha', 'Ministry of Education', 2018, 'Sarva Shiksha Abhiyan', 4, 'Integrated scheme for school education extending from pre-school to Class 12. Treats school education holistically without segmentation.', 'Universal access to quality education. Improve learning outcomes. Reduce gender and social category gaps. Transition rate from primary to upper primary to 90%.', 'All school-going children from pre-primary to Class 12', 2026, 294283.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (32, 'Bharatmala Pariyojana', 'bharatmala', 'Ministry of Road Transport and Highways', 2017, 'National Highways Development Project', 7, 'Umbrella programme for highways development focusing on optimising efficiency of freight and passenger movement across India through development of Economic Corridors.', 'Develop 34,800 km of national highways including 9,000 km of Economic Corridors. Complete by 2022 at cost of Rs 5.35 lakh crore.', 'All highway users; logistics sector; connect 550 districts', 2022, 535000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (26, 'POSHAN Abhiyaan (National Nutrition Mission)', 'poshan-abhiyaan', 'Ministry of Women and Child Development', 2018, 'Integrated Child Development Services (ICDS) Scheme', 9, 'Government''s flagship programme to improve nutritional outcomes for children, pregnant women and lactating mothers. Uses technology and Jan Andolan approach.', 'Reduce stunting from 38.4% to 25% by 2022. Reduce undernutrition from 35.7% to 20%. Reduce anaemia among children from 58.5% to 40%. Reduce low birth weight by 2%.', 'Children 0-6 years, pregnant women, lactating mothers across India', 2022, 9046.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (29, 'PM Poshan Shakti Nirman (Mid-Day Meal Scheme)', 'pm-poshan', 'Ministry of Education', 2021, 'Mid-Day Meal Scheme', 4, 'Renamed from Mid-Day Meal Scheme, provides free hot cooked meals to students in government schools. Enhanced to include breakfast in aspirational districts.', 'Provide nutritious meal to 11.80 crore school children daily. Improve enrollment, retention and attendance in schools. Address classroom hunger.', '11.80 crore students in government and government-aided schools', 2026, 130000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (19, 'Pradhan Mantri Gram Sadak Yojana (Phase III)', 'pmgsy', 'Ministry of Rural Development', 2019, 'Pradhan Mantri Gram Sadak Yojana', 8, 'Provides all-weather road connectivity to unconnected habitations in rural areas. Phase III focuses on consolidation and upgradation of existing rural roads.', 'Connect all remaining unconnected habitations of 500+ population. Upgrade 1,25,000 km of existing rural roads. Total road length: 2.5 lakh km.', 'Rural habitations with population over 500 (250 in hilly/tribal areas)', 2025, 80250.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (18, 'AMRUT (Atal Mission for Rejuvenation and Urban Transformation)', 'amrut', 'Ministry of Housing and Urban Affairs', 2015, 'Jawaharlal Nehru National Urban Renewal Mission', 7, 'Mission to establish infrastructure to ensure basic services including water supply, sewerage, urban transport to households and build amenities in cities.', 'Provide tap water connections to 1.06 crore urban households. Sewerage connections to 78 lakh households. Develop parks and green spaces.', '500 cities with population above 1 lakh', 2020, 50000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (24, 'National Health Mission', 'nhm', 'Ministry of Health and Family Welfare', 2013, 'National Rural Health Mission', 2, 'Umbrella mission encompassing National Rural Health Mission (NRHM) and National Urban Health Mission (NUHM). Continued and expanded under BJP government.', 'Reduce Infant Mortality Rate to 25 per 1,000 live births. Maternal Mortality Ratio to 100 per lakh. Total Fertility Rate to 2.1. Universal immunization coverage.', 'All rural and urban populations with focus on 18 high-focus states', 2025, 340000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (30, 'Khelo India Programme', 'khelo-india', 'Ministry of Youth Affairs and Sports', 2018, 'Rajiv Gandhi Khel Abhiyan', 4, 'Programme to revive sports culture at grassroots level in India. Identifies and trains talented young athletes with scholarships and world-class training.', 'Identify 1,000 talented young athletes annually. Provide Rs 5 lakh/year scholarship for 8 years. Develop sports infrastructure across India.', 'Young athletes aged 8-18 identified through Khelo India Games', 2025, 3183.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (25, 'Mission Indradhanush', 'mission-indradhanush', 'Ministry of Health and Family Welfare', 2014, 'Universal Immunization Programme', 2, 'Immunisation programme to cover all children under 2 years and pregnant women who are either unvaccinated or partially vaccinated against 12 vaccine-preventable diseases.', 'Achieve full immunisation coverage for at least 90% children by 2020 across all districts. Intensified Mission Indradhanush (IMI) to cover 190 low-coverage districts.', 'Children under 2 years and pregnant women across India', 2020, 2000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (34, 'Production Linked Incentive (PLI) Scheme', 'pli-scheme', 'Ministry of Commerce and Industry', 2020, NULL, 11, 'Scheme to give companies incentives on incremental sales from products manufactured in India over a base year. Covers 14 key sectors including electronics, pharma, autos.', 'Boost domestic manufacturing. Attract Rs 2 lakh crore investment over 5 years. Create 60 lakh employment. Generate Rs 30 lakh crore in production.', 'Manufacturers in 14 identified sectors', 2025, 197000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (35, 'PM SVANidhi (PM Street Vendor AtmaNirbhar Nidhi)', 'pm-svanidhi', 'Ministry of Housing and Urban Affairs', 2020, NULL, 6, 'Micro-credit scheme for street vendors to help them resume livelihoods after COVID-19 lockdowns. Provides collateral-free working capital loans with incentives for digital transactions.', 'Provide Rs 10,000 initial working capital loan to 50 lakh street vendors. Subsequent loans of Rs 20,000 and Rs 50,000 on timely repayment.', '50 lakh street vendors affected by COVID-19 lockdowns', 2022, 700.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (37, 'Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY)', 'ddu-gky', 'Ministry of Rural Development', 2014, 'Aajeevika Skills Programme', 10, 'Skill training and placement programme for rural youth from poor families. Aims to diversify incomes of rural families and cater to career aspirations of rural youth.', 'Skill and place 10 lakh rural youth by 2017. Achieve 75% placement in jobs post training. Cover all 676 districts across India.', 'Rural youth aged 15-35 from poor families across India', 2020, 8995.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (38, 'Atal Bhujal Yojana', 'atal-bhujal', 'Ministry of Jal Shakti', 2020, NULL, 5, 'Scheme for sustainable groundwater management with community participation in water-stressed areas. Focuses on demand-side interventions and community behaviour change.', 'Improve groundwater management in 8,353 water-stressed gram panchayats across 7 states. Reduce groundwater extraction by 20%. Increase community participation.', '8,353 gram panchayats in Gujarat, Haryana, Karnataka, MP, Maharashtra, Rajasthan, UP', 2025, 6000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (41, 'PM Kisan Urja Suraksha evam Utthaan Mahabhiyan (PM KUSUM)', 'pm-kusum', 'Ministry of New and Renewable Energy', 2019, NULL, 5, 'Scheme to add solar power generation capacity in rural areas, solarise agricultural pump sets, and install grid-connected solar power plants for farmers.', 'Install 30.8 GW solar capacity through 3 components: standalone solar pumps, solarisation of existing pumps, and solar plants on barren land. Cover 35 lakh farmers by 2022.', '35 lakh farmers with agricultural pump sets', 2022, 34422.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (42, 'Swamitva Scheme', 'swamitva', 'Ministry of Panchayati Raj', 2020, NULL, 8, 'Scheme to provide property rights to residents of rural areas of India by mapping land parcels using drone technology. Provides property cards to households.', 'Survey and map 6.62 lakh villages by 2025. Issue property cards to all village household owners. Enable property-based credit in rural areas.', 'Residents of 6.62 lakh villages with houses in abadi areas', 2025, 566.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (46, 'PMAY (Gramin) – PM Awas Yojana Rural', 'pmay-gramin', 'Ministry of Rural Development', 2016, 'Indira Awaas Yojana', 1, 'Separate from PMAY Urban. Provides financial assistance to rural BPL households to construct pucca houses with basic amenities including toilet, LPG connection, electricity.', 'Construct 2.95 crore pucca houses for rural poor by March 2022. Each house to have toilet, electricity, cooking gas. Unit cost Rs 1.20 lakh (plain) and Rs 1.30 lakh (hilly/tribal).', 'Rural BPL households living in kaccha or dilapidated houses', 2022, 130075.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (36, 'Aspirational Districts Programme', 'aspirational-districts', 'NITI Aayog', 2018, NULL, 8, 'Programme to quickly and effectively transform the most underdeveloped districts of India across 5 thematic areas: health, education, agriculture, financial inclusion, and infrastructure.', 'Convergence of central and state scheme spending. Improve rankings of 112 most backward districts by 2022. Real-time monitoring via Championsof Change dashboard.', '112 aspirational districts across 28 states', 2022, 49000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (40, 'National Apprenticeship Promotion Scheme', 'naps', 'Ministry of Skill Development and Entrepreneurship', 2016, 'Apprenticeship Training Scheme', 10, 'Scheme to promote apprenticeship training in India by sharing 25% of prescribed stipend with employers for fresh apprentices. Target: 50 lakh apprentices by 2020.', 'Engage 50 lakh apprentices by March 2020. Share 25% of stipend (up to Rs 1,500/month) with employers. Make apprenticeship more attractive for industry.', 'Industry partners; unemployed youth seeking on-the-job training', 2020, 10000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (47, 'Swachh Bharat Mission (Gramin)', 'swachh-bharat-gramin', 'Ministry of Jal Shakti', 2014, 'Nirmal Bharat Abhiyan', 8, 'Rural component of the Swachh Bharat Mission aiming to eliminate open defecation in rural India through construction of individual household toilets (IHHLs) and behaviour change.', 'Make all villages, gram panchayats, districts, states Open Defecation Free (ODF) by 2 October 2019. Construct 10 crore toilets. Establish solid and liquid waste management in all villages.', 'Rural households without toilets; 6 lakh villages across India', 2019, 134000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (49, 'Soil Health Card Scheme', 'soil-health-card', 'Ministry of Agriculture & Farmers Welfare', 2015, NULL, 3, 'Scheme to issue Soil Health Cards to farmers carrying crop-wise nutrient recommendations based on soil test results, to promote balanced use of fertilisers and improve soil health.', 'Issue 14 crore soil health cards to all farmers in 2 cycles of 3 years each. Reduce fertiliser subsidy bill. Improve soil fertility and crop productivity.', 'All 14 crore farming households across India', 2020, 1068.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (50, 'Pradhan Mantri Jan Aushadhi Pariyojana (PMJAP)', 'pmjap', 'Ministry of Chemicals and Fertilizers', 2015, 'Jan Aushadhi Scheme', 2, 'Scheme to make quality generic medicines available at affordable prices through dedicated retail stores called Pradhan Mantri Bhartiya Janaushadhi Kendras (PMBJKs) across the country.', 'Open 10,500 Jan Aushadhi Kendras by March 2025. Offer 2,000+ generic medicines at 50-90% less than branded prices. Save patients Rs 5,000 crore annually.', 'All citizens especially poor, elderly, and those with chronic diseases', 2025, 904.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (53, 'eNAM (National Agriculture Market)', 'enam', 'Ministry of Agriculture & Farmers Welfare', 2016, NULL, 3, 'Pan-India electronic trading portal for agricultural commodities providing a single window service for all APMC related information and services. Enables farmers to get better prices through online competitive bidding.', 'Integrate 585 APMCs with eNAM by 2018. Enable 1,000 mandis by 2020. Allow farmers to sell produce from any part of country. Increase farmer income by 20%.', 'Farmers, traders, and buyers of agricultural produce across integrated mandis', 2020, 200.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (54, 'Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY)', 'ddugjy', 'Ministry of Power', 2014, 'Rajiv Gandhi Grameen Vidyutikaran Yojana', 5, 'Scheme for rural electrification focusing on feeder separation of agricultural and domestic supply, strengthening sub-transmission and distribution infrastructure in rural areas.', 'Electrify all remaining 18,452 unelectrified villages by May 2018. Provide electricity connections to 2.37 crore BPL rural households. Strengthen rural distribution infrastructure.', '18,452 unelectrified villages; 2.37 crore BPL rural households', 2018, 75893.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (55, 'Ayushman Bharat Digital Mission (ABDM)', 'abdm', 'Ministry of Health and Family Welfare', 2021, 'National Digital Health Mission', 2, 'Mission to develop a national digital health ecosystem that supports universal health coverage. Creates a Health ID (ABHA) for every citizen linking all health records digitally.', 'Create health IDs for 100 crore citizens. Digitize health records of all citizens. Create national registries of doctors and health facilities. Enable paperless health ecosystem.', 'All 140 crore citizens of India', 2025, 1600.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (57, 'Shyama Prasad Mukherji Rurban Mission', 'rurban-mission', 'Ministry of Rural Development', 2016, NULL, 8, 'Mission to stimulate local economic development, enhance basic services, and create well-planned Rurban clusters (rural areas with urban amenities) to bridge rural-urban divide.', 'Develop 300 rural clusters as Rurban clusters with urban-level facilities while maintaining rural character. Cover 0.5-1 lakh population clusters across India.', '300 rural clusters across 28 states and 7 UTs', 2022, 5142.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (56, 'PM Garib Kalyan Anna Yojana (PMGKAY)', 'pmgkay', 'Ministry of Consumer Affairs, Food and Public Distribution', 2020, 'National Food Security Act, 2013 (NFSA)', 8, 'Free food grain scheme launched during COVID-19 pandemic providing additional 5 kg grain per person per month free of cost to NFSA beneficiaries. Extended multiple times, now merged with NFSA from 2023.', 'Provide free food grain to 80 crore NFSA beneficiaries during COVID and economic distress. Prevent hunger and starvation. Total expenditure exceeded Rs 3.91 lakh crore.', '80 crore National Food Security Act beneficiaries', 2023, 391000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (33, 'Sagarmala Programme', 'sagarmala', 'Ministry of Ports, Shipping and Waterways', 2015, NULL, 7, 'Programme for port-led development to reduce logistics cost for EXIM and domestic trade with minimal infrastructure investment through optimum utilization of waterways.', 'Implement 415 projects worth Rs 8 lakh crore by 2035. Reduce logistics cost from 14% to 8% of GDP. Create 1 crore new jobs.', 'Coastal communities; exporters; logistics industry', 2035, 579000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (52, 'Pradhan Mantri Matru Vandana Yojana (PMMVY)', 'pmmvy', 'Ministry of Women and Child Development', 2017, 'Indira Gandhi Matritva Sahyog Yojana (IGMSY)', 9, 'Maternity benefit programme providing cash incentive of Rs 5,000 to pregnant and lactating mothers for the first live birth to partly compensate for wage loss and improve health seeking behaviour.', 'Provide Rs 5,000 to all eligible pregnant and lactating women for first live birth. Cover 51.7 lakh beneficiaries annually. Reduce maternal and infant mortality.', 'Pregnant and lactating women (except those in regular employment) for first live birth', 2022, 10000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (48, 'PM Krishi Sinchai Yojana (PMKSY)', 'pmksy', 'Ministry of Jal Shakti', 2015, 'Accelerated Irrigation Benefits Programme (AIBP)', 3, 'Integrated irrigation scheme with motto "Har Khet Ko Pani, More Crop Per Drop". Consolidates existing irrigation schemes under one umbrella for end-to-end irrigation supply chain.', 'Achieve convergence of investments in irrigation. Expand cultivable area under irrigation by 76.03 lakh hectares. Improve water use efficiency. Cover all irrigation schemes by 2020.', 'Farmers with irrigated and unirrigated agricultural land across India', 2020, 50000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (8, 'Jan Dhan Yojana', 'pmjdy', 'Ministry of Finance', 2014, NULL, 6, 'National mission for financial inclusion to ensure access to financial services like banking, savings, remittance, credit, insurance and pension.', 'Open bank accounts for all unbanked adults. Provide RuPay debit card, Rs 1 lakh accident insurance, Rs 30,000 life cover. Cover 7.5 crore households.', 'All unbanked households across India, focus on rural areas', 2018, 3000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (6, 'Pradhan Mantri Mudra Yojana', 'pmmy', 'Ministry of Finance', 2015, 'Self Employment and Talent Utilization (SETU) Scheme', 6, 'Provides loans up to Rs 10 lakh to non-corporate, non-farm small/micro enterprises. Three products: Shishu (up to 50k), Kishore (50k-5L), Tarun (5L-10L).', 'Fund the unfunded. Provide institutional finance to micro/small business sector. Target 2.44 crore MSMEs by 2017-18.', 'Small and micro enterprises, self-employed individuals', 2020, 20000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (51, 'Mahatma Gandhi NREGS (BJP era continuation)', 'mgnregs', 'Ministry of Rural Development', 2005, 'National Rural Employment Guarantee Scheme (NREGS)', 8, 'Continuation and implementation of the MGNREGS Act under BJP government. Provides at least 100 days of guaranteed wage employment per year to adult members of rural households who demand unskilled manual work.', 'Provide 100 days of employment to all rural households demanding work. Strengthen livelihood security of rural poor. Create durable assets. Empower rural women.', '5-8 crore rural households annually demanding work', 2026, 660000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (21, 'PM Suraksha Bima Yojana', 'pmsby', 'Ministry of Finance', 2015, NULL, 6, 'Accident insurance scheme offering Rs 2 lakh cover for accidental death and full disability, Rs 1 lakh for partial disability at a premium of Rs 12/year.', 'Provide affordable insurance to those excluded from formal insurance. Target coverage of 10 crore people by 2020.', 'Bank account holders aged 18-70', 2020, 1000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (22, 'PM Jeevan Jyoti Bima Yojana', 'pmjjby', 'Ministry of Finance', 2015, NULL, 6, 'Life insurance scheme offering Rs 2 lakh cover on death from any cause at a premium of Rs 330/year, renewable annually.', 'Provide life insurance to those excluded from formal insurance sector. Target coverage of 5 crore people.', 'Bank account holders aged 18-50', 2020, 2000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (23, 'Stand Up India', 'stand-up-india', 'Department of Financial Services', 2016, NULL, 6, 'Scheme to facilitate bank loans between Rs 10 lakh and Rs 1 crore to at least one SC/ST borrower and one woman borrower per bank branch for greenfield enterprises.', 'Promote entrepreneurship among SC/ST communities and women. Target 2.5 lakh beneficiaries (one per bank branch) by 2019.', 'SC/ST entrepreneurs and women borrowers', 2019, 500.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (44, 'e-SHRAM Portal', 'e-shram', 'Ministry of Labour and Employment', 2021, NULL, 6, 'National database of unorganised workers to facilitate their access to social security benefits. Provides a Universal Account Number to each registered unorganised worker.', 'Register 38 crore unorganised workers on e-SHRAM portal by 2022. Provide Rs 2 lakh accidental insurance cover. Enable targeted delivery of social security benefits.', '38 crore unorganised sector workers across India', 2022, 404.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (45, 'Pradhan Mantri Vaya Vandana Yojana', 'pmvvy', 'Ministry of Finance', 2017, NULL, 6, 'Pension scheme for senior citizens providing assured pension/interest income at 7.4% per annum for 10 years. Managed by LIC of India with government subsidy.', 'Provide regular income to senior citizens post-retirement. Cover 30 lakh senior citizens. Maximum investment of Rs 15 lakh per family.', 'Senior citizens aged 60 and above', 2023, 156000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (12, 'Pradhan Mantri Fasal Bima Yojana', 'pmfby', 'Ministry of Agriculture & Farmers Welfare', 2016, 'National Crop Insurance Programme', 3, 'Crop insurance scheme providing financial support to farmers suffering crop loss/damage due to unforeseen events. Replaced NAIS and MNAIS.', 'Provide comprehensive risk coverage for pre-sowing to post-harvest losses. Stabilize farmers'' income and encourage crop diversification. Cover 50% of all farmers.', 'All farmers including sharecroppers growing notified crops', 2020, 130000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (20, 'Atal Pension Yojana', 'apy', 'Ministry of Finance', 2015, 'Swavalamban Yojana', 6, 'Government-backed pension scheme for unorganised sector workers guaranteeing pension of Rs 1,000–5,000 per month from age 60, depending on contribution.', 'Provide social security to 4 crore unorganised sector workers by 2020. Ensure old-age income security to workers outside formal pension net.', 'Workers in unorganised sector aged 18-40', 2020, 10500.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (27, 'Pradhan Mantri Annadata Aay SanraksHan Abhiyan (PM-AASHA)', 'pm-aasha', 'Ministry of Agriculture & Farmers Welfare', 2018, 'Price Support Scheme (PSS)', 3, 'Scheme to ensure farmers get Minimum Support Price (MSP) for their produce. Comprises Price Support Scheme, Price Deficiency Payment Scheme, and Pilot of Private Procurement.', 'Ensure farmers get remunerative prices for their produce. Implement MSP across all notified crops. Prevent distress selling.', 'All farmers growing notified crops across India', 2024, 1500.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (39, 'PM Gati Shakti National Master Plan', 'pm-gati-shakti', 'Ministry of Commerce and Industry', 2021, 'National Infrastructure Pipeline (NIP)', 7, 'Digital platform to bring 16 ministries together for integrated planning and coordinated implementation of infrastructure connectivity projects. Aims to reduce logistics cost.', 'Integrate infrastructure planning across rail, road, ports, airports, waterways, logistics. Reduce logistics cost from 13% to 8% of GDP by 2030.', 'Infrastructure ministries; logistics industry; all businesses', 2030, 10000000.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (43, 'PM Daksh Yojana', 'pm-daksh', 'Ministry of Social Justice and Empowerment', 2021, NULL, 10, 'Scheme for upskilling of marginalised youth — SCs, OBCs, EBCs, DNTs, and sanitation workers. Provides short-term and long-term skill training with stipend and placement support.', 'Train 50,000 youth annually. Ensure 60% placement post training. Cover SCs, OBCs, EBCs, Safai Karamcharis, Denotified Tribes.', 'Marginalised youth: SCs, OBCs, EBCs, sanitation workers aged 18-45', 2026, 572.00);
INSERT INTO public.schemes (id, name, slug, ministry, launched_year, renamed_from, category_id, description, goals, target_beneficiaries, target_year, budget_crore) VALUES (17, 'Make in India', 'make-in-india', 'Department for Promotion of Industry and Internal Trade', 2014, NULL, 7, 'Initiative to facilitate investment, foster innovation, enhance skill development, protect intellectual property, and build best-in-class manufacturing infrastructure.', 'Increase manufacturing sector growth rate to 12-14% per annum. Increase share of manufacturing in GDP from 16% to 25% by 2025. Create 100 million additional jobs by 2022.', 'Domestic and foreign manufacturers; investors across 25 sectors', 2025, 197000.00);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (119, 1, 2025, '6/2025', 'In Chhattisgarh, against a projected demand of five lakh urban dwelling units under PMAY-Urban, only 2.07 lakh units had been completed as of April 2025; audit also noted delayed planning and substantial curtailment of sanctioned projects.', 'major', 'Completion of dwelling units against projected demand', 'Demand for five lakh dwelling units was projected in the approved Housing for All Plans of Action', '2.07 lakh dwelling units completed as of April 2025', 'dwelling units', 58.60, 'https://cag.gov.in/uploads/download_audit_report/2023/9_Chapter_II_PA_PMAY-U-06942922c9820d8.36265537.pdf', 'A total demand for 5 lakh Dwelling Units (DUs) was projected by the State Government in the approved Housing for All Plan of Action (HFAPOAs) prepared for 168 ULBs against which 2.49 lakh DUs (50 per cent of demand) were taken up for construction and 2.07 lakh DUs were completed as of  April 2025. We noticed that Housing for All Plan of Actions (HFAPOAs) were prepared and approved (April 2018 for 36 ULBs and February 2022 for 132 ULBs) by State Level Sanctioning and Monitoring Committee (SLSMC) with delay of three to six years of implementation of the scheme. Meanwhile, projects under AHP/BLC/ISSR verticals were sanctioned by the SLSMC and Central Sanctioning and Monitoring Committee (CSMC) for construction of 1.48 lakh DUs without preparation of HFAPOAs, Annual Implementation Plan (AIP) and finalisation of beneficiaries list indicating deficient planning. Approval of projects without identification and validation of beneficiaries led to curtailment of projects later on. During the period of 2015-16 to 2023-24, out of total sanctioned 75,164 DUs in Affordable Housing in Partnership (AHP) vertical, 37,067 DUs (49 per cent) have been curtailed/surrendered. Out of remaining 38,097 DUs, only 23,242 DUs (61 per cent) were completed as of April 2025. Similarly, out of total sanctioned 2.77 lakh houses in BLC vertical, 66,383 houses (24 per cent) were surrendered/curtailed, and out of remaining 2.11 lakh houses, 1.84 lakh houses (87 per cent) were completed.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (138, 4, 2024, '2/2024 (Tripura)', 'Audit found irregular disbursement of PM-KISAN benefits to ineligible persons, including government employees, income-tax payers and deceased beneficiaries, reflecting weaknesses in beneficiary validation and monitoring.', 'critical', 'Eligibility and accuracy of PM-KISAN beneficiary records and payments', 'Benefits were intended only for eligible farmer families meeting the scheme''s exclusion criteria.', 'Benefits were paid to multiple categories of ineligible beneficiaries, including government employees, income-tax payers and deceased persons.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Full-Report_Report-No.-2-of-2024_AR-2022-23_Govt.-of-Tripura-%281%29-0682c47183073f6.28112187.pdf', 'Scrutiny of the database of PM-KISAN revealed that 2,911 beneficiaries were found to be ineligible up to March 2023 due to various reasons (untraceable, not having land ownership, beneficiaries do not belong to State, retired or serving government employees, and other exclusion criteria). Out of 2,911 beneficiaries, 2,763 ineligible beneficiaries were extended the benefit amounting to Rs 4.18 crore, 127 beneficiaries did not receive any instalment and ineligibility of remaining 21 were revoked by the State Nodal Officer (SNO). Cross-check of the PM-KISAN database with the Human Resource Management System (HRMS) managed by the Finance Department, Government of Tripura revealed that 337 out of 2,44,072 beneficiaries were State Government employees (Group B and Group C).');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (18, 7, 2019, 'Report No. 14 of 2019', 'CAG found that only 3.66 crore out of 8 crore Ujjwala beneficiaries refilled their cylinders even once. 54% of LPG connections were effectively dormant by end of 2018.', 'critical', 'Cylinder refill rate (actual LPG usage)', '100% of connections actively used', '45.75% connections refilled at least once', 'percent active', 54.25, 'https://cag.gov.in/uploads/download_audit_report/2019/Report_No_14_of_2019_Performance_Audit_of_Pradhan_Mantri_Ujjwala_Yojana_Ministry_of_Petroleum_and_Natural_Gas_0.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (19, 7, 2019, 'Report No. 14 of 2019', 'Average LPG consumption by Ujjwala beneficiaries was 3.21 refills per year against national average of 7.7. Beneficiaries still using firewood due to cost of cylinder refill.', 'major', 'Annual LPG consumption per beneficiary', 'Similar to national average of 7.7 refills/year', '3.21 refills per year', 'refills/year', 58.30, 'https://cag.gov.in/uploads/download_audit_report/2019/Report_No_14_of_2019_Performance_Audit_of_Pradhan_Mantri_Ujjwala_Yojana_Ministry_of_Petroleum_and_Natural_Gas_0.pdf', 'Encouraging the sustained usage of LPG remains a big challenge as the annual average refill consumption of PMUY consumers on 31 December 2018 was only 3.21. Since the cost of refill has to be paid upfront by the BPL consumers, this has become a constraint in ensuring sustained usage of LPG.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (125, 2, 2024, '3/2024', 'The Jharkhand audit found that the SBM(U)-supported municipal solid-waste system was not fully streamlined, with deficiencies across planning, financing, IEC, segregation, collection, transportation, processing and final disposal.', 'major', 'End-to-end municipal solid-waste management in sampled ULBs', NULL, 'Audit test-checked 14 ULBs and found inadequate planning and institutional mechanisms, weak utilisation and monitoring of SWM funds, ineffective IEC activities, incomplete segregation and processing arrangements, and continued unsanitary disposal.', 'ULBs', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-No.-3-of-2024_SWM_JHR-English-%2822-05-2024%29-066acd68d100425.95459333.pdf', 'Under the Mission, the Urban Development and Housing Department (the Department), Government of Jharkhand (GoJ), was required to streamline and formalise Solid Waste Management (SWM) systems, through a systematic process, comprising of (i) waste segregation and storage at source (ii) primary collection (iii) secondary storage (iv) transportation (v) secondary segregation (vi) resource recovery (vii) processing and (viii) treatment and final disposal of the solid waste. Audit, however, noticed that the Solid Waste Management Plan (short and long term) were not being prepared, by any of the 14 test-checked ULBs.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (124, 2, 2024, '2/2024', 'The audit of solid waste management in Meghalaya identified weak institutional planning, inadequate achievement of service-level benchmarks, deficiencies in financial management, and continued open dumping.', 'major', 'Urban solid-waste planning, service delivery and scientific disposal under SBM(U)-aligned requirements', NULL, 'ULBs and state authorities had gaps in SWM plans, contingency planning, waste-generation assessment, informal-sector integration, segregation, processing and disposal, including open dumping.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/PA-on-Solid-Waste-Management-in-Urban-Areas-of-Meghalaya-for-the-year-ended-31-March-2022-066d1a92ed8cc34.24619201.pdf', 'Based on the analysis in the preceding paragraphs, Audit concludes that the function of Municipal Waste Management in the state of Meghalaya is severely hampered due to weak institutional mechanism that is manifested in none of the multiple agencies involved in this process being compliant with the responsibilities assigned to them under the Meghalaya SWM Rules. Waste Management Plans (either short term or long term) were not prepared in the test checked ULBs/Town Committee except for Shillong Municipal Area, where a City Solid Waste Action Plan had been prepared by the Shillong Municipal Board (SMB) but the same was still awaiting approval. These delays in preparation and approval of requisite legislations and plans had inhibited the implementation of SWM activities. Analysis of financial resources for the solid waste management in Meghalaya has brought out that over a period of previous five years, bulk of the financial resource Performance Audit on Solid Waste Management in Urban Areas of Meghalaya has been received under the Asian Development Bank’s external funded project of NERCCDIP. During the period from 2017-18 to 2021-22 in Meghalaya, the State Government heavily relied on external funding from Asian Development Bank and Central grants, while the budgetary support from the State budget as agencies’ own resources contributed only a minor share towards financing of Solid Waste Management activities. Test check of urban agglomerations revealed that significant portion (70 per cent to 98 per cent) of municipal waste ended up in landfills without any processing.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (143, 9, 2022, '2/2022', 'Performance audit of DDUGJY and Saubhagya in Mizoram found deficiencies in implementation of the schemes by the Power and Electricity Department.', 'major', 'Implementation of rural infrastructure and household electrification schemes', NULL, 'CAG identified deficiencies in planning, execution, financial management and monitoring.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-2%2C-2022%2C-Mizoram-068b15b26723bd1.26023217.pdf', 'Even though the State Government has stated 100 per cent (in excess of 100 per cent in case of Saubhagya Scheme) achievement of the broad objectives in terms of electrification of targeted number of villages, habitations and households, creation of electric infrastructure, etc., Audit observed that the schemes could have been more efficiently and economically implemented had due diligence been exercised in matters related to planning, execution and monitoring.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (245, 26, 2025, 'Report No. 9 of 2025', 'The audit found non-coverage of a considerable percentage of targeted beneficiaries under POSHAN Abhiyaan in Odisha.', 'major', 'Non-coverage of beneficiaries', '100 percent coverage', '73 to 94 percent coverage', 'percent', 6.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Audit-Report-No.-9_POSHAN_English-069cb9223a82218.76400442.pdf', 'Scrutiny revealed that the percentage of coverage of targeted beneficiaries under SNP ranged between 73 and 94 per cent during 2018-23.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (246, 26, 2025, 'Report No. 9 of 2025', 'A short delivery of wheat to Anganwadi Centres by the appointed Transport Agent was observed during the audit.', 'major', 'Short delivery of wheat by Transport Agent', '4,109 mt', '3,951 mt', 'metric tonnes', 3.85, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Audit-Report-No.-9_POSHAN_English-069cb9223a82218.76400442.pdf', 'Audit observed short delivery of 158 MT of wheat by Transport Agent during the period covered by audit.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (247, 26, 2025, 'Report No. 9 of 2025', 'Audit detected diversion of Take Home Ration (THR) funds for unrelated expenditure.', 'critical', 'Diversion of THR cost towards other expenditure', 'THR funds to be used only for THR supply', 'THR cost diverted to excess payment for SHG charges', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Audit-Report-No.-9_POSHAN_English-069cb9223a82218.76400442.pdf', 'Audit noticed diversion of THR cost amounting to ₹1.64 crore towards payment of processing and supervision charges to SHGs in excess of the admissible rates.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (248, 13, 2025, 'Report No. 20 of 2025', 'Bank account details on the Skill India Portal were missing, blank, null, or invalid for 90.66 lakh out of 95.90 lakh certified beneficiaries under PMKVY 2.0 and 3.0 — 94.53% of all records. Invalid entries included placeholder values such as ''11111111111'', ''123456'', single-digit numbers, and text/names/special characters. 12,122 account numbers were reused across 52,381 different candidates; one account number was shared by 2,106 individuals.', 'critical', 'Beneficiary data integrity — bank account records on Skill India Portal', '95.90 lakh certified candidates', '90.66 lakh (94.53%) had missing or invalid bank data', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-20-of-2025_PA-PMKVY_English-PDF-A-06943abec463479.68516873.pdf', 'Bank account details, which are mandatory for Direct Benefit Transfers, were missing, blank, marked Null/N/A, or filled with zeros in 94.53 per cent of 95.90 lakh beneficiary records under PMKVY 2.0 and 3.0. Among available records, 12,122 account numbers were repeated for at least 52,381 candidates; entries such as ''11111111111'', ''123456'', single-digit numbers, or fields populated with text, names or special characters were recorded.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (128, 2, 2025, '1/2025', 'The Uttar Pradesh audit found delayed and inadequate release and utilisation of SBM(U) funds, weak planning and capacity building, and poor performance in segregation, processing and scientific disposal.', 'critical', 'Release and utilisation of SBM(U) funds and achievement of urban solid-waste-management outcomes', 'Funds were to be released to ULBs under the SWM, capacity-building and IEC components in accordance with SBM(U) plans.', 'During 2016-22, the share of available SWM funds released to ULBs ranged from 0 to 63 percent; release under capacity building and administrative expenses ranged from 0 to 20 percent, while IEC and public-awareness releases ranged from 3 to 62 percent. Test-checked ULBs also had substantial unutilised balances and delays in State-level fund release.', 'percent', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-1-UP-Solid-Waste-Mgt_English-_signed_20-06-2025-0689b2a336d2085.44753065.pdf', 'Further, SWM plan was prepared in only three out of 45 test-checked Urban Local Bodies (ULBs). SWM related bye-laws were framed in only 12 ULBs out of 45 test-checked ULBs. The bye-laws framed by these ULBs lacked uniformity. Against proposed 112 training programmes for capacity building of human resources in ULBs, only 53 training programs were organised due to delay in administrative approval by the State Government and inadequate funding. During 2016-22, percentage of fund released to ULBs vis-a-vis available fund under SWM component ranged between zero and 63 per cent. Further, this percentage was zero to 20 per cent and three to 62 per cent respectively in Capacity Building and Administrative & Office Expenses (CB & AOE) and IEC&PA components, leaving a substantial unutilised balance during all years of the audit period at the level of State Mission Director (SMD), Swachh Bharat Mission (SBM) (Urban). Moreover, State Government had released funds to the SMD with a delay ranging from 55 to 236 days and 11 to 1,098 days under SWM and CB & AOE respectively. Test-checked ULBs were collecting and transporting mixed waste to the plant, landfill or dumpsite. No instances of source segregation were found during the public survey of households in the test-checked ULBs. At the State level between 26 to 71 per cent of waste was processed during the year 2016-22 out of the total waste collected and at the ULBs level, between zero to 63 per cent waste was processed during the year 2016-22. Operation and maintenance of solid waste processing plants were found deficient in test-checked ULBs. Quantity of legacy waste had increased due to lack of proper disposal of waste in ULBs.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (145, 9, 2022, '3/2022', 'Assam Power Distribution Company Limited did not undertake feeder-segregation works, and implementation suffered from delays, weak monitoring, irregular contracting and procurement of substandard items.', 'major', 'Feeder segregation and compliance with scheme implementation requirements', NULL, 'Feeder segregation was not undertaken, preventing achievement of the objective of optimum power rostering between agricultural and non-agricultural consumers.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/7%20Chapter%202-0632d764f7bfc45.35685450.pdf', 'The Company did not take up feeder segregation works resulting in non-achievement of the objective of optimum rostering of power between agricultural and non-agricultural consumers. Implementation of the scheme was also characterized by several instances of non-adherence to the scheme guidelines. There were instances of inefficiencies in contract management, execution of works and monitoring. Project implementation was beset with slow execution of works, weak monitoring, non-fulfilment of commitments made in the agreements, delays in award of contracts, irregular award of work, procurement of items of below standard etc.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (249, 13, 2025, 'Report No. 20 of 2025', 'Certified training was claimed by multiple defunct companies on the Skill India Portal. Radiate Designs (struck off by Registrar of Companies in 2015) certified 15,218 people. Neelima Moving Pictures (shut for 5–6 years) claimed to have trained 33,000 people. Present Media Private Limited certified 19,561 candidates as dancers, hairdressers, and makeup artists across nine states. At least one training partner (Jaipur Cultural Society) claimed to have conducted training on 31st February — a date that does not exist. Identical photographs were submitted as training evidence in multiple states simultaneously (Bihar, Uttar Pradesh, Maharashtra, Rajasthan).', 'critical', 'Ghost training centres and fraudulent certification', NULL, NULL, NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-20-of-2025_PA-PMKVY_English-PDF-A-06943abec463479.68516873.pdf', 'Field inspections revealed instances where training centres were found closed on dates SIP data indicated training was scheduled. Identical photographs were submitted as evidence for multiple beneficiaries across different states. Certifications were issued by entities struck off by the Registrar of Companies prior to the audit period.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (58, 32, 2023, 'Report No. 19 of 2023', 'CAG found only 7,662 km of the 34,800 km Phase I target was completed by June 2023, against the 2022 deadline. Project cost has escalated to Rs 10.64 lakh crore, nearly double the original Rs 5.35 lakh crore estimate.', 'critical', 'Construction progress vs targets', '34,800 km by 2022', '7,662 km by 2023', 'km completed', 78.00, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-19%2C-2023%2C-Union-Government-068b1756bd99986.27522696.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (59, 32, 2023, 'Report No. 19 of 2023', 'CAG found land acquisition was pending for 28% of project length. Rs 1.1 lakh crore paid to NHAI via market borrowings had created debt burden with annual interest of Rs 18,000 crore, raising sustainability concerns.', 'major', 'Land acquisition delays', 'Timely land acquisition', '28 percent land still unacquired', 'land acquisition completion', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-19-of-203--Bharatmala-English-064d5db7bc63c20.06754442.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (127, 2, 2024, '6/2024', 'The Assam audit found that the State''s draft urban solid-waste policy remained unapproved and that urban local bodies had significant deficiencies in planning, funding, processing and monitoring of waste-management activities.', 'major', 'State policy, funding and operational performance of urban solid-waste management', NULL, 'The draft Assam Urban SWM Policy, 2018 was still unapproved by March 2023; audit also identified deficiencies in fund position, human resources, waste management and monitoring, including problems with SBM(U)-funded organic-waste composting facilities.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Chapter-IV-0680f57900b68d2.52493300.pdf', 'The “Draft Assam Urban Solid Waste Management (SWM) Policy, 2018” was yet to be approved by the Government till March 2023 even after three years of submission by Director of Municipal Administration (DMA) and six years after notification of the SWM Rules, 2016.
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (146, 9, 2022, '5/2022', 'Karnataka''s implementation audit found incomplete and deficient Saubhagya works, including execution without sanctioned estimates, discrepancies in material inspection and excess payment to contractors.', 'major', 'Completion, authorization, quality control and payment accuracy for Saubhagya works', NULL, 'CAG found unauthorized execution, material-inspection discrepancies and excess payments during implementation.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/DDUGJY%20ENGLISHI%20ALL%20PAGES-0632ae0143d4311.31295081.pdf', '3.10 Execution of works under SAUBHAGYA
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (250, 13, 2025, 'Report No. 20 of 2025', 'Thousands of underage candidates were enrolled and certified in violation of PMKVY eligibility criteria. Over 52,000 candidates were certified as Group Farming Practitioners without meeting the minimum age requirement. Over 40,000 underage candidates were certified as Self-Employed Tailors. Similar violations were found across multiple other job roles. DBT incentive payments of ₹500 had not been received by 34 lakh certified candidates as of October 2024, despite the relevant phases having formally concluded. DBT was successful for only 18.44% of certified candidates as of 2023.', 'major', 'Underage enrolments and DBT payment failures', '95.90 lakh certified candidates to receive ₹500 DBT incentive', 'Only 18.44% received DBT in 2023; 34 lakh unpaid as of Oct 2024', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-20-of-2025_PA-PMKVY_English-PDF-A-06943abec463479.68516873.pdf', 'Despite minimum age and qualification requirements for various job roles, thousands of underage candidates were enrolled and certified. More than 52,000 candidates were certified as Group Farming Practitioners and over 40,000 as Self-Employed Tailors without meeting age criteria. DBT payments were processed for only 25.58 per cent of certified candidates, with successful payouts in just 18.44 per cent of cases as of 2023.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (130, 2, 2020, '5/2020', 'Only 22 per cent of funds were utilised by urban local bodies, resulting in delays in implementing solid waste management projects under Swachh Bharat Mission (Urban).', 'major', 'Utilisation of funds for SBM (Urban) solid waste management projects', NULL, '22 per cent of funds utilised', 'percent', 78.00, 'https://www.cag.gov.in/webroot/uploads/download_audit_report/2020/AG%20GSS%20Eng%2018-19-FULL_REPORT-05f8d5e095f1e93.70851670.pdf', 'As of March 2020, SLHPC approved DPRs worth Rs 863.8 crore for implementation of SWM in selected 18 ULBs, of which Rs 249.7 crore was received from central and state government. However due to delay in approval of DPRs, overall utilization had been meagre Rs 54.61 crore (22%). It is thus highly unlikely that SWM projects approved by SLHPC would be completed by the end of the Mission period (March 2021).');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (129, 1, 2023, '2/2023', 'The Housing for All Plan of Action was completed only in March 2022 instead of June 2016. Of the 13.92 lakh houses identified for urban poor households, 6.84 lakh did not receive the intended benefits because the State failed to obtain sanctions in time. Further, 2.66 lakh sanctioned houses remained incomplete after the mission period.', 'major', 'Coverage of identified urban housing demand under PMAY-U', 'Tamil Nadu identified a demand for 13.92 lakh houses for urban poor households.', '6.84 lakh identified houses were deprived of intended benefits because they were not sanctioned.', 'lakh dwelling units', 49.14, 'https://www.cag.gov.in/webroot/uploads/download_audit_report/2021/Government-of-Tamil-Nadu-Report-No.2-of-the-year-2023---Performance-Audit-on-Housing-for-Urban-Poor-%28English%29-065268212d8ea65.98788120.pdf', 'The Housing for All Plan of Action was completed only in March 2022 instead of June 2016. Of the 13.92 lakh houses identified for urban poor households, 6.84 lakh did not receive the intended benefits because the State failed to obtain sanctions in time. Further, 2.66 lakh sanctioned houses remained incomplete after the mission period.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (149, 9, 2024, '4/2024', 'Madhya Pradesh''s audit of Saubhagya found deficient project execution, excess expenditure and procurement, infrastructure created without connections, non-compliant solar power-pack installations and incorrect claims for cash awards and additional grants.', 'critical', 'Compliance, cost efficiency and achievement of household electrification outputs under Saubhagya', NULL, 'CAG found irregular awards, deficient execution, excess procurement and expenditure, infrastructure without service connections, and incorrect grant-related claims.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/DDUGJY_MP-Report-No4_English_04-12-2024_SignCopy-06764fa4f38cbe3.22455925.pdf', 'Deficient execution of Contract
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (166, 13, 2025, 'Report No. 20 of 2025', 'Out of 56 lakh candidates certified under the Short-Term Training and Special Projects components of PMKVY, only 23 lakh candidates were placed, representing 41 per cent placement.', 'critical', 'Placement of candidates certified under PMKVY', '56 lakh certified candidates', '23 lakh placed candidates', 'candidates', 58.93, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-20-of-2025_PA-PMKVY_English-PDF-A-06943abec463479.68516873.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (82, 54, 2025, 'Report No. 17 of 2025', 'CAG found government''s claim of electrifying all 18,452 villages used a definition requiring only 10% of households to have power. Actual household electrification was 77% at the time of the ODF declaration. 3.3 crore households in "electrified" villages had no connection.', 'critical', 'Village electrification vs household access', 'All villages electrified', 'Only 10% households needed for "electrified" status', 'definition used', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/REPORT-NO-17--of-2025-_English-06944e9f0974b28.79742615.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (83, 54, 2025, 'Report No. 17 of 2025', 'CAG survey in 21 states found rural households received average of 12.5 hours electricity per day despite target of 24 hours. In UP, Bihar and Jharkhand, average supply was 6-8 hours. Rs 2,300 crore of infrastructure was stranded due to state DISCOM non-payment.', 'critical', 'Supply quality and hours in rural areas', '24 hours electricity supply', '12.5 hours average supply', 'hours per day', 47.90, 'https://cag.gov.in/uploads/download_audit_report/2025/REPORT-NO-17--of-2025-_English-06944e9f0974b28.79742615.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (133, 3, 2025, '4/2025', 'The audit found substantial shortfalls in beneficiary verification and coverage under AB-PMJAY in Bihar. Against the revised target of 61.8 million beneficiaries, only 25.6 million had been verified by 31 March 2024. In addition, 595 villages with eligible beneficiaries had no Ayushman Cards issued.', 'major', 'AB-PMJAY beneficiary verification and coverage', 'Coverage target of 12.1 million beneficiary families, representing approximately 61.8 million beneficiaries', 'Only 25.6 million beneficiaries verified by 31 March 2024; 595 eligible villages had no Ayushman Card holders', 'beneficiaries; villages', 58.60, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Performance-Audit---Civil---Report---4-of-2025--English-069a01619c584d8.44750365.pdf', 'The PMJAY scheme aimed to provide health cover to all the targeted 1.21 crore beneficiary families of the State. Audit noted that against the revised target of 6.18 crore beneficiaries, only 2.56 crore beneficiaries (41 per cent) were verified by the State as on 31 March 2024. Further, 595 villages having eligible beneficiaries had no Ayushman Cards issued.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (153, 10, 2025, '7/2025', 'Punjab reported achieving functional tap connections for 100 per cent of rural households, but CAG found inaccurate and unstructured Annual Action Plans, unrealistic targets, underutilisation of funds, inadequate sustainability measures, weak operation and maintenance arrangements, and insufficient water-quality monitoring.', 'major', 'Functional Household Tap Connection coverage and scheme implementation', '100 per cent rural household coverage by 5 April 2023', 'The reported achievement could not be reliably supported because planning data were inaccurate and key implementation and monitoring deficiencies persisted', 'per cent of rural households', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/05-Chapter-II-069b809d2b456d2.05748827.pdf', 'The implementation of the Jal Jeevan Mission (JJM) in Punjab encountered several structural and operational challenges. Annual Action Plans were inaccurate and unstructured, failing to account for households already having drinking water access. This led to underutilisation of funds, inability to meet utilisation thresholds and delays in Utilisation Certificates, hindering further release of Central Share. There was an absence of critical planning tools like the State Action Plan (SAP), resulting in unrealistic targets. Over-reliance on over-exploited groundwater with limited adoption of sustainability measures was noticed. Lack of a formal O&M strategy and inadequate handover of schemes to Village Water and Sanitation Committees (VWSC) was observed. Insufficient Block-Level Laboratories and shortage of trained human resources led to inadequate water quality monitoring. Punjab reported to have achieved the JJM target of providing functional tap connections to 100 per cent rural households by 5 April 2023.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (12, 4, 2022, 'Report No. 5 of 2022', 'Payments made to 2.75 lakh deceased farmers: Rs 270 crore transferred to accounts of farmers who had already died, indicating lack of database maintenance.', 'major', 'Dead farmer payments', 'No payments to deceased', 'Rs 270 crore to 2.75 lakh deceased', 'crore', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Report-no---5--ENGLISH-All-page-0639c1cd5094d73.67698090.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (27, 11, 2017, 'Report No. 39 of 2017', 'Of the 97 sewage treatment plant (STP) projects, only 46 were completed and functional by 2022. 23 STPs non-operational despite being shown as complete. Total sewage untreated remained 9,000 MLD per day.', 'critical', 'STPs operational vs planned', '97 STPs operational', '46 STPs functional; 9,000 MLD untreated sewage', 'STPs', 52.58, 'https://cag.gov.in/webroot/uploads/download_audit_report/2017/Report_No.39_of_2017_-_Performance_Audit_on_Ministry_of_Water_Resources%2C_River_Development_%26_Ganga_Rejuvenation_Union_Government.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (28, 11, 2017, 'Report No. 39 of 2017', 'Industrial effluent discharge uncontrolled: Only 215 of 764 grossly polluting industries along Ganga were compliant with discharge norms. 72% of polluters continued dumping untreated waste.', 'major', 'Industrial compliance with discharge norms', 'All industries compliant', '28% industries compliant', 'percent', 72.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2017/Report_No.39_of_2017_-_Performance_Audit_on_Ministry_of_Water_Resources%2C_River_Development_%26_Ganga_Rejuvenation_Union_Government.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (135, 4, 2023, '2/2023 (Meghalaya)', 'Audit identified irregular payment of PM-KISAN benefits to the same beneficiaries through the same bank accounts, indicating duplicate or inadequately controlled disbursements.', 'major', 'Uniqueness and validity of beneficiary-bank-account payments', 'Benefits were intended for eligible farmer families, with one family receiving the prescribed benefit.', 'Payments were recorded for the same beneficiaries using the same bank accounts.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-2%2C-2023%2C-Meghalaya-068b16c152046d3.77805602.pdf', 'The report stated that these deficiencies resulted in the extension of scheme benefits to ineligible beneficiaries such as disbursement to both husband and wife, double payment to the same beneficiaries and transfer of benefits to multiple beneficiaries with the same bank account.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (154, 10, 2026, '2/2026', 'In Chhattisgarh, deficiencies in planning, fund management, scheme execution and water-quality monitoring resulted in non-achievement of the Jal Jeevan Mission''s primary output and intended outcomes.', 'critical', 'Achievement of programme output and outcome', NULL, 'The primary output and outcome targets were not achieved; CAG also found mismatched data, delayed or short fund transfers, excess payments and shortfalls in water-quality testing', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2026/Final-PDF-of-Report-No--2-of-2026__English-06a55ff1aa79c09.72753680.pdf', 'Chhattisgarh was lagging in achieving the target and even though achievement of FHTC was 78 per cent as of March 2024, the schemes were in progress and not yet completed. Hence, the programme objective i.e. key output of delivering drinking water at the doorstep of every rural HHs has not been fully achieved.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (8, 3, 2023, 'Report No. 11 of 2023', 'CAG found significant data quality issues in the beneficiary database. In 7 sample states, 7.49 lakh beneficiary families were found ineligible or duplicate, yet they received benefits worth Rs 491 crore.', 'critical', 'Beneficiary database integrity', 'Only eligible families covered', '7.49 lakh ineligible families benefited', 'lakh families', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-11-of-2023_PA-on-PMJAY_English-PDF-A-064d22bab2b83b5.38721048.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (10, 3, 2023, 'Report No. 11 of 2023', 'Only 2.95 crore of the targeted 10 crore families had been issued Ayushman cards as of 2022. Coverage of intended beneficiaries was only 29.5%.', 'major', 'Beneficiary card issuance', '10 crore families covered', '2.95 crore families with active cards', 'crore families', 70.50, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-11-of-2023_PA-on-PMJAY_English-PDF-A-064d22bab2b83b5.38721048.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (9, 3, 2023, 'Report No. 11 of 2023', 'Hospitals empanelled under PMJAY performed fraudulent claims. CAG identified 7,491 suspicious transactions worth Rs 88.36 crore — payments made after patient death, treatments impossible in the empanelled facility type.', 'critical', 'Claims fraud prevention', 'Zero fraudulent claims', 'Rs 88.36 crore in fraudulent claims detected', 'crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-11-of-2023_PA-on-PMJAY_English-PDF-A-064d22bab2b83b5.38721048.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (118, 1, 2022, '2/2022', 'In Puducherry, although 44,315 beneficiaries were found eligible for the PMAY-Urban Beneficiary Led Construction component, benefits were provided to only 14,826, denying assistance to 29,489 eligible beneficiaries.', 'critical', 'Coverage of eligible beneficiaries', '44,315 beneficiaries were eligible for the scheme', 'Only 14,826 eligible beneficiaries received scheme benefits', 'beneficiaries', 66.50, 'https://cag.gov.in/en/audit-report/details/118540', 'Compliance Audit on Implementation of Beneficiary Led Construction component of Pradhan Mantri Awas Yojana (PMAY) – Urban by the UT of Puducherry revealed that even though 44,315 beneficiaries were found to be eligible for the scheme, the scheme was implemented only to 14,826 beneficiaries, thereby denying the scheme benefits to 29,489 beneficiaries.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (117, 1, 2022, '4/2022', 'In Karnataka, only 88,395 dwelling units were completed out of 517,531 approved units under the AHP and BLC components, leaving most approved houses incomplete and making the Housing for All by 2022 objective unlikely to be achieved.', 'critical', 'Completion of approved dwelling units', 'Housing for All by 2022', '88,395 of 517,531 approved dwelling units completed as of March 2021', 'dwelling units', 82.90, 'https://cag.gov.in/uploads/download_audit_report/2021/6%20Executive%20Summary-0632ad57ae8cdb8.76458198.pdf', 'As of March 2021, under AHP and BLC verticals, projects were taken up only for 5,17,531 beneficiaries out of the 13,71,592 prospective beneficiaries (38 per cent) identified through demand survey. As against the approved 5,17,531 DUs, only 88,395 DUs (17 per cent) were completed as of March 2021. The construction of 3,28,499 DUs (63 per cent) were yet (March 2021) to be commenced indicating that achieving the mission goal of ‘Housing for All’ by 2022 was a difficult prospect.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (122, 2, 2022, '2/2022', 'The performance audit of SBM in Arunachal Pradesh found deficiencies in implementation of the urban component, including failure to prepare project reports or DPRs for public and community toilets.', 'major', 'Planning and implementation of SBM(U) sanitation infrastructure', NULL, 'The Mission Director had not prepared project reports or DPRs for construction of public/community toilets; audit noted that universal access, ergonomic design and lower operation and maintenance costs could not therefore be assured.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-2-of-2022--Government-of-Arunachal-Pradesh-068b1284c3d3016.84630833.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (120, 1, 2023, '3/2023', 'In its district-centric audit of selected urban local bodies in Cuttack and Sambalpur districts, CAG reviewed implementation of Pradhan Mantri Awas Yojana (Urban) and observed that the State had limited implementation to the beneficiary-led subsidy component, leaving other PMAY-U components unimplemented in the audited urban areas.', 'major', 'Coverage and implementation of PMAY-U components in audited urban local bodies', NULL, 'The audited implementation was focused only on the subsidy/beneficiary-led housing component rather than the full set of PMAY-U verticals.', 'PMAY-U components', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Report-No-3-of-2023-%28English%29%2C-Local-Body-Audit-Report-0651c206273c003.18266522.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (121, 2, 2018, '4/2018', 'The audit found deficiencies in planning, institutional arrangements, fund utilisation, segregation, collection, processing and scientific disposal of municipal solid waste in urban local bodies.', 'major', 'Effectiveness and scientific management of municipal solid waste in urban local bodies', NULL, 'Urban local bodies had not fully established effective systems for waste assessment, segregation, collection, processing and disposal; audit also identified gaps in SBM-related planning and fund utilisation.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2018/Report_No_4_of_2018_Performance_Audit_of_Solid_Waste_Management_in_Urban_Local_Bodies_Government_of_Karnataka.pdf', 'We observed that until the preparation of DPRs, none of the test-checked ULBs assessed the requirement of capital and revenue funds for SWM activities and hence, they were unaware of the resource deficit. Based on JPVs, we found that segregation at source was not followed in 32 out of 35 test-checked ULBs and it was partially carried out in three test-checked ULBs (CC, Tumakuru, CMC, Dandeli and TMC, Kumta). As evident from above, 92 per cent of the waste was collected and only 26 per cent was processed each year and a major portion of the remaining MSW was dumped at landfills, which would have a harmful impact on health and environment.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (123, 2, 2022, '9/2022', 'Eleven urban local bodies did not receive the Central share of SBM-Urban funds because DPRs were not prepared and submitted on time.', 'major', 'Receipt of Central SBM-Urban funding by ULBs', NULL, 'Eleven ULBs did not receive Central assistance amounting to ₹45.82 crore.', 'crore INR', NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-9%2C-2022%2C-Kerala-068b144ae8bc652.06700870.pdf', 'Eleven ULBs did not receive Central share worth ₹45.82 crore, due to non-preparation and timely submission of DPRs.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (126, 2, 2024, '4/2024', 'The Uttarakhand audit found that urban local bodies had not established effective systems for waste planning, collection, transportation, processing and sanitary disposal.', 'major', 'Implementation of solid-waste management systems in urban local bodies', NULL, 'Deficiencies included ineffective baseline waste analysis, incomplete or defective DPRs, non-use of personal protective equipment, lack of systems for integrating informal waste workers, roadside dumping, open dumping due to unavailable sanitary landfill sites, and uncovered transport vehicles.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-No.-4-of-2024_PA-on-SWM-GoUK_English-067b719e9423de6.20500998.pdf', 'The State Government needs to devise systems to assist ULBs in preparation of Solid Waste Management plans/action plans for effective implementation of waste management and monitor their effective implementation.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (131, 2, 2022, '3/2022', 'The audit found major deficiencies in implementation of Individual Household Latrines and public toilets; only 10 per cent of constructed Individual Household Latrines were functional.', 'critical', 'Functionality of Individual Household Latrines constructed under SBM (Urban)', NULL, 'Only 10 per cent of constructed latrines were functional', 'percent', 90.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Report-No.-3-of-2022_Comnpliance_English-%2809-03-2023%29%28new%29-06422d051c4bc68.09607613.pdf', 'Only 10 per cent of the IHHLs constructed were found functional.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (134, 4, 2023, '1/2023 (Haryana)', 'Improper identification, non-verification and weak monitoring resulted in PM-KISAN benefits being paid to ineligible recipients, including State Government pensioners; other ineligible payments were not adequately recovered.', 'critical', 'Value of PM-KISAN payments made to ineligible beneficiaries', 'The scheme was intended to provide ₹6,000 per year in three instalments only to eligible farmer families.', '₹131.40 lakh was disbursed to State Government pensioners; recovery of payments to other ineligible beneficiaries was also deficient.', '₹ lakh', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/Chapter-4_CAR-2_2020-21_ENG_Report-No.1-of-2023-0641d9dc8d9ae45.18448201.pdf', 'Due to improper identification, non-verification and lapses in monitoring of PM-KISAN scheme, benefits amounting to ` 131.40 lakh were disbursed to State Government Pensioners. Besides, there were non-recovery of amount disbursed to Income Tax payees and ineligible beneficiaries, benefits extended to more than one family member, benefits extended to beneficiaries who do not own agriculture land, benefits extended to the deceased beneficiaries, non-receipt of administrative expenses amounting ` 420.38 lakh, benefits released to the beneficiaries pending for Physical Verification, non-setting up of Project Monitoring Unit and non-achieving of target of physical verification.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (132, 2, 2026, '1/2026', 'An SBM (Urban) solid waste management project of Lumding Municipal Board remained unfruitful despite fund availability; inadequate follow-up and payment of an unsecured advance led to unfruitful expenditure of ₹30.51 lakh.', 'major', 'Completion and productive utilisation of the solid waste management project', NULL, '₹30.51 lakh incurred as unfruitful expenditure', 'lakh rupees', NULL, 'https://cag.gov.in/uploads/download_audit_report/2026/Chapter-VIII-06a1ea9914da168.72557599.pdf', '8.4.4 Unfruitful expenditure on Solid Waste Management project under Lumding Municipal Board remained unfruitful for years despite availability of funds under Swachh Bharat Mission-Urban. Lack of active pursuance compounded by payment of unsecured advance to the project contractor by the Lumding Municipal Board, resulted in an expenditure of ₹30.51 lakh remaining unfruitful.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (136, 4, 2023, '2/2023 (Manipur)', 'The subject-specific compliance audit found deficiencies in the implementation of PM-KISAN in Manipur, particularly in beneficiary identification, verification and payment controls.', 'major', 'Compliance of PM-KISAN beneficiary identification, verification and disbursement processes', 'The scheme was intended to transfer benefits only to verified farmer families owning cultivable land.', 'Audit identified shortcomings in implementation and compliance controls.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/Report-No.2-of-2023%2C-Govt.-of-Manipur-068b1610e7bff33.94559415.pdf', 'There were delays in processing of application forms of beneficiaries by two to 16 months. Records of the beneficiaries were not properly maintained in the selected districts.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (137, 4, 2024, '2/2024 (Assam)', 'The PM-KISAN implementation in Assam was affected by large-scale ineligible applications, weak monitoring, fake or multiple registrations and very limited recovery of funds paid to non-entitled beneficiaries.', 'critical', 'Recovery of PM-KISAN funds released to non-entitled beneficiaries', NULL, 'Only 0.24 percent of funds released to non-entitled beneficiaries had been recovered; approximately 35 percent of applicants were reported as ineligible.', 'percent', 99.76, 'https://cag.gov.in/uploads/download_audit_report/2024/06-Chapter-2-066d9895d42a428.15560919.pdf', 'Subsequently, the State Government declared that 11,72,685 (37 per cent) out of the 31,20,430 beneficiaries were ineligible through an inquiry conducted from May-July 2020 across the state. A mere 0.24 per cent of the funds released to these ineligible beneficiaries were received back till October 2021, which was not refunded to the Ministry of Agriculture and Farmers Welfare.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (139, 5, 2017, '1/2017', 'Haryana did not fully achieve the Beti Bachao Beti Padhao targets for improving the sex ratio at birth, increasing girls'' enrolment in secondary education, and re-enrolling 100 percent of girls who had dropped out.', 'major', 'Sex ratio at birth, girls'' secondary-school enrolment, and re-enrolment of dropout girls', 'Improvement in the sex ratio at birth, increased secondary-school enrolment of girls, and 100 percent re-enrolment of dropout girls', 'The targets were not fully achieved', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2017/Haryana_Report_1_of_2017_Non_PSUs_SGE_Sectors.pdf', 'Targets of ''Beti Bachao Beti Padhao'' of improving the sex ratio at birth, increasing girl’s enrollment in secondary education and 100 per cent re-enrolment of drop-out girls could not be fully achieved.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (142, 9, 2022, '2/2022', 'Performance audit of DDUGJY and Saubhagya in Tripura identified deficiencies in planning, implementation, household electrification, feeder separation, financial management and monitoring.', 'major', 'Implementation of rural electrification schemes and achievement of household electrification objectives', NULL, 'CAG reported significant implementation deficiencies across the audited scheme components.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-2-of-the-year-2022-%28Government-of-Tripura%29-068b153ad85c8e0.79389150.pdf', 'The Performance Audit of DDUGJY and Saubhagya in Tripura revealed deficiencies in planning, implementation, household electrification, feeder separation, financial management and monitoring.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (157, 2, 2024, 'Report No. 2 of 2024', 'The Government stated that grants received from the Ministry for Swachh Bharat Mission Urban Phase-I during 2014-2022 were ₹61.99 crore, while ₹85.30 crore was allocated for Swachh Bharat Mission 2.0.', 'major', 'SBM Urban funding', '₹61.99 crore received under SBM Urban Phase-I during 2014-2022', '₹85.30 crore allocated for SBM 2.0', '₹ crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/6-Chapter-2_SS-0682c47185b2c32.99556319.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (200, 37, 2020, 'Report No. 5 of the year 2020', 'ORMAS received ₹657.90 crore under DDU-GKY during 2014-19 and utilised ₹568.43 crore, representing 86 per cent utilisation as of March 2019.', 'minor', 'DDU-GKY fund utilisation', '₹657.90 crore received', '₹568.43 crore utilised', '₹ crore', 13.56, 'https://cag.gov.in/webroot/uploads/download_audit_report/2019/Para%202.2%20Implementation%20of%20Deen%20Dayal%20Upadhyaya%20Grameen%20Kaushalya-0615eba3b29d333.35528712.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (144, 9, 2022, '3/2022', 'In Jharkhand, 284,485 Saubhagya connections were released in seven test-checked districts against work orders for 406,196 connections, without ensuring assessment of beneficiaries eligible for free connections.', 'critical', 'Saubhagya household connections released versus connections covered by work orders', '406196', '284485', 'connections', 30.00, 'https://cag.gov.in/uploads/download_audit_report/2022/4%20Executive%20Summary-062f10466b93934.40045274.pdf', 'Under SAUBHAGYA, 2,84,485 connections were released in the seven test-checked districts against work order for providing 4,06,196 connections without ensuring assessment of beneficiaries eligible for free connections.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (147, 9, 2023, '2/2023', 'Arunachal Pradesh''s performance audit of DDUGJY and Saubhagya revealed several deficiencies in planning, execution, financial management and monitoring of rural electrification works.', 'major', 'Achievement of rural electrification and household-connection objectives', NULL, 'CAG reported deficiencies in implementation of both schemes.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Report-No.-2%2C-2023%2C-Arunachal-Pradesh-068b13f8fd9bef9.74614265.pdf', 'A Performance Audit of the Implementation of Deen Dayal Upadhyaya Gram Joyti Yojana and Saubhagya scheme in Arunachal Pradesh carried out covering the period from 2014-15 to 2020-21, revealed several deficiencies in implementation of programme/schemes which are highlighted below:');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (151, 9, 2025, '17/2025', 'The Union-level performance audit found systemic deficiencies in DDUGJY and Saubhagya implementation, including incomplete electrification, weak planning and monitoring, financial irregularities, inadequate quality assurance and failure to fully achieve scheme objectives.', 'critical', 'Achievement of rural infrastructure, household electrification, financial management and quality-assurance objectives', NULL, 'CAG identified deficiencies across implementation, financial management, quality assurance and monitoring of Saubhagya projects in test-checked States and Union Territories.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/REPORT-NO-17--of-2025-_English-06944e9f0974b28.79742615.pdf', 'The objective of strengthening and augmentation of sub-transmission & distribution infrastructure and feeder separation for reliable and quality power supply after electrification of un-electrified villages in rural areas was, therefore, partially achieved as the allocated budget outlay was insufficient to meet the objectives of DDUGJY scheme with respect to system strengthening and feeder separation.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (150, 9, 2025, '7/2025', 'Uttar Pradesh issued an indent for electrification of 1.70 crore un-electrified households, but REC approved only 1.22 crore connections; the audit also found that off-grid connections were omitted from DPRs and identified irregularities in execution and beneficiary selection.', 'critical', 'Households proposed for electrification versus connections approved under Saubhagya', '17000000', '12200000', 'households/connections', 28.20, 'https://cag.gov.in/uploads/download_audit_report/2025/Performance-Audit-on--DDUGJY-and-SAUBHAGYA-%28English%29-0695278b83bc989.78923668.pdf', 'Despite the clear mandate to include off-grid connections under the SAUBHAGYA scheme, the DPRs omitted such provisions.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (152, 10, 2023, '3/2023', 'Water-supply schemes, including NRDWP/Jal Jeevan Mission components, faced inadequate planning and financial sustainability; water charges amounting to ₹278.20 crore were not recovered.', 'major', 'Recovery of water charges', NULL, '₹278.20 crore remained unrecovered', '₹ crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/ENG_Complete_Report-No.3-Haryana_31.08.2023-064f0590172fe46.78486641.pdf', 'Non-recovery of water charges amounting ₹ 278.20 crore
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (155, 10, 2026, '2/2026', 'In Maharashtra, tap connections from private or own sources were included in Jal Jeevan Mission coverage even though their functionality was not established. In six test-checked districts, 9.64 lakh such connections were included in the dashboard total.', 'critical', 'Reported tap-connection coverage under JJM', '37.89 lakh tap connections shown on the JJM dashboard in six selected districts', '9.64 lakh connections were from private or own sources and could not be counted as verified JJM Functional Household Tap Connections', 'lakh tap connections', 25.45, 'https://cag.gov.in/uploads/download_audit_report/2026/6.-Executive-Summary-06a50a878c80396.60451856.pdf', 'At the State level, 27.74 lakh private tap connections were shown covered under JJM. In the selected six districts, JJM dashboard showed 37.89 lakh tap connections which included 9.64 lakh tap connection from private/own source which were yet to be covered under the JJM. Tap connections from private/ own source do not ensure functionality and hence cannot be counted as achievement of providing FHTC under JJM.');
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (156, 10, 2026, '5/2026', 'In Madhya Pradesh, CAG found systemic planning and implementation weaknesses, including absence of baseline surveys in all test-checked districts, deficient action plans, non-prioritisation of villages, irregular expenditure, excess payments, delays, inadequate water-quality testing and failure to achieve programme outputs and outcomes.', 'critical', 'Planning, implementation and achievement of JJM outputs and outcomes', NULL, 'Baseline surveys were not conducted in any test-checked district and significant deficiencies affected planning, fund management, construction, monitoring and water-quality assurance', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2026/MP-JJM-Report-No.-5-of-2026-Bhopal---English-06a674f93c3faf1.25493877.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (158, 2, 2025, 'Report No. 4 of the year 2025', 'Out of 18 test-checked ULBs, Detailed Project Reports were prepared by only six ULBs under ISWM/SBM 1.0 and 11 ULBs under SBM 2.0. In three test-checked ULBs where DPRs were prepared, the prescribed waste-generation assessment method was not followed.', 'major', 'Detailed Project Reports and waste-generation assessment under SBM', '18 test-checked ULBs', 'DPRs prepared by 6 ULBs under ISWM/SBM 1.0 and 11 ULBs under SBM 2.0', 'ULBs', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/executive-summary-06995ab7b207685.23870065.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (159, 3, 2024, 'Report No. 6 of the year 2024', 'Under Pradhan Mantri Jan Arogya Yojana (PMJAY), inordinate delay in payment of insurance claims to beneficiaries was noticed. A District Implementation Unit to support PMJAY and a combined state-level unit for anti-fraud, medical audit and vigilance with district-level officers were not formed.', 'major', 'Claims processing and programme governance', NULL, 'Inordinate delay in payment of insurance claims; required district and state-level implementation, anti-fraud, medical audit and vigilance units were not formed.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-No.-6%2C-2024%2C-Kerala-06a2bd10de77a70.75432165.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (160, 2, 2024, 'Report No. 01 of 2024', 'In West Bengal, 13,709 metric tonnes of solid waste was generated per day during 2021-22 and 13,687 tonnes per day was collected, but only 3,047 tonnes per day, or 22.26 per cent of collected waste, was treated; the remaining 10,640 tonnes per day was unscientifically disposed of.', 'critical', 'Solid waste collection and treatment', NULL, 'Only 3,047 TPD of 13,687 TPD collected waste was treated; 10,640 TPD was unscientifically disposed of.', 'tonnes per day', 77.74, 'https://cag.gov.in/en/audit-report/details/125662', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (161, 2, 2025, 'Report No. 1 of 2025', 'Fourteen test-checked Urban Local Bodies in Telangana failed to fully utilise funds provided under Swachh Bharat Mission-Urban, leaving 37 per cent of the allocated funds unspent as of March 2022.', 'major', 'SBM-Urban fund utilisation', NULL, '37 per cent of allocated SBM-Urban funds remained unspent.', 'per cent of allocated funds', 37.00, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-of-CAG-of-India-on-Local-Bodies-for-the-period-ended-March-2022-English-version-069ca3f440fd237.20233929.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (162, 2, 2025, 'Report No. 5 of 2025', 'In Punjab during 2021-22, approximately 4,222 metric tonnes of solid waste was generated per day and 4,207 metric tonnes per day was collected, but only 1,471 metric tonnes per day was treated, leaving nearly two-thirds of collected waste untreated.', 'critical', 'Solid waste collection and treatment', NULL, 'Only 1,471 TPD of 4,207 TPD collected waste was treated.', 'tonnes per day', 65.02, 'https://cag.gov.in/uploads/download_audit_report/2022/REPORT-NO.-5-_PAU_SWM-_English-069b7f589571ed5.58982746.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (163, 5, 2019, 'Report No. 2 of 2019', 'The report’s table of funds directly transferred to State Implementing Agencies records ₹44.95 lakh released through one NGO for Beti Bachao Beti Padhao under the Social Welfare Department.', 'minor', 'Funds directly transferred to State Implementing Agencies', NULL, '₹44.95 lakh released through one NGO for Beti Bachao Beti Padhao', '₹ lakh', NULL, 'https://cag.gov.in/en/audit-report/details/87123', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (164, 10, 2025, 'Report No. 10 of 2025', 'Of the total 4,04,404 Functional Household Tap Connections disconnected during the audit period, 2,13,991 were disconnected within one month of being provided, indicating disinterest of beneficiaries in the scheme.', 'major', 'Sustainability and continuity of Functional Household Tap Connections', NULL, '2,13,991 of 4,04,404 disconnected connections were disconnected within one month', 'Functional Household Tap Connections', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/1.PA-on-JJM--English-0699d4ee1651af6.08263828.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (165, 11, 2025, 'Report No. 2 of 2025', 'The State Ganga Committee and State Mission for Clean Ganga did not plan and implement sewage treatment infrastructure in collaboration with local communities. Many Sewage Treatment Plants remained unconnected or only partially connected to household sewer networks, existing treatment capacity was insufficient, and significant quantities of untreated sewage were discharged into the Ganga. Eighteen STPs were not taken over by the maintenance agency because of operational and safety-related deficiencies.', 'critical', 'Sewage treatment infrastructure and operation of Sewage Treatment Plants', NULL, NULL, NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Report-No.-2-of-2025_Namami-Gange_UK_English-%2804-07-2025%29-069b020170bd314.74984302.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (167, 13, 2023, 'Report No. 3 of the year 2023', 'Failure of the Kerala Academy for Skills Excellence to ensure the genuineness of placement documents submitted by training partners resulted in undue financial benefit of ₹16.72 lakh to the training partners under PMKVY.', 'major', 'Verification of placement claims and placement-linked payments', NULL, '16.72 lakh undue financial benefit', '₹ lakh', NULL, 'https://cag.gov.in/en/audit-report/download/119630', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (168, 13, 2022, 'Report No. 2 of 2022', 'MSDE sanctioned ₹1,088.73 lakh under PMKVY for training and placement of 7,071 youths during 2017-18; the Department had incurred expenditure of ₹776.81 lakh as of 4 August 2019.', 'major', 'Utilisation of funds sanctioned for PMKVY training and placement', '1088.73', '776.81', '₹ lakh', 28.65, 'https://cag.gov.in/uploads/download_audit_report/2022/Report-No.-2%2C-2022%2C-Mizoram-068b15b26723bd1.26023217.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (169, 13, 2025, 'Report No. 3 of 2025', 'The audit found that adherence to PMKVY guidelines relating to biometric attendance, insurance of candidates, organising Kaushal Melas, and training linked to captive placements was not maintained or complied with; monitoring, inspection and internal control mechanisms were also ineffective.', 'major', 'PMKVY guideline compliance, monitoring and internal controls', NULL, NULL, NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/CAR--II-%282021-22%29-English-06932c5ef47ff10.28539780.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (170, 13, 2025, 'Report No. 3 of 2025', 'The report included a Subject Specific Compliance Audit on Pradhan Mantri Kaushal Vikas Yojana 2.0 under the Skill Development and Employment Department, Government of Uttarakhand.', 'major', 'PMKVY 2.0 compliance', NULL, NULL, NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-3-of-2025_CA-Civil_UK_English-%2809-09-2025%29-069b0249d4babf5.17738626.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (171, 15, 2021, 'Report No. 7 of 2021', 'There was no substantial role of Urban Local Bodies in implementation of the Smart Cities Mission in Punjab.', 'major', 'Urban Local Body participation in Smart Cities Mission implementation', NULL, 'No substantial role of Urban Local Bodies', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2021/Report%20No.%207%20of%202021_PA%20on%2074th%20CAA_English-062bd5610e610a5.58061202.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (172, 15, 2023, 'Report No. 2 of 2023', 'Out of 61 prioritised projects under Kohima Smart City Development, only 28 DPRs were completed, and only eight projects had been completed by October 2021. The audit also reported infructuous expenditure of ₹70.75 lakh on procurement of a water ATM and water tanker and ₹85.57 lakh on construction of a Multi Utility Duct.', 'critical', 'Project preparation and completion under Kohima Smart City Mission', '61 prioritised projects', '8 projects completed by October 2021', 'projects', 86.89, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Audit-Report-for-Year-ended-31-March-2022-065030884898d78.98617669.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (173, 15, 2024, 'Report No. 2 of the year 2024', 'Unfeasible projects were included among the 44 initially approved projects for Patna Smart City, resulting in delayed or incomplete execution. The audit also found poor contract management, mobilisation advance paid without finalisation of the scope of work, diversion of funds to unapproved projects and submission of incorrect utilisation certificates.', 'critical', 'Project planning, contract management and financial management', '44 initially approved projects', 'Unfeasible projects included, with delayed or incomplete execution', 'projects', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-no-2-ENGLISH--Compliance-Audit-Report-2022-for-24-%2829-06-2024%29-FINAL-FOR-PRINT-066a230fbc82fd2.20767913.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (174, 15, 2025, 'Report No. 11 of 2025', 'Against 135 goals specified in the Smart City Proposals of Karnataka''s smart cities, achievement was 68 goals; other projects were still in progress. Smart cities also dropped 161 of 544 originally planned projects, equivalent to 30 per cent, contrary to Ministry of Housing and Urban Affairs instructions.', 'critical', 'Achievement of Smart Cities Mission goals and project retention', '135 goals specified in the Smart City Proposals', '68 goals achieved', 'goals', 49.63, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/English-Print-final-06981dd464a8a09.83668109.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (175, 15, 2025, 'Report No. 5 of 2025', 'Dehradun Smart City Limited identified 33 projects valued at ₹1,359.80 crore under the revised Smart City Proposal, but only 22 projects valued at ₹1,021.54 crore were implemented under the Smart Cities Mission by March 2023. The audit further found that numerous smart solutions were dropped or remained non-functional and observed wasteful expenditure of ₹6.17 crore.', 'critical', 'Project implementation under Dehradun Smart Cities Mission', '33 projects', '22 projects implemented', 'projects', 33.33, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-05-Smart-Cities-UK---19-11-2025-signed-069b02aa24e1a16.54541284.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (176, 16, 2023, 'Report No. 16 of 2023', 'BSNL procured 6,000 Aadhaar Enrolment Kits during 2018-19 at a cost of ₹77.88 crore; 3,941 kits remained non-operational up to December 2022, blocking Government funds of ₹51.15 crore. UIDAI also imposed a disincentive of ₹0.65 crore on BSNL.', 'major', 'Aadhaar enrolment infrastructure and kit utilisation', '6000', '3941 non-operational kits', 'kits', 65.68, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.-16-of-2023_F%26C_English_DSC-064d3a3ea2200e4.24790196.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (177, 18, 2025, 'Report No. 4 of 2025', 'The State Urban Development Agency reported that Mission cities had achieved 36-37 reform milestones, whereas Audit found that only 15-16 milestones had actually been achieved.', 'major', 'AMRUT reform milestones achieved', '36-37 milestones', '15-16 milestones', 'milestones', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Full_English_AR_2021-22-0687a1a6b4e9719.81037180.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (178, 18, 2025, 'Report No.7 of 2025', 'Although the primary objective of AMRUT was universal coverage in water supply, none of the nine mission cities achieved this objective as of October 2024. Household water-supply coverage ranged from 9.39 per cent to 89.16 per cent.', 'major', 'Household water-supply coverage', 'Universal coverage', '9.39% to 89.16% across the nine mission cities; none achieved universal coverage', 'percent of households', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/CHAPTER-IV---PROJECT-IMPLEMENTATION-0699d30255af021.03377366.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (179, 13, 2022, 'No. 24 of 2022', 'The report showed a budget allocation of ₹2,676.65 crore for Pradhan Mantri Kaushal Vikas Yojana against expenditure of ₹2,112.67 crore, resulting in savings of ₹563.98 crore, or 21.07 per cent of the allocation.', 'major', 'Budget allocation and expenditure under PMKVY', '2676.65', '2112.67', '₹ crore', 21.07, 'https://cag.gov.in/uploads/download_audit_report/2022/Final-Report-English-063a19ffa5daa99.59624873.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (180, 16, 2026, 'Report No. 5 of 2026', 'The audit reviewed implementation of the Common Service Centres 2.0 Project under the Digital India Programme and reported shortcomings in the delivery of the project’s intended last-mile digital services.', 'major', 'Implementation of Common Service Centres 2.0 Project', 'Establishment of 2.5 lakh Common Service Centres at Gram Panchayat level', NULL, 'Common Service Centres', NULL, 'https://cag.gov.in/uploads/media/Report-No-5-of-2026-Union-Government-FC-English-069ce328181a951-43720339.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (181, 16, 2025, 'Report No. 1 of 2025', 'The audit examined the National Knowledge Network Project, a MeitY project associated with the Digital India ecosystem. The project had been approved with an outlay of ₹5,990 crore to connect 1,500 institutions.', 'major', 'National Knowledge Network connectivity', '₹5,990 crore outlay to connect 1,500 institutions', NULL, 'crore; institutions', NULL, 'https://cag.gov.in/uploads/media/Report-No-1-of-2025-Compliance-English-digitized-067eccf7929f917-22606952.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (182, 16, 2022, 'Report No. 15 of 2022', 'The audit reported idling of Aadhaar enrolment kits in Post Office Aadhaar Centres while examining the Department of Posts’ IT Modernisation Project and related digital service infrastructure.', 'major', 'Utilisation of Aadhaar enrolment kits', NULL, 'Aadhaar enrolment kits were idle in Post Office Aadhaar Centres', 'enrolment kits', NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Report%20No.%2015%20of%202022%20Union%20Govt._%20CA%20digital%20sign-062f0f478add833.76450548.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (183, 19, 2024, 'Report No. 8 of 2024', 'The Management’s decision not to upload Phase-I and Phase-II NITs on the PMGSY portal as prescribed in the Standard Bidding Document limited bidder participation: an average of two/three bidders participated in Phase-I and Phase-II, whereas six bidders participated in Phase-III.', 'major', 'Tendering and bidder participation', 'Two/three bidders participated on average in Phase-I and Phase-II', 'Six bidders participated in Phase-III', 'bidders', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2024/Final-Report-No.08-MP-English---25.11.2024-signed-06764038458ad31.02667470.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (184, 24, 2018, 'Report No.4 of 2018', 'Over 12 per cent of the 24.95 lakh pregnant women registered for Ante Natal Care did not receive Iron and Folic Acid tablets.', 'major', 'National Health Mission maternal health services', '24.95 lakh pregnant women registered for Ante Natal Care', 'Over 12 per cent did not receive Iron and Folic Acid tablets', 'pregnant women', 12.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2017/Chapter_2_Health_and_Family_Welfare_Department_of_Report_No_4_of_2018_-_General_and_Social_Sector_Government_of_Kerala.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (226, 57, 2024, '4 of 2024', 'For ₹189 crore released by the Government of India during 2016-17 to 2021-22 for the National Rurban Mission, utilisation certificates for ₹45.71 crore had not been submitted as of September 2023.', 'major', 'Utilisation certificates for National Rurban Mission funds', '189', '45.71', '₹ crore', 24.19, 'https://cag.gov.in/en/audit-report/download/120912', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (185, 24, 2017, 'Report No.25 of 2017', 'State Health Societies spent ₹1,06,179.78 crore out of ₹1,10,930.30 crore available during 2011-16 under the National Rural Health Mission.', 'major', 'National Rural Health Mission fund utilisation', '₹1,10,930.30 crore available', '₹1,06,179.78 crore spent', '₹ crore', 4.28, 'https://www.cag.gov.in/webroot/uploads/download_audit_report/2017/Chapter_2_-_Fund_management_of_Report_No.25_of_2017_-_Performance_audit_Union_Government_Reproductive_and_Child_Health_under_National_Rural_Health_Mission_Reports_of_Ministry_of_Health_and_Family_Welfa.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (186, 24, 2024, 'Report No. 02 of the year 2024', 'The Government of India and the Government of Chhattisgarh allocated ₹7,263.47 crore to the National Health Mission during 2016-22, of which ₹6,486.08 crore, or 89.30 per cent, was spent.', 'major', 'National Health Mission budget utilisation', '₹7,263.47 crore allocated', '₹6,486.08 crore spent', '₹ crore', 10.70, 'https://cag.gov.in/uploads/download_audit_report/2024/Full_English_PHIMS-066a38e83d51cd7.42146357.pdf', NULL);
