INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (188, 16, 2021, 'Report No. 3 of 2021', 'Deficient planning, delayed implementation and non-resolution of issues in the project for providing broadband connectivity to 2,500 Common Services Centres in the North East and other inaccessible regions led to sub-optimal use and idling of equipment. Expenditure of ₹8.63 crore on installation of VSAT equipment and ₹26.46 crore on operating expenditure was rendered unfruitful.', 'major', 'Common Services Centres broadband connectivity project', '₹49.88 crore approved project outlay', '₹35.09 crore rendered unfruitful, comprising ₹8.63 crore for VSAT equipment and ₹26.46 crore for operating expenditure', '₹ crore', 70.35, 'https://cag.gov.in/uploads/download_audit_report/2021/8%20Chapter%204%20-%20MeitY-061a4c2fd6f1778.99980192.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (189, 25, 2017, 'Report No. 3 of 2017', 'In the exit conference, the Principal Secretary stated that Mission Indradhanush was conducted in high- and medium-priority districts to close immunisation gaps during 2015-16 and 2016-17.', 'minor', 'Mission Indradhanush implementation and immunisation-gap closure', NULL, NULL, NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2017/Chapter_2_Performance_Audits_MP_Report_3_of_2017.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (190, 25, 2018, 'Report No. 4 of 2018', 'The State had achieved the target of 100 per cent immunisation of children in the 0-1 year age group, including coverage of dropout children through Mission Indradhanush.', 'minor', 'Immunisation coverage of children aged 0-1 years', '100', '100', 'percent', 0.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2018/Report_No_4_of_2018_-_General_%26_Social_Sector_Government_of_Telangana.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (191, 28, 2025, '5 of 2025', 'The utilisation of funds ranged between 44 and 50 per cent under the Samagra Shiksha Scheme.', 'major', 'Samagra Shiksha fund utilisation', NULL, 'Fund utilisation ranged between 44 and 50 per cent', 'per cent', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/Ex-Summary-06938179c532cb0.75644204.pdf', NULL);
