INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (193, 28, 2026, '03 of 2026', 'Major components of Samagra Shiksha were not implemented in the test-checked districts for want of funds. Strengthening of existing schools was not undertaken in Bankura during 2019-20 to 2023-24, in Uttar Dinajpur during 2020-21 to 2023-24, in Murshidabad during 2020-21 and 2023-24, and in Dakshin Dinajpur during 2019-20 to 2021-22.', 'major', 'Implementation of Samagra Shiksha components', NULL, 'Strengthening of existing schools was not implemented during the stated periods in four test-checked districts for want of funds', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Appendices-of-WB_Samagra-Shiksha_23-24-%28Report-No.-3-of-2026%29-06a68a451379cf8.69226023.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (194, 29, 2015, '36 of 2015', 'Enrolment of children in schools covered by the Mid-Day Meal Scheme declined consistently from 14.69 crore in 2009-10 to 13.87 crore in 2013-14; in contrast, private-school enrolment increased by 38 per cent from 4.02 crore to 5.53 crore.', 'major', 'Enrolment in Mid-Day Meal Scheme-covered schools', NULL, 'Enrolment declined from 14.69 crore children in 2009-10 to 13.87 crore children in 2013-14.', 'crore children', 5.58, 'https://cag.gov.in/uploads/download_audit_report/2015/Union_Performance_Civil_Mid_Day_Meal_Report_36_2015_2.pdf', NULL);
