INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (199, 37, 2018, 'Report No. 4 of the year 2018', 'The Punarjani skilling and placement project targeted training for 5,000 Kudumbashree workers but benefited only 1,794 members; the audit also found that Programme Implementation Agencies were not monitored by Kudumbashree, resulting in deficiencies in the scheme.', 'major', 'DDU-GKY-related skilling and placement outcomes', '5,000 members targeted', '1,794 members benefited', 'members', 64.12, 'https://cag.gov.in/uploads/download_audit_report/2017/Chapter_3_Local_Self_Government_Department_of_Report_No_4_of_2018_-_General_and_Social_Sector_Government_of_Kerala.pdf', NULL);
