INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (202, 41, 2025, 'Report No. 4 of 2025', 'As of 31 March 2023, only 98.78 MW of solar power Power Purchase Agreements had been signed under Component A of PM-KUSUM against the State target of 500 MW, and only 3 MW had been commissioned, representing less than one per cent of the target achievement.', 'major', 'PM-KUSUM Component A solar power capacity implementation', '500 MW', '3 MW commissioned', 'MW', 99.40, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/MP_CA-Commercial-Report-No-4-of-2025-in-English-06932ad13728417.36969035.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (203, 46, 2020, 'Report No. 1 of 2020', 'The failure to upload data pertaining to 7.15 lakh beneficiaries resulted in the Government of India refusing to include them in the Permanent Wait List, depriving them of a pucca house.', 'critical', 'Beneficiary identification and inclusion in the Permanent Wait List', NULL, '7.15 lakh beneficiaries were not included in the Permanent Wait List', 'beneficiaries', NULL, 'https://cag.gov.in/uploads/download_audit_report/2020/Chapter_2_Performance_Audit_of_Report_No_1_of_2020_General_and_Social_Sector_Government_of_Rajasthan.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (204, 46, 2023, 'Report No. 7 of 2023', 'Audit noted that 8.59 lakh eligible beneficiaries identified by Gram Sabhas were excluded from the Permanent Wait List, while 12.25 lakh beneficiaries could not be included in the list and were deprived of benefits under PMAY-G. The State also surrendered the target of 5.27 lakh houses due to non-availability of households in the Permanent Wait List.', 'critical', 'Beneficiary identification, Permanent Wait List and housing target achievement', '5.27 lakh houses were allotted as a target', '8.59 lakh eligible beneficiaries were excluded; 12.25 lakh beneficiaries were not included; the 5.27 lakh-house target was surrendered', 'beneficiaries and houses', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/Report-No.7-English-Local-Bodies-31.7.2023-signed---Copy-065c6066815de09.51627719.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (205, 46, 2025, 'Report No. 8 of 2025', 'The State completed construction of 34.18 lakh PMAY-G houses by March 2024 out of 34.71 lakh houses sanctioned during 2016-17 to 2022-23; deficiencies were observed in implementation of the scheme.', 'major', 'Construction completion of sanctioned PMAY-G houses', '34.71 lakh houses sanctioned', '34.18 lakh houses completed by March 2024', 'lakh houses', 1.53, 'https://cag.gov.in/uploads/download_audit_report/2025/Full_PA_PMAY-ReportNo-8_English_05-15-2025-signed-0694bb6ecc93c28.69875526.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (206, 47, 2017, 'Report No. 5 of 2017', 'Shortfall in achievement of targets was noticed: Individual Household Latrines for 2,14,647 households under Swachh Bharat Mission (Gramin) in Punjab were yet to be constructed despite availability of funds.', 'major', 'Individual Household Latrine construction', NULL, '2,14,647 households'' IHHLs remained unconstructed', 'households', NULL, 'https://cag.gov.in/uploads/download_audit_report/2017/Report_No_5_of_2017_-_Social_General_and_Economic_Sector_Government_of_Punjab.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (207, 47, 2018, 'Report No.1 of 2018', 'Planning and implementation of Swachh Bharat Mission (Gramin) by Uttarakhand was inadequate: against targets of 546 Community Sanitary Complexes and 4,485 Solid and Liquid Waste Management structures, only 63 and 50 respectively had been constructed up to March 2017.', 'critical', 'Community Sanitary Complexes and Solid and Liquid Waste Management structures', '546 Community Sanitary Complexes and 4,485 Solid and Liquid Waste Management structures', '63 Community Sanitary Complexes and 50 Solid and Liquid Waste Management structures constructed', 'structures', NULL, 'https://cag.gov.in/en/audit-report/download/47283', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (208, 47, 2017, 'Report No. 39 of 2017', 'The main objective of the rural sanitation programme to make all Ganga river basin villages Open Defecation Free under Swachh Bharat Mission (Gramin) could not be achieved. Audit also recommended that the reliability of data reported under the SBM (Gramin) Management Information System be ensured through cross-checking with monthly physical and financial reports.', 'major', 'Open Defecation Free status and rural sanitation monitoring', NULL, 'The objective of making all Ganga river basin villages Open Defecation Free was not achieved', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2017/Report_No.39_of_2017_-_Performance_Audit_on_Ministry_of_Water_Resources%2C_River_Development_%26_Ganga_Rejuvenation_Union_Government.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (209, 47, 2022, 'Report No. 2 of 2022', 'The objectives of Swachh Bharat Mission (Gramin) were not achieved by 2 October 2019 because all households without toilets were not included in the baseline survey. Consequently, the Department constructed 44,712 IHHLs in excess of the target set in the Project Implementation Plan during 2014-15 to 2019-20.', 'major', 'Baseline survey coverage and Individual Household Latrine construction', 'Target set in the Project Implementation Plan', '44,712 IHHLs constructed in excess of the Project Implementation Plan target', 'IHHLs', NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/Audit%20Report%202019-20-063295dfb834be1.69469104.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (210, 36, 2020, 'Report No. 7 of 2020', 'Audit found that ₹442.18 crore was incurred by CPSEs in aspirational districts under the common theme, representing 11.78 per cent of total CSR expenditure, and that only 55 CPSEs incurred CSR expenditure in aspirational districts.', 'major', 'Corporate Social Responsibility expenditure and participation in aspirational districts', NULL, '₹442.18 crore, or 11.78 per cent of total CSR expenditure, was incurred in aspirational districts; only 55 CPSEs incurred such expenditure.', '₹ crore; percent; CPSEs', NULL, 'https://cag.gov.in/uploads/download_audit_report/2020/Comml_CA_GPFR_Rep_No_7_2020_Chap_4-0602233901268a4.04267801.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (211, 36, 2022, 'Report No.10 of the year 2022', 'The Board did not have the data points specified in the NITI Aayog Aspirational District indicator framework. CAG observed that, without the required data, evaluation of the outcomes of the Board''s activities was not feasible and the Board could not demonstrate the effectiveness of its operations in measurable terms.', 'major', 'Availability and use of NITI Aayog Aspirational District indicators for monitoring and evaluation', NULL, 'Required data points under the NITI Aayog Aspirational District indicator framework were not available with the Board, preventing measurable evaluation of outcomes.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/KKRDB-Consolidated-Report-English-063f74dd7d48100.07216289.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (212, 36, 2026, 'Report No. 3 of 2026', 'The Cluster Facilitation Project, aimed at improving performance in aspirational districts, remained largely ineffective due to delays in operationalisation, under-deployment of Thematic Experts, and poor achievement of performance deliverables despite payment of ₹6.56 crore. Only 11 per cent of the Thematic Experts were appointed.', 'critical', 'Cluster Facilitation Project implementation and deployment of Thematic Experts', NULL, 'Only 11 per cent of Thematic Experts were appointed; the project remained largely ineffective despite payment of ₹6.56 crore.', 'percent; ₹ crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2026/Final-PDF-for-Report-No--3-of-2026_English-06a55ffb9953b80.12821263.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (213, 48, 2019, 'Report No. 5 of 2019', 'Under the Accelerated Irrigation Benefits Programme (AIBP), which was included as a component of PMKSY from 2015-16, 79,838 hectares of irrigation potential were due for creation within the committed timeframe, but only 55,516 hectares were created during 2013-18; 24,322 hectares remained pending at the end of March 2018.', 'major', 'Irrigation potential created under AIBP/PMKSY', '79838', '55516', 'hectares', 30.47, 'https://cag.gov.in/uploads/download_audit_report/2019/Chapter_5_Performance_Audit_on_PSUs_other_than_Power_Sector_of_Report_no_5_of_2019_PSU_Government_of_Karnataka.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (214, 49, 2021, 'Report No. 1 of 2021', 'Implementation of the Soil Health Card Scheme remained ineffective due to inefficient flow of funds, deficient planning for providing financial assistance for recommended nutrients, and non-planning for training and workshops.', 'major', 'Soil Health Card Scheme implementation', NULL, NULL, NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2019/06_Chapter%202_Part-I-062bd4e5f540b05.96015689.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (215, 49, 2019, 'Report No. 3 of the year 2019', 'Soil testing laboratories were underutilised, resulting in slow implementation of the Soil Health Cards Scheme; the shortfall in analysing soil samples ranged between 13.49 per cent and 45.92 per cent.', 'major', 'Soil sample analysis and soil testing laboratory utilisation', NULL, 'Shortfall in analysing soil samples ranged between 13.49 per cent and 45.92 per cent', 'percent', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2019/Report_no_3_of_2019_Social_General_and_Economic_Sector_%28Non_PSU%29_Government_of_Haryana.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (216, 52, 2024, 'Report 3 of 2024', 'Implementation of the Pradhan Mantri Matru Vandana Yojana (PMMVY), along with Janani Suraksha Yojana and Birth Waiting Home programmes, was affected by inadequate and untimely release of funds by the State Government. Consequently, intended benefits could not be provided to needy beneficiaries in time.', 'major', 'Timeliness and adequacy of fund release and delivery of PMMVY benefits', NULL, NULL, NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2024/Report-No.-3-of-2024--Performance-Audit-on-Public-Health-Infrastructure-and-Management-of-Health-Services-in-AP-0673fdc2a17e028.11698250.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (217, 52, 2024, 'Report No 4 of 2024', 'Funds of ₹65.20 crore received under PM Matru Vandana Yojana during 2017-18 were not utilised as of June 2022 and remained in the ESCROW account.', 'major', 'Utilisation and release of PMMVY funds', '₹65.20 crore received under PMMVY during 2017-18', '₹65.20 crore remained unutilised in the ESCROW account as of June 2022', '₹ crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2022/PA-PHMIS-ENGLISH-066ac6a43bfb790.63812312.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (218, 53, 2025, 'Report No. 5 of 2025', 'The Market Board received ₹138.94 crore from the Government of India during 2017-18 to 2021-22 for implementation of three centrally sponsored schemes, including Electronic National Agriculture Market (e-NAM).', 'minor', 'e-NAM funding received', NULL, '₹138.94 crore received for implementation of e-NAM, RKVY and Bundelkhand Package', '₹ crore', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/02_overview-%2828.03.2025%29-0689b314c6484e8.39199025.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (219, 54, 2022, '3 of 2022', 'Electrification of 819 (10 per cent) out of 7,925 villages taken up under DDUGJY was not completed as of March 2020. Further, 68,417 (32 per cent) out of 2,15,605 DDUGJY connections could not be provided.', 'critical', 'Village and household electrification', '7,925 villages and 2,15,605 connections', '819 villages and 68,417 connections remained incomplete/unprovided', 'villages and connections', 10.00, 'https://cag.gov.in/en/audit-report/details/116726', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (220, 54, 2022, '3 of 2022', 'Out of 2,339 unelectrified villages sanctioned under the scheme, APDCL electrified only 996 villages; the remaining 1,343 villages were found to be partially electrified while executing the scheme works.', 'critical', 'Village electrification', '2,339 villages', '996 villages electrified; 1,343 villages partially electrified', 'villages', 57.42, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Report%20No.%203%20of%202022_%28PSUs%202019-20%29_English_%2803-08-2022%29-0632d764ed773d8.55253332.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (221, 54, 2022, '7 of the year 2022', 'Infructuous expenditure of ₹1.18 crore was incurred on installations of M&P boxes under DDUGJY.', 'major', 'Project execution and expenditure', NULL, '₹1.18 crore of infructuous expenditure', 'INR crore', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/Report-No.-7-of-the-year-2022-Performance-Audit-on--Implementation-of-Deendayal-Upadhayaya-Gram-Jyoti-Yojana-in-Rajasthan-for-the-year-ended-31-March-2020-063fdc442597375.20524306.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (222, 54, 2022, '7 of the year 2022', 'The works for all 21 DDUGJY projects were awarded with delays ranging between 306 and 657 days, with an average delay of 470 days.', 'major', 'Project award and implementation delay', NULL, '306–657 days of delay, averaging 470 days', 'days', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/006_Chapter-2_Energy%20and%20Power%20-%20PSUs%20-%202020-21-062f3aa140b7835.44009910.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (223, 54, 2024, '04 of the year 2024', 'The audit identified deficiencies in DDUGJY implementation, including execution of work not conforming to Detailed Project Reports, failure to impose liquidated damages, delays in execution of projects, failure to realise additional grant, discrepancies in beneficiary data and closure reports, and deficiencies in project monitoring.', 'major', 'Project execution, financial management and monitoring', NULL, 'Deficiencies and control failures identified across DDUGJY projects', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2022/DDUGJY_MP-Report-No4_English_04-12-2024_SignCopy-06764fa4f38cbe3.22455925.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (224, 54, 2025, '7 of 2025', 'The objective of separating agriculture and non-agriculture feeders under DDUGJY was not achieved. The audit also reported avoidable expenditure due to execution of unnecessary items and double payment for installation of meters at consumers'' premises.', 'critical', 'Feeder separation and project expenditure', NULL, 'Feeder-separation objective not achieved; unnecessary works and double meter payments identified', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Performance-Audit-on--DDUGJY-and-SAUBHAGYA-%28English%29-0695278b83bc989.78923668.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (225, 56, 2023, 'Report No. 02 of the year 2023', 'After implementation of PMGKAY, 31.05 lakh NFSA-PHH beneficiaries with one to three members received no additional rice compared with their pre-PMGKAY entitlement. PHH card holders with more than three members received additional rice at three kg per person instead of the five kg per person envisaged under PMGKAY. Separate stock and distribution registers for PMGKAY were not maintained in 88 per cent of the test-checked Fair Price Shops.', 'major', 'Distribution of additional rice under PMGKAY through the Public Distribution System', 'Five kg of additional rice per person per month under PMGKAY', 'No additional rice for 31.05 lakh one-to-three-member NFSA-PHH beneficiaries; three kg per person instead of five kg for PHH households with more than three members; PMGKAY registers absent in 88 per cent of test-checked Fair Price Shops', 'kg per person per month; per cent of test-checked Fair Price Shops; beneficiaries in lakh', 40.00, 'https://cag.gov.in/webroot/uploads/download_audit_report/2023/English_Full_AR_2019-21-064ba56b27b7bc9.79918136.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (227, 51, 2013, 'Report No. 6 of 2013', 'Per rural household employment declined from 54 days in 2009-10 to 43 days in 2011-12.', 'major', 'Per rural household employment generation', '54', '43', 'days per rural household', 20.37, 'https://cag.gov.in/en/audit-report/details/704', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (228, 51, 2025, 'Report No.9 of 2025', 'Non-identification of beneficiaries by Gram Panchayats led to non-implementation of 88.73 per cent of individual projects included in the Annual Plan.', 'critical', 'Implementation of individual beneficiary projects', NULL, '88.73', 'percent of Annual Plan individual projects not implemented', 88.73, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Print-version_MGNREGA_%28English%29-14.01.2025-proof-print-mod-with-legislature-date-0699d38fe9768b3.68014422.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (229, 51, 2025, 'Report No.13 of the year 2025', 'Demand for employment from registered households did not exceed 48 per cent of the issued job cards during the audit period.', 'major', 'Household demand for MGNREGS employment', NULL, '48', 'percent of issued job cards', NULL, 'https://cag.gov.in/uploads/download_audit_report/2025/English-final-pdf-MGNREGS-with-signature-069c27a99698a17.10858290.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (230, 51, 2025, 'Report No. 6 of 2025', 'Although the scheme provides for 100 days of guaranteed employment, households provided employment received an average of 21 days per household per year during 2019-24.', 'critical', 'Employment days provided per household', '100', '21', 'days per household per year', 79.00, 'https://cag.gov.in/uploads/download_audit_report/2025/Report-No.-6-of-2025_PA-on-MGNAREGS_UK_English_signed-21-11-2025-069b03389eefe86.70319852.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (231, 51, 2026, 'Report No. 4 of 2026', 'Pending liabilities of wages and material amounted to ₹1,217.05 crore.', 'critical', 'Pending wage and material liabilities', NULL, '1217.05', 'crore rupees', NULL, 'https://cag.gov.in/uploads/download_audit_report/2026/MP-Report-No.-04-of-2026---MGNREGA--English-06a61c636798ce0.32200448.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (232, 33, 2025, '7 of 2025', 'Under the Sagarmala Programme, Andhra Pradesh proposed nine jetty projects and committed to bear 50 per cent of the project cost. Only one project, the Bhavani Island jetty, was approved; work was halted after execution of works worth ₹4.79 crore because the State did not release its ₹5 crore share. Of the remaining eight projects, revised DPRs were submitted for only three, while no decision was taken on the other five proposals.', 'major', 'Sagarmala jetty project implementation', '9 jetty projects proposed', '1 project approved; work halted after ₹4.79 crore of works, with 8 remaining proposals not completed', 'projects', 88.89, 'https://cag.gov.in/en/audit-report/details/124284', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (233, 8, 2022, 'Report No. 3 of 2022', 'Payment of financial assistance and pensions to beneficiaries continued through bearer cheques at the time of audit despite the Jan Dhan Scheme being implemented in Meghalaya, under which beneficiaries could open basic savings bank deposit accounts through bank branches or Business Correspondent outlets.', 'major', 'Payment channel for social assistance and pensions', NULL, 'Bearer-cheque payments continued at the time of audit despite implementation of the Jan Dhan Scheme.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2020/Report%20No.%203%20of%202022_S%26ES%202019-20_Meghalaya_%2821-6-2022%29-0632c13e348d7c0.85218927.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (234, 12, 2017, 'Report No. 7 of 2017', 'Despite three decades of Government of India efforts to provide crop insurance, coverage of farmers under the schemes continued to remain low; coverage of non-loanee farmers was particularly low because the schemes primarily targeted loanee farmers.', 'major', 'Farmer coverage, especially non-loanee farmer coverage', NULL, 'Overall farmer coverage remained low, with particularly low coverage among non-loanee farmers.', NULL, NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2017/Report_No.7_of_2017_-_Performance_audit_Union_Government_Agriculture_Crop_Insurance_Schemes_Reports_of_Agriculture_and_Farmers_Welfare.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (235, 12, 2022, 'Report No. 2 of 2022', 'The audit covered Pradhan Mantri Fasal Bima Yojana and Bangla Shasya Bima for 2016-17 to 2020-21. West Bengal continued the Government of India PMFBY scheme up to December 2018, implemented the same scheme with 100 per cent State assistance up to January 2019, and introduced the 100 per cent State-sponsored Bangla Shasya Bima scheme in February 2019.', 'major', 'Scheme implementation and transition from PMFBY to Bangla Shasya Bima', NULL, 'PMFBY implementation in West Bengal ended during the 2018-19 crop season, followed by State-funded implementation and then replacement by Bangla Shasya Bima.', NULL, NULL, 'https://cag.gov.in/uploads/download_audit_report/2021/Chapter-2-of-WB-CAR-2020-21-%28Report-No.-2-of-2022%29-06a68964ba82318.00207300.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (236, 17, 2020, 'No. 5 of 2020', 'The audit found that the automated system for the Merchandise Exports from India Scheme (MEIS) and Service Exports from India Scheme (SEIS), introduced under the Foreign Trade Policy 2015-20 with a Make in India vision, had shortcomings and required manual intervention. This caused avoidable physical interface and discretion, resulting in delays and failure to achieve simplification and ease-of-doing-business objectives. During April 2015 to October 2018, 5,94,653 scrips amounting to ₹76,416 crore were issued.', 'major', 'MEIS/SEIS export-incentive scrip issuance, automation and ease of doing business', NULL, '5,94,653 scrips amounting to ₹76,416 crore were issued; the audit found shortcomings and gaps in automation, manual intervention and resulting delays.', 'scrips; ₹ crore', NULL, 'https://cag.gov.in/en/audit-report/details/112155', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (237, 21, 2024, 'Report No. 06 of 2024', 'The State provided enhanced benefits of ₹2 lakh under PMJJBY and PMSBY to Anganwadi Workers and Anganwadi Helpers despite the Government of India notification issued in July 2018.', 'major', 'PMSBY insurance benefit provided to Anganwadi Workers and Anganwadi Helpers', NULL, 'Enhanced benefit of ₹2 lakh was provided despite the July 2018 Government of India notification.', 'rupees', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-No.-6%2C-2024%2C-Gujarat-06a2bc9f9831d02.41362501.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (238, 21, 2025, 'Report No.9 of 2025', 'During the beneficiary survey, 44.01 per cent of beneficiaries were not enrolled in any of the insurance schemes, including PM Suraksha Bima Yojana, indicating that the State had not fulfilled its responsibility to sensitise and enrol job-card holders.', 'major', 'Insurance coverage of MGNREGS workers', NULL, '44.01 per cent of surveyed beneficiaries were not enrolled in any insurance scheme.', 'percent of beneficiaries surveyed', 44.01, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Print-version_MGNREGA_%28English%29-14.01.2025-proof-print-mod-with-legislature-date-0699d38fe9768b3.68014422.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (239, 22, 2025, 'Report No. 02 of 2025', 'For Pradhanmantri Jeevan Jyoti Bima Yojana, ₹148.00 crore was allotted during 2017-22, but only ₹8.77 crore was expended, covering 204,843 beneficiaries.', 'major', 'BOCW fund allotment and expenditure under PMJJBY', '148.00', '8.77', '₹ crore', 94.07, 'https://cag.gov.in/uploads/download_audit_report/2022/17_Chapter_6--Utilisation-of-BOCW-Fund-1-0687a1e094b22c3.58805566.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (240, 22, 2024, 'Report No. 06 of 2024', 'The State offered enhanced PMJJBY and PMSBY benefits of ₹2 lakh to Anganwadi Workers and Anganwadi Helpers despite the Government of India notification issued in July 2018.', 'major', 'Insurance benefits for Anganwadi Workers and Anganwadi Helpers', '2 lakh', NULL, '₹ per beneficiary', NULL, 'https://cag.gov.in/uploads/download_audit_report/2024/Report-No.-6%2C-2024%2C-Gujarat-06a2bc9f9831d02.41362501.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (241, 39, 2024, 'Report No. 02 of 2024', 'Sixteen AC bills involving ₹62.04 crore, drawn on 31 March 2023 for construction of 13 jetties on the Hooghly River and three helipads in different districts for multimodal connectivity under Gati Shakti NMP, remained unadjusted till August 2023.', 'major', 'Adjustment of AC bills for multimodal connectivity works under Gati Shakti NMP', NULL, '₹62.04 crore remained unadjusted in 16 AC bills till August 2023', 'crore rupees', NULL, 'https://cag.gov.in/uploads/download_audit_report/2023/3H.-Chapter-IV_SFAR-2022-23-06a689dc6867121.95549310.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (242, 44, 2026, '5 of 2026', 'The number of transactions peaked in 2021-22 primarily because of 16.57 crore e-Shram registrations for the informal workforce; however, the effectiveness of the Common Service Centres 2.0 platform was constrained by incomplete integration of State e-services.', 'major', 'e-SHRAM registrations and integration of State e-services', '16.57 crore e-Shram registrations', 'Incomplete integration of State e-services constrained effectiveness', 'registrations; qualitative integration status', NULL, 'https://cag.gov.in/uploads/media/Report-No-5-of-2026-Union-Government-FC-English-069ce328181a951-43720339.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (243, 44, 2025, '6 of 2025', 'The Board had data for only 2,51,385 workers, whereas cross-verification with the e-Shram portal showed 20,97,593 unorganised workers across 29 categories, other than agriculture and construction workers, registered in Karnataka.', 'major', 'Coverage and completeness of the unorganised-worker database', '2,51,385 workers in the Board''s data', '20,97,593 workers registered on the e-Shram portal', 'workers', NULL, 'https://cag.gov.in/webroot/uploads/download_audit_report/2025/Compliance-Audit-Report-for-the-year-ended-March-2023-English-068a700dfe5c4f6.28455798.pdf', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (244, 44, 2025, '6 of 2025', 'The Government stated that 85.81 lakh workers were registered under the e-Shram portal, while registration of the remaining 59.19 lakh workers with the State welfare mechanism was still pending.', 'major', 'Registration of unorganised workers and convergence with State welfare schemes', '85.81 lakh workers registered under the e-Shram portal', '59.19 lakh workers remained to be registered with the State welfare mechanism', 'workers', NULL, 'https://cag.gov.in/en/audit-report/download/123588', NULL);
INSERT INTO public.cag_audits (id, scheme_id, report_year, report_number, finding, severity, parameter, claimed, actual, unit, gap_percent, source_url, report_excerpt) VALUES (140, 5, 2017, '1/2017', 'The audit included a dedicated compliance audit of the implementation of the Beti Bachao Beti Padhao Scheme in Uttarakhand and reported deficiencies in implementation.', 'major', 'Implementation of the Beti Bachao Beti Padhao Scheme', NULL, 'Deficiencies were identified in implementation', NULL, NULL, 'https://www.cag.gov.in/webroot/uploads/download_audit_report/2017/Uttarakhand_Report_No_1_of_2017.pdf', 'The number of paragraphs this year is 17 including 11 theme based compliance audit paragraphs viz., ‘Enforcement of Food Safety and Standards Act, 2006’, ‘Prevention of forest fires’, ‘Setting up of Private Universities’, ‘Horticulture Mission for North East and Himalayan States’, ‘Recovery of Loans and Government Dues by District Collectors’, ‘108 Emergency Response Service’, ‘Post Matric Scholarship to the students belonging to SC and OBC’, ‘Infrastructure Development for Tourist Destinations and Circuits’, ‘Setting up of projects of Sewage Treatment Plants under Jawaharlal Nehru National Urban Renewal Mission’, ‘Implementation of the Nirbhaya Scheme’ and ‘Implementation of Beti Bachao Beti Padhao Scheme’.');
