INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (36, 17, '2019-02-01', 'Manufacturing GDP share reaches 17.4%: Make in India on track', 'DPIIT claims manufacturing contribution to GDP has risen to 17.4%, progressing towards 25% target under Make in India initiative.', 'achievement', '17.4', 'percent of GDP', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=197782');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (115, 2, '2021-12-24', 'Roadmap launched for garbage-free urban India', 'MoHUA launched the Azadi@75 Star Rating Protocol of Garbage Free Cities toolkit to support SBM-U 2.0 implementation. The release said 299 cities had already received garbage-free certification, while the revised protocol aimed to bring every urban local body into the certification process.', 'launch', '299', 'cities certified as garbage free', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1784877');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (116, 2, '2022-04-07', 'SBM-U toilet construction and waste-processing progress reported', 'The Ministry reported that SBM-U had exceeded its toilet-construction targets for both individual household latrines and community or public toilets. It also stated that municipal solid-waste processing had risen to more than 72 percent and described SBM-U 2.0 measures for achieving garbage-free cities.', 'achievement', '72', 'percent of municipal solid waste processed', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1814401');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (117, 2, '2023-04-06', 'Urban waste processing reaches 75 percent', 'The release stated that urban local bodies were processing 1.14 lakh metric tonnes of municipal waste per day out of approximately 1.5 lakh metric tonnes generated. It linked the progress to SBM-U 2.0 objectives covering source segregation, door-to-door collection and remediation of legacy dumpsites.', 'achievement', '75', 'percent of municipal solid waste processed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1914186');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (118, 2, '2023-07-31', 'SBM-U 2.0 implementation and funding reviewed', 'MoHUA described its monitoring arrangements for sanitation and waste management through Swachh Survekshan, ODF and garbage-free certifications, reviews and digital portals. The release also reported earmarked additional central assistance for used-water management and solid-waste management components.', 'update', '15883', 'crore rupees earmarked for used-water management', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1944255');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (119, 2, '2024-12-27', 'Urban sanitation workers highlighted as SBM-U change agents', 'The release described toilet caretakers and sanitation workers as important contributors to SBM-U outcomes. Their work includes maintaining public toilets, encouraging hygiene, managing waste and engaging communities in better sanitation practices.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2088430');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (120, 2, '2025-02-06', 'Government reports SBM-U 2.0 budget and waste-management support', 'MoHUA reported that SBM-U 2.0 is being implemented through assistance for waste-to-compost, waste-to-energy, biomethanation, material-recovery facilities and legacy-dumpsite remediation. The release provided separate budget outlays and central-share figures for the original mission and its second phase.', 'update', '141600', 'crore rupees budget outlay for SBM-U 2.0', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100336');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (121, 2, '2025-03-28', 'Consultative Committee reviews SBM-U 2.0 roadmap', 'The Ministry’s Consultative Committee reviewed progress and the future roadmap of SBM-U 2.0. Discussions emphasized sustained cleanliness, behavioural change, public participation, stronger infrastructure and adoption of successful urban-sanitation practices.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=2116136');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (122, 2, '2025-12-11', 'SBM-U 2.0 implementation and fund utilization reported', 'MoHUA explained that central funds under SBM-U 2.0 are released against approved state action plans and subsequent utilization and physical progress. The release reported central-share releases, utilization certificates and plans for mechanized road sweepers under the mission.', 'update', '6876', 'crore rupees released under SBM-U 2.0', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2202529');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (130, 2, '2026-04-22', 'NITRD recognised as a zero-waste-to-landfill healthcare campus', 'The National Institute of Tuberculosis and Respiratory Diseases in Delhi was officially recognised as Zero Waste to Landfill under an SBM-U 2.0 initiative. The project introduced waste auditing, staff training, composting, dry-waste recovery and horticultural-waste management to divert campus waste from landfills.', 'achievement', '0', 'waste sent to landfill', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2254377&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (131, 2, '2026-06-29', 'Telangana strengthens urban sanitation through citizen action', 'Telangana’s 100-Day Action Plan under SBM-U 2.0 used rallies, door-to-door outreach, source-segregation messaging and home-composting awareness to promote sustained behaviour change. The campaign sensitised 27.09 lakh urban households and mobilised citizens and urban local bodies to improve cleanliness and service delivery.', 'update', '27.09 lakh', 'urban households sensitised', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2278895&lang=1&reg=48');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (146, 4, '2024-07-30', 'PM-KISAN reaches over 11 crore farmers in 17 instalments', 'The Ministry reported that PM-KISAN had transferred more than Rs. 3.24 lakh crore to over 11 crore farmers across 17 instalments. It reaffirmed that the scheme provides Rs. 6,000 annually through direct bank transfers for agricultural needs.', 'achievement', '3.24 lakh crore', 'Indian rupees disbursed', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2039203');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (147, 4, '2024-10-04', '18th PM-KISAN instalment announced for October 5', 'The Ministry announced that the Prime Minister would release the 18th PM-KISAN instalment from Washim, Maharashtra. The release said the instalment would take cumulative scheme disbursement above Rs. 3.45 lakh crore and support more than 11 crore farmers.', 'target', '3.45 lakh crore', 'Indian rupees cumulative disbursement expected', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=2061923');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (148, 4, '2024-10-05', '18th PM-KISAN instalment disbursed to farmers', 'The Prime Minister released the 18th PM-KISAN instalment in Washim, Maharashtra. About Rs. 20,000 crore was transferred to approximately 9.4 crore farmers through direct benefit transfer.', 'achievement', '20000 crore', 'Indian rupees transferred', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2062425');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (149, 4, '2025-02-07', 'PM-KISAN saturation drives add eligible farmers', 'The Ministry reported that saturation campaigns had added more than one crore eligible farmers during the Viksit Bharat Sankalp Yatra and over 25 lakh more within the first 100 days of the new government. It said 9.59 crore beneficiaries received the 18th instalment.', 'update', '25 lakh', 'eligible farmers added within the first 100 days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100758');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (150, 4, '2025-02-21', '19th PM-KISAN instalment announced for February 24', 'The Agriculture Minister briefed the media on the upcoming 19th PM-KISAN instalment. The release stated that more than Rs. 3.46 lakh crore had already been disbursed to over 11 crore farmer families through 18 instalments.', 'target', '3.46 lakh crore', 'Indian rupees previously disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2105462');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (151, 4, '2025-02-24', '19th PM-KISAN instalment reaches 9.8 crore farmers', 'The Prime Minister released the 19th PM-KISAN instalment from Bhagalpur, Bihar. More than 9.8 crore farmers, including 2.41 crore women farmers, received direct financial assistance exceeding Rs. 22,000 crore.', 'achievement', '22000 crore', 'Indian rupees transferred', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2105745');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (39, 19, '2022-05-01', 'PMGSY: 7.22 lakh km rural roads constructed since 2000', 'Rural Development Ministry announces 7.22 lakh km of rural roads constructed under PMGSY, connecting 99% of habitations over 500 population.', 'achievement', '7.22', 'lakh km roads', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1843197');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (123, 1, '2026-02-23', 'PMAY-U 2.0 approves 2.88 lakh additional houses', 'The Ministry of Housing and Urban Affairs approved 287,618 additional houses under PMAY-U 2.0 across 16 States and Union Territories. This raised total sanctions under the scheme to more than 13.61 lakh houses, including homes under BLC, AHP and ARH verticals.', 'achievement', '287618', 'houses sanctioned', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2231861&lang=2&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (124, 1, '2026-03-12', 'PMAY-U extended to support sustainable and disaster-resilient housing', 'The Ministry of Housing and Urban Affairs extended the PMAY-U scheme period to 30 September 2026 to complete under-construction houses and release funds through the SNA-SPARSH module. The release also highlighted technology-focused housing initiatives, including 54 proven construction technologies shortlisted under the Global Housing Technology Challenge.', 'update', '54', 'proven construction technologies shortlisted', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2239027&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (132, 3, '2023-05-31', '5 crore hospital admissions authorized under AB-PMJAY', 'Ayushman Bharat PM-JAY reached 5 crore authorized hospital admissions, representing treatment worth Rs. 61,501 crore. The release also reported that 23.39 crore beneficiaries had been verified and could access cashless treatment through 28,351 empanelled hospitals.', 'achievement', '5 crore', 'authorized hospital admissions', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1928582');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (133, 3, '2024-01-14', '30 crore Ayushman cards created', 'AB-PMJAY crossed the milestone of 30 crore Ayushman cards created as of January 12, 2024. The release attributed the acceleration to campaigns including Viksit Bharat Sankalp Yatra and Ayushman Bhava, as well as the Ayushman mobile app.', 'achievement', '30 crore', 'Ayushman cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1996010');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (134, 3, '2024-08-02', 'More than 34.7 crore Ayushman cards created', 'The government reported that more than 34.7 crore Ayushman cards had been created under AB-PMJAY as of June 30, 2024. It also stated that 7.37 crore hospital admissions worth approximately Rs. 1 lakh crore had been authorized.', 'update', '34.7 crore', 'Ayushman cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2040860');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (135, 3, '2024-12-20', 'AB-PMJAY expanded to senior citizens aged 70 and above', 'The government reiterated the expansion of AB-PMJAY to provide free treatment benefits of up to Rs. 5 lakh annually to all citizens aged 70 and above, regardless of socioeconomic status. As of November 30, 2024, approximately 36 crore beneficiaries had been verified and 8.39 crore hospital admissions had been authorized.', 'update', '6 crore', 'senior citizens aged 70 years and above covered by the expansion', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2086513');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (136, 3, '2025-02-04', 'Ayushman Vay Vandana benefits available through expanded hospital network', 'The release provided an update on treatment services available to senior citizens under the Ayushman Vay Vandana Card following the AB-PMJAY expansion. It stated that beneficiaries could access cashless services covering 1,961 procedures across 27 specialties through more than 30,072 hospitals.', 'update', '30,072', 'empanelled hospitals', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099545');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (137, 3, '2025-03-28', 'AB-PMJAY savings exceed Rs. 1.25 lakh crore', 'The Economic Survey 2024-25 reported that government-supported health insurance schemes including AB-PMJAY had helped reduce out-of-pocket expenditure. It recorded savings of more than Rs. 1.25 lakh crore and noted that government health expenditure increased while the share paid directly by households declined.', 'achievement', '1.25 lakh crore', 'rupees in reported savings on out-of-pocket expenditure', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2116209');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (138, 3, '2025-07-25', 'Over 41 crore Ayushman cards created', 'The government reported that more than 41 crore Ayushman cards had been created under AB-PMJAY. The scheme had 31,466 empanelled hospitals and more than 9.84 crore authorized hospital admissions worth over Rs. 1.40 lakh crore.', 'achievement', '41 crore', 'Ayushman cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148359');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (139, 3, '2026-02-03', 'More than 15,733 private hospitals empanelled under AB-PMJAY', 'The Ministry reported that more than 15,733 private hospitals had been empanelled under AB-PMJAY as of December 31, 2025. It also stated that 1,259 of these private hospitals were located in aspirational districts.', 'achievement', '15,733', 'private hospitals empanelled', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2222495');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (140, 3, '2026-03-17', '43.52 crore Ayushman cards created', 'The government reported that 43.52 crore Ayushman cards had been created under AB-PMJAY as of February 28, 2026, including 1.14 crore Ayushman Vay Vandana cards. It also reported 11.69 crore authorized hospital admissions worth Rs. 1.73 lakh crore and 36,229 empanelled hospitals.', 'achievement', '43.52 crore', 'Ayushman cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2241085&lang=1&reg=1');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (152, 4, '2025-03-18', 'PM-KISAN recovery and verification measures reported', 'The Ministry reported that more than Rs. 3.68 lakh crore had been disbursed through 19 instalments and that mandatory land seeding, Aadhaar-based payments, and e-KYC were being used to verify beneficiaries. It also stated that Rs. 416 crore had been recovered from ineligible beneficiaries.', 'update', '416 crore', 'Indian rupees recovered from ineligible beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112399');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (153, 4, '2025-07-29', 'PM-KISAN beneficiary and fund-release details published', 'The Ministry published instalment-wise details showing that more than Rs. 3.69 lakh crore had been disbursed through 19 instalments. It also described technological safeguards, mandatory e-KYC and Aadhaar-linked payments, and recovery of funds paid to ineligible beneficiaries.', 'update', '3.69 lakh crore', 'Indian rupees disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149696');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (154, 4, '2025-07-30', '20th PM-KISAN instalment scheduled for August 2', 'The Ministry announced preparations for the 20th PM-KISAN instalment, scheduled to be released from Varanasi on August 2. It said Rs. 20,500 crore would be transferred to approximately 9.7 crore farmers through direct benefit transfer.', 'target', '20500 crore', 'Indian rupees planned for disbursement', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2150070');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (155, 4, '2025-08-02', '20th PM-KISAN instalment transferred to 9.7 crore farmers', 'The Prime Minister released the 20th PM-KISAN instalment from Varanasi. The release transferred Rs. 20,500 crore directly to more than 9.7 crore eligible farmer beneficiaries.', 'achievement', '20500 crore', 'Indian rupees transferred', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2151853');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (156, 4, '2025-09-26', '21st PM-KISAN instalment prioritized for flood-affected states', 'The Agriculture Minister released the 21st PM-KISAN instalment for farmers in Himachal Pradesh, Punjab, and Uttarakhand affected by floods and landslides. More than Rs. 540 crore was transferred directly to over 27 lakh farmers in the three states.', 'achievement', '540 crore', 'Indian rupees transferred', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2171684');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (96, 1, '2022-12-22', 'Technology Sub-Mission established under PMAY-U', 'The Ministry of Housing and Urban Affairs reported that a Technology Sub-Mission had been established under PMAY-U. It promotes innovative, sustainable, eco-friendly and disaster-resilient construction technologies and materials for faster, lower-cost and higher-quality housing.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1885835');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (97, 1, '2023-05-25', 'PMAY-U completes more than 74 lakh urban houses', 'The government stated that more than 74.25 lakh houses had been completed under PMAY-U by May 24, 2023, compared with 8.04 lakh houses during 2004–2014. The release also highlighted increased central assistance, women’s ownership, slum rehabilitation and improved access to basic amenities.', 'achievement', '74.25', 'lakh houses completed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1931774');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (98, 1, '2023-08-31', 'PMAY-U progress booklet reports nearly 1.19 crore sanctioned houses', 'The Ministry of Housing and Urban Affairs highlighted PMAY-U achievements in an e-booklet on its programmes. The release reported that approximately 1.19 crore houses had been sanctioned under PMAY-U, alongside progress in housing construction and delivery.', 'achievement', '1.19', 'crore houses sanctioned', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1953776');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (99, 1, '2024-07-23', 'PMAY-U records 85.04 lakh completed houses', 'The government stated that PMAY-U is demand-driven and that no fixed national construction target has been set. As of July 15, 2024, 118.64 lakh houses had been sanctioned, 114.33 lakh grounded for construction and 85.04 lakh completed or delivered.', 'update', '85.04', 'lakh houses completed or delivered', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2038342');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (100, 1, '2024-08-01', 'PMAY-U reports 81.67 lakh occupied houses under urban housing mission', 'The Ministry provided an update on the In-Situ Slum Rehabilitation vertical and overall PMAY-U implementation. As of July 22, 2024, 118.64 lakh houses had been sanctioned, 114.33 lakh grounded, 85.04 lakh completed and 81.67 lakh occupied.', 'update', '81.67', 'lakh houses occupied', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2040052');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (101, 1, '2024-08-09', 'Cabinet approves PMAY-U 2.0 for one crore urban families', 'The Union Cabinet approved PMAY-U 2.0 to provide financial assistance to urban poor and middle-class families to construct, purchase or rent affordable homes over five years. The scheme targets one crore families, with government assistance of ₹2.30 lakh crore and an overall investment of ₹10 lakh crore.', 'launch', '1', 'crore urban families to receive assistance', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2043927');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (102, 1, '2025-07-24', 'PMAY-U interest subsidy reaches 25 lakh beneficiaries', 'The Ministry reported that ₹58,885 crore in interest subsidies had been provided to 25,04,220 beneficiaries under PMAY-U’s Credit Linked Subsidy Scheme. The release also noted the launch of PMAY-U 2.0 from September 1, 2024, for one crore additional eligible urban beneficiaries.', 'achievement', '25,04,220', 'beneficiaries receiving interest subsidy', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2147921');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (103, 1, '2025-03-21', 'PMAY-U 2.0 approves over 3.52 lakh houses', 'The first Central Sanctioning and Monitoring Committee meeting under PMAY-U 2.0 approved proposals for more than 3.52 lakh houses across ten States and Union Territories. The release said the approvals prioritised women, vulnerable groups and beneficiaries from SC, ST and OBC communities.', 'achievement', '3.52', 'lakh houses approved', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113557');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (104, 1, '2025-06-18', 'PMAY-U 2.0 approves 2.35 lakh additional houses', 'The third CSMC meeting under PMAY-U 2.0 approved 2,34,864 houses in nine States. With these approvals, the total number of houses sanctioned under PMAY-U 2.0 rose to 7,09,979.', 'achievement', '2.35', 'lakh houses approved', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2137416');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (105, 1, '2025-08-13', 'PMAY-U 2.0 approves 1.47 lakh more houses', 'The fourth CSMC meeting under PMAY-U 2.0 approved 1,46,582 additional pucca houses across 14 States and Union Territories. The total number of houses sanctioned under PMAY-U 2.0 consequently reached 8.56 lakh.', 'achievement', '1.47', 'lakh houses approved', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2156126');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (106, 1, '2025-09-05', 'Angikaar 2025 campaign launched under PMAY-U 2.0', 'The Minister for Housing and Urban Affairs launched Angikaar 2025 as a last-mile outreach campaign for PMAY-U 2.0. The campaign aims to increase awareness, speed up application verification, expedite completion of sanctioned houses and improve convergence with other government schemes.', 'launch', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2164173');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (107, 1, '2025-10-16', 'PMAY-U 2.0 crosses 10 lakh sanctioned houses', 'The fifth CSMC meeting under PMAY-U 2.0 approved 1,40,942 additional houses across 14 States and Union Territories. These approvals took the scheme’s total sanctions above 10 lakh, with housing needs of women and vulnerable groups prioritised.', 'achievement', '1.41', 'lakh additional houses approved', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2179800');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (125, 1, '2026-06-17', 'Government approves over 2.13 lakh additional PMAY-U 2.0 houses', 'The Ministry of Housing and Urban Affairs approved more than 2.13 lakh additional houses under PMAY-U 2.0 during the seventh Central Sanctioning and Monitoring Committee meeting. The approvals raised total sanctions under the scheme to over 16.13 lakh houses across 16 States and Union Territories, with 97% of sanctioned houses allotted to women.', 'achievement', '2.13 lakh', 'additional houses', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2274164&lang=1&reg=48');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (141, 4, '2023-06-14', 'PM-KISAN empowers farmers through timely financial assistance', 'The release states that PM-KISAN had disbursed more than Rs. 2.42 lakh crore to over 11 crore farmers. It highlights direct bank transfers, support for women beneficiaries, and positive effects on farm investment and rural incomes.', 'achievement', '2.42 lakh crore', 'Indian rupees disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1932398');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (142, 4, '2023-08-08', 'Government reports PM-KISAN coverage and disbursement progress', 'The Ministry describes PM-KISAN as providing Rs. 6,000 annually to eligible landholding farmer families through three direct-transfer instalments. It reports that more than Rs. 2.60 lakh crore had been disbursed to over 11 crore farmers.', 'update', '2.60 lakh crore', 'Indian rupees disbursed', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1946816');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (143, 4, '2023-09-21', 'AI chatbot launched for PM-KISAN beneficiaries', 'The Ministry launched an AI chatbot integrated with the PM-KISAN grievance-management system. The chatbot provides multilingual assistance on application status, payments, eligibility, and other scheme-related queries.', 'launch', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1959461');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (144, 4, '2024-06-17', '17th PM-KISAN instalment announced for Varanasi', 'The release announced that the Prime Minister would release the 17th PM-KISAN instalment on June 18, 2024. More than 9.26 crore farmers were expected to receive over Rs. 20,000 crore through direct transfers.', 'target', '20000 crore', 'Indian rupees planned for disbursement', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2025877');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (145, 4, '2024-06-18', '17th PM-KISAN instalment released to farmers', 'The Prime Minister released the 17th instalment of PM-KISAN from Varanasi. The release transferred about Rs. 20,000 crore to farmers and also recognized more than 30,000 self-help groups trained as Krishi Sakhis.', 'achievement', '20000 crore', 'Indian rupees transferred', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2026279');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (1, 1, '2022-08-15', 'PM Modi announces Housing for All target achieved', 'Prime Minister announces that all sanctioned houses under PMAY-U have been completed, achieving the Housing for All mission.', 'achievement', '1.12', 'crore houses sanctioned', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1730341');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (4, 2, '2019-10-02', 'India becomes ODF: PM declares nation Open Defecation Free', 'On the 150th birth anniversary of Mahatma Gandhi, PM Modi declares India Open Defecation Free, five years after Swachh Bharat Mission launch.', 'achievement', '10', 'crore toilets built', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1587023');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (108, 1, '2025-12-11', 'PMAY-U sanctions 122.06 lakh houses, with 96.02 lakh completed', 'The Ministry of Housing and Urban Affairs reported that 122.06 lakh houses, including 10.43 lakh under PMAY-U 2.0, had been sanctioned under the two urban housing phases. It stated that 113.85 lakh houses had been grounded and 96.02 lakh had been completed or delivered to beneficiaries as of 2025-11-24.', 'update', '122.06', 'lakh houses sanctioned', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2202527');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (126, 2, '2025-12-20', '10th Swachh Survekshan launched with expanded citizen participation', 'The Ministry of Housing and Urban Affairs launched the 10th edition of Swachh Survekshan for 2025–26 under the urban cleanliness framework of SBM-U. The new edition increases the role of year-round citizen feedback, expands assessments to river and coastal towns, and introduces additional award categories.', 'launch', '10', 'Swachh Survekshan edition', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2207000&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (127, 2, '2025-12-31', 'Urban local bodies turn coconut waste into compost, coir and livelihoods', 'The release highlights SBM-U 2.0 initiatives that convert coconut waste from temples, coastal cities and markets into compost, cocopeat, coir and other useful products. It presents these projects as examples of waste-to-wealth models that reduce landfill disposal while creating economic and environmental benefits.', 'achievement', '1.15 lakh', 'metric tonnes of coconut waste processed into coir and compost', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2210020&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (128, 2, '2026-01-29', 'SBM-U reports 81.30 percent municipal waste processing', 'The Ministry of Housing and Urban Affairs reported that urban local bodies have constructed more household and community toilets than the original SBM-U targets. Municipal solid-waste processing has risen from 16 percent in 2014 to 81.30 percent, supported by facilities such as material recovery, composting, construction-and-demolition waste and waste-to-energy plants.', 'achievement', '81.30', 'percent of municipal solid waste processed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2220345');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (129, 2, '2026-01-21', 'Lucknow becomes Uttar Pradesh’s first zero fresh waste dump city', 'Lucknow achieved 100 percent scientific processing of its municipal solid waste after commissioning the Shivari Solid Waste Management Plant. The new facility has a capacity of 700 metric tonnes per day, enabling the city to process its daily waste without fresh open dumping.', 'achievement', '100', 'percent scientific processing of municipal solid waste', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2216806&lang=2&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (2, 1, '2019-06-07', 'PMAY-U: Government sanctions 81 lakh houses', 'Over 81 lakh houses sanctioned under Pradhan Mantri Awas Yojana Urban since inception, with completion progressing well.', 'achievement', '81', 'lakh houses sanctioned', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1577423');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (3, 1, '2020-01-15', 'PMAY-U grounded benefit distribution hits record', 'Ministry announces 40 lakh houses grounded (construction started) under PMAY-Urban, ahead of schedule.', 'achievement', '40', 'lakh houses grounded', 'https://www.google.com/search?q=site:pib.gov.in+PMAY+Urban+grounded+2020');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (5, 2, '2017-04-01', 'SBM surpasses 5 crore household toilets target', 'Ministry announces construction of over 5.5 crore individual household toilets under Swachh Bharat Mission since 2014.', 'achievement', '5.5', 'crore toilets', 'https://www.google.com/search?q=site:pib.gov.in+Swachh+Bharat+"5+crore+toilets"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (6, 2, '2020-01-21', 'India ODF Plus: 2,780 cities declared ODF+', 'More than 2,780 cities in India have been declared ODF Plus under Swachh Bharat Mission Urban 2.0.', 'achievement', '2780', 'cities ODF+', 'https://www.google.com/search?q=site:pib.gov.in+"ODF+Plus"+"2780+cities"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (7, 3, '2022-09-23', 'Ayushman Bharat: 3 crore hospitalisations covered', 'On the 4th anniversary, Ayushman Bharat PM-JAY has covered over 3 crore hospitalisations, providing free healthcare worth Rs 35,000 crore.', 'achievement', '3', 'crore hospitalisations', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=238383');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (8, 3, '2021-04-01', '18 crore Ayushman cards issued to beneficiaries', 'Ministry of Health announces issuance of 18 crore Ayushman Bharat cards, with 2.3 crore hospitalisations covered.', 'achievement', '18', 'crore cards issued', 'https://www.google.com/search?q=site:pib.gov.in+Ayushman+"18+crore+cards"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (9, 3, '2018-09-23', 'PM launches Ayushman Bharat: Rs 5 lakh coverage for 50 crore', 'PM Modi launches Pradhan Mantri Jan Arogya Yojana providing Rs 5 lakh annual health cover to 10 crore families or 50 crore beneficiaries.', 'launch', '50', 'crore beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1547032');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (10, 4, '2022-10-16', 'PM Kisan: Rs 2 lakh crore disbursed to 11 crore farmers', 'PM Modi releases 12th instalment of PM-KISAN. Total disbursal crosses Rs 2 lakh crore benefiting over 11 crore farmers.', 'achievement', '2', 'lakh crore disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1886630');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (11, 4, '2020-04-24', 'PM Kisan: Rs 6,000 reaches 8.89 crore farmers during COVID', 'During COVID lockdown, PM Kisan transferred Rs 2,000 first instalment directly to 8.89 crore farmer accounts.', 'achievement', '8.89', 'crore farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1616791');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (12, 5, '2020-01-22', 'Child Sex Ratio improves by 16 points under BBBP', 'Ministry of Women & Child Development reports Child Sex Ratio at birth improved from 918 to 934 in BBBP districts, attributing success to the programme.', 'achievement', '16', 'point improvement in CSR', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1695199');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (13, 5, '2016-03-08', 'BBBP: 100 districts covered, girl child enrolment up', 'On International Women Day, PM announces BBBP expansion. Female school enrolment in target districts up by 5.4%.', 'achievement', '100', 'districts covered', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=136289');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (14, 6, '2021-08-28', 'MUDRA loans: Rs 15.10 lakh crore disbursed in 6 years', 'Finance Minister announces that over 28.68 crore MUDRA loans worth Rs 15.10 lakh crore disbursed since inception, helping micro enterprises.', 'achievement', '15.10', 'lakh crore disbursed', 'https://www.google.com/search?q=site:pib.gov.in+Mudra+"15.10+lakh+crore"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (15, 6, '2019-04-05', 'PM Mudra: 19.27 crore accounts opened, women get 75% loans', 'Ministry reports 19.27 crore loan accounts opened under PMMY. Women entrepreneurs constitute 75% of beneficiaries.', 'achievement', '19.27', 'crore loan accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1595504');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (16, 7, '2019-09-07', 'PM Ujjwala: 8 crore LPG connections target achieved ahead of schedule', 'PM Modi announces achievement of 8 crore free LPG connections target 7 months ahead of schedule. Clean cooking fuel reaches every village.', 'achievement', '8', 'crore connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1584346');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (17, 7, '2020-06-01', 'Ujjwala beneficiaries: 14.17 crore LPG connections in rural India', 'During COVID, free LPG cylinders given to Ujjwala beneficiaries. Over 14.17 crore total LPG connections in rural areas.', 'achievement', '14.17', 'crore LPG connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1942151');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (18, 8, '2022-08-28', 'Jan Dhan: 46.25 crore accounts, Rs 1.74 lakh crore deposits', 'Finance Minister announces 46.25 crore Jan Dhan accounts with combined deposits of Rs 1.74 lakh crore. 56% account holders are women.', 'achievement', '46.25', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1854909');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (19, 8, '2014-09-05', 'PM Modi breaks world record: 1.5 crore Jan Dhan accounts in one day', 'Guinness World Record set as 1.5 crore bank accounts opened on single day under PMJDY launch, achieving most bank accounts opened in a week.', 'achievement', '1.5', 'crore accounts in one day', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=109149');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (20, 9, '2019-03-31', 'India achieves 100% household electrification: Saubhagya complete', 'Union Power Minister announces all 2.82 crore un-electrified households have been electrified under Saubhagya scheme, completing India''s electrification mission.', 'achievement', '2.82', 'crore households electrified', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=197411');
