INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (78, 55, '2022-09-27', 'Ayushman Bharat Digital Mission: 22 crore ABHA IDs created in one year', 'Health Ministry marks first anniversary of ABDM with 22 crore Ayushman Bharat Health Account (ABHA) IDs created. 1.2 lakh health facilities registered.', 'achievement', '22', 'crore health IDs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1830743');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (79, 56, '2022-12-23', 'PMGKAY extended till December 2023; 80 crore beneficiaries to get free grain', 'PM announces PMGKAY extended for one more year covering 80 crore NFSA beneficiaries with 5 kg free grain per month. Total expenditure to reach Rs 3.91 lakh crore.', 'achievement', '80', 'crore beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1990696');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (80, 56, '2020-03-26', 'PM launches Rs 1.70 lakh crore PMGKAY relief package for COVID', 'PM announces Rs 1.70 lakh crore COVID relief under PMGKAY including free 5 kg grain and 1 kg pulses to 80 crore for 3 months.', 'launch', '80', 'crore beneficiaries', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=202495');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (81, 57, '2021-03-01', 'Rurban Mission: 300 clusters identified, 217 clusters sanctioned', 'Rural Development Ministry announces 217 Rurban clusters sanctioned across 27 states under Shyama Prasad Mukherji Rurban Mission.', 'achievement', '217', 'clusters sanctioned', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=199466');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (82, 14, '2022-01-16', 'Startup India: 84,012 DPIIT-recognised startups; India 3rd largest startup ecosystem', 'Commerce Ministry marks 6 years of Startup India. 84,012 startups recognised by DPIIT, making India world''s 3rd largest startup ecosystem. 47% startups from Tier 2/3 cities.', 'achievement', '84012', 'recognised startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1881495');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (83, 14, '2019-08-15', 'Fund of Funds for Startups: Rs 10,000 crore to catalyse startup investment', 'PM announces Rs 10,000 crore Fund of Funds for Startups established under SIDBI to provide capital to startups via SEBI-registered AIFs.', 'target', '10000', 'crore fund', 'https://www.google.com/search?q=site:pib.gov.in+"Startup+India"+"Fund+of+Funds"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (84, 40, '2021-03-01', 'NAPS: 9.7 lakh apprentices engaged, Rs 310 crore stipend support disbursed', 'Skill Ministry announces 9.7 lakh apprentices engaged under NAPS with Rs 310 crore disbursed as stipend support to employers since 2016.', 'achievement', '9.7', 'lakh apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1844727');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (72, 51, '2021-02-01', 'MGNREGS: 7.55 crore households provided employment in 2020-21', 'Rural Development Ministry announces record 7.55 crore rural households given employment under MGNREGS in 2020-21, generating 389.09 crore person-days of work.', 'achievement', '7.55', 'crore households', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1786672');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (86, 36, '2022-01-05', 'Aspirational Districts: 112 districts show double-digit improvement in composite index', 'NITI Aayog announces 112 aspirational districts collectively improved composite development index by 16.1 points in 4 years across health, education, agriculture, and infrastructure.', 'achievement', '16.1', 'point composite improvement', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1823404');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (87, 36, '2020-06-01', 'Delta Ranking: 25 districts in top performers across all 5 sectors', 'PM lauds 25 aspirational districts that feature in top performers across all 5 thematic areas — health & nutrition, education, agriculture, financial inclusion, and basic infrastructure.', 'achievement', '25', 'top performer districts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1601272');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (89, 39, '2021-10-13', 'PM launches Gati Shakti portal to end infrastructure silos across ministries', 'PM launches PM Gati Shakti National Master Plan, a digital platform integrating 16 ministries to eliminate infrastructure duplication and reduce project delays.', 'launch', '16', 'ministries integrated', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1763594');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (90, 38, '2022-07-01', 'Atal Bhujal Yojana: Water security plans prepared for 8,353 gram panchayats', 'Jal Shakti Ministry announces Water Security Plans prepared for all 8,353 gram panchayats in 7 states under Atal Bhujal, with community-led groundwater conservation underway.', 'achievement', '8353', 'gram panchayats', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1843394');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (92, 45, '2020-05-27', 'PMVVY extended with enhanced limit: senior citizens can invest up to Rs 15 lakh', 'Finance Ministry announces PMVVY extended to March 2023 with investment limit raised from Rs 7.5 lakh to Rs 15 lakh per family, benefiting over 30 lakh senior citizens.', 'achievement', '15', 'lakh per family limit', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1518543');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (93, 45, '2022-08-01', 'PMVVY: 6.97 lakh policies issued, Rs 61,000 crore corpus mobilised', 'LIC announces 6.97 lakh PMVVY policies issued with total corpus of Rs 61,000 crore, providing assured pension income to senior citizens.', 'achievement', '6.97', 'lakh policies', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1530964');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (94, 43, '2022-07-01', 'PM Daksh: 50,000 marginalised youth trained in FY 2021-22', 'Social Justice Ministry announces PM Daksh Yojana trained 50,000 SC/OBC/EBC/sanitation worker youth in FY22 across 1,000 training programmes with 60% placement rate claimed.', 'achievement', '50000', 'youth trained', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1808665');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (95, 43, '2023-03-01', 'PM Daksh portal: 2.7 lakh candidates registered for skill training', 'Ministry announces 2.7 lakh candidates registered on PM Daksh portal for free skill training, with 500 empanelled training partners across India.', 'achievement', '2.7', 'lakh registered', 'https://www.google.com/search?q=site:pib.gov.in+"PM+Daksh"+"2.7+lakh"');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (85, 40, '2019-08-01', 'Government targets 50 lakh apprentices by 2020 under NAPS', 'Ministry of Skill Development announces target to engage 50 lakh apprentices by March 2020 with industry through NAPS incentive of Rs 1,500/month stipend support.', 'target', '50', 'lakh apprentices', 'https://pib.gov.in/newsite/PrintRelease.aspx?relid=149428');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (88, 39, '2022-10-13', 'PM Gati Shakti: Rs 25 lakh crore infrastructure projects mapped on National Master Plan', 'Commerce Ministry announces Rs 25 lakh crore worth of infrastructure projects from 16 ministries mapped on PM Gati Shakti National Master Plan portal for integrated planning.', 'achievement', '25', 'lakh crore mapped', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2022/oct/doc20221013117201.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (91, 38, '2023-06-23', 'Groundwater extraction reduced by 18% in Atal Bhujal districts since 2020', 'Ministry claims groundwater extraction rate has reduced by 18% across 8,353 programme gram panchayats due to behaviour change, micro-irrigation, and recharge structures.', 'achievement', '18', 'percent extraction reduction', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2023/jun/doc2023623216801.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (109, 2, '2021-10-01', 'Prime Minister launches SBM-U 2.0', 'The Prime Minister launched the second phase of Swachh Bharat Mission-Urban to advance sanitation, waste management and behavioural change across urban local bodies. The release highlighted progress under the first phase, including expanded sanitation access and increased municipal waste processing.', 'launch', '70', 'lakh household, community and public toilets built', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1760039');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (110, 2, '2021-10-12', 'Cabinet approves SBM-U continuation through 2025-26', 'The Union Cabinet approved continuation of Swachh Bharat Mission-Urban through 2025-26. The second phase focuses on sustaining ODF outcomes, achieving scientific waste processing, managing wastewater and making cities garbage free.', 'target', '2025-26', 'mission completion year', 'https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=1763354');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (111, 2, '2021-10-27', 'Operational guidelines for SBM-U 2.0 launched', 'The Ministry of Housing and Urban Affairs launched the operational guidelines for SBM-U 2.0. The guidelines establish implementation principles centered on garbage-free cities, equity, capacity building and digital monitoring.', 'launch', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1766973');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (112, 2, '2021-12-06', 'Swachh Technology Challenge launched', 'MoHUA launched the Swachh Technology Challenge under SBM-U 2.0 to identify affordable, indigenous and scalable waste-management solutions. The challenge targeted social inclusion, zero-dump systems, plastic-waste management and digital transparency.', 'launch', '4', 'thematic challenge categories', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1778490');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (113, 2, '2021-12-09', 'Municipal waste processing reaches 70 percent', 'The release stated that municipal solid-waste processing under SBM-U had increased substantially from its 2014 level. It also reported that nearly all urban local bodies had been certified ODF and described SBM-U 2.0 goals for garbage-free cities.', 'achievement', '70', 'percent of municipal solid waste processed in 2021', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1779680');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (114, 2, '2021-12-13', 'SBM-U 2.0 and AMRUT 2.0 set five-year urban targets', 'The Ministry outlined the principal objectives of SBM-U 2.0, including source segregation, door-to-door collection, scientific waste processing, dumpsite remediation and wastewater management. The missions were presented as a five-year programme to make cities garbage free and water secure.', 'target', '5', 'years in the mission period from 2021 to 2026', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1780913');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (157, 4, '2025-11-14', '21st PM-KISAN instalment announced with cumulative transfers above Rs. 3.70 lakh crore', 'The Ministry announced that the Prime Minister would release the 21st PM-KISAN instalment on November 19, 2025. It reported cumulative direct transfers exceeding Rs. 3.70 lakh crore to more than 11 crore farmer families through 20 instalments and highlighted digital innovations such as Kisan-eMitra and farmer registries.', 'target', '3.70 lakh crore', 'Indian rupees cumulative direct transfers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2190074');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (158, 5, '2021-02-04', 'Review of Beti Bachao Beti Padhao Scheme', 'A NITI Aayog evaluation found that the scheme generated significant mass mobilization against gender discrimination and developed community-level initiatives. The release also reported an improving national Sex Ratio at Birth from 918 in 2014-15 to 934 in 2019-20.', 'achievement', '16', 'percentage points improvement in national Sex Ratio at Birth', 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=1695199');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (159, 5, '2021-02-12', 'Beti Bachao Beti Padhao scheme reports improved Sex Ratio at Birth', 'The Ministry reported that BBBP combines a nationwide advocacy campaign with multisectoral interventions in 405 districts. It cited an improvement in the national Sex Ratio at Birth from 918 in 2014-15 to 934 in 2019-20.', 'achievement', '16', 'percentage points improvement in national Sex Ratio at Birth', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1697410');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (160, 5, '2021-12-03', 'BBBP campaign covers 405 districts through multisectoral interventions', 'The Ministry described BBBP''s objectives of preventing gender-biased sex selection, protecting girls, and promoting their education and participation. It stated that the scheme combines nationwide advocacy with multisectoral interventions in identified districts and does not provide direct benefit transfers.', 'update', '405', 'districts receiving multisectoral interventions', 'https://pib.gov.in/pressreleasepage.aspx?prid=1777733');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (161, 5, '2022-02-11', 'Initiatives announced to address school dropouts among girls', 'The release said BBBP awareness campaigns are organized at district level to support the re-enrolment of girls who have dropped out at secondary level. It also highlighted recognition for meritorious students and complementary Samagra Shiksha measures such as enrolment drives, retention camps, and gender-sensitization activities.', 'update', '405', 'districts receiving multisectoral interventions', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1797708');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (162, 5, '2022-07-27', 'BBBP reports gains in sex ratio, education and maternal-care indicators', 'The Ministry reported that BBBP advocacy helped increase national Sex Ratio at Birth from 918 in 2014-15 to 937 in 2020-21. It also cited higher secondary-school enrolment for girls, first-trimester antenatal registration, and institutional deliveries.', 'achievement', '19', 'percentage points improvement in national Sex Ratio at Birth', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1845380');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (163, 5, '2023-07-28', 'BBBP expanded nationwide under Mission Shakti', 'The Ministry stated that BBBP operates under the Sambal component of Mission Shakti and has been expanded to all districts through multisectoral interventions. Activities include promotion of sports, self-defence camps, girls'' toilets, menstrual-hygiene facilities, awareness of the PC-PNDT Act, and girls'' skilling.', 'update', '100', 'percent central government funding', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1943758');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (164, 5, '2025-01-21', 'Ministry announces 10th-anniversary BBBP celebrations', 'The Ministry announced a nationwide programme marking ten years of BBBP, with celebrations scheduled from January 22 to March 8, 2025. Planned activities included an oath-taking ceremony, a best-practices compendium, Mission Shakti and Mission Vatsalya portal launches, and local awareness events.', 'launch', '10', 'years since scheme launch', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2094929');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (165, 5, '2025-01-22', 'Ministry commemorates BBBP''s 10th anniversary', 'The Ministry commemorated a decade of BBBP and described the scheme as having contributed to progress in gender equality and the status of girls. The inaugural event also launched a compendium of best practices, Mission Vatsalya and Mission Shakti portals, and the Mission Shakti mobile app.', 'launch', '10', 'years since scheme launch', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2095220');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (166, 5, '2025-02-03', 'Palamu launches 100-day BBBP awareness campaign', 'Palamu district in Jharkhand organized thematic awareness programmes under the 100 Din Beti Bachao, Beti Padhao campaign to address gender inequality, education, health, safety, and child protection. The release reported more than 70 programmes and outreach to 1,999 beneficiaries through related thematic activities.', 'achievement', '70', 'programmes organized in Palamu district', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099035');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (167, 5, '2025-02-04', 'Haryana''s Mahri Laado radio programme expands BBBP outreach', 'Haryana''s Women and Child Development Department launched the Mahri Laado radio programme as a community-based BBBP initiative addressing gender inequality and promoting the value of daughters. Broadcasts on All India Radio combined stories, interviews, and discussions, with reported participation across seven districts.', 'launch', '112933', 'participants engaged across seven Haryana districts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099556');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (168, 5, '2025-02-07', 'BBBP expanded to all districts with measurable annual objectives', 'The Ministry said BBBP is fully funded by the Central Government and has been expanded to cover every district. It reported that national Sex Ratio at Birth rose from 918 in 2014-15 to 930 in 2023-24, alongside improvements in girls'' secondary-school enrolment, institutional deliveries, and antenatal-care registration.', 'update', '12', 'percentage points improvement in national Sex Ratio at Birth', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=2100642');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (169, 5, '2026-02-06', 'BBBP reports continued improvement in sex ratio and girls'' enrolment', 'The Ministry described BBBP as a national movement focused on behavioural and social change toward the girl child. It reported that national Sex Ratio at Birth increased from 918 in 2014-15 to 929 in 2024-25, while girls'' secondary-school gross enrolment rose from 75.51% to 80.2%.', 'achievement', '11', 'percentage points improvement in national Sex Ratio at Birth', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2224413');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (170, 7, '2023-08-10', 'Features of PMUY', 'The release describes PMUY''s provision of deposit-free LPG connections to adult women from poor households. It reports that the original target of 8 crore connections was achieved in September 2019 and that Ujjwala 2.0 had expanded access to remaining households.', 'achievement', '8 crore', 'LPG connections', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1947509');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (171, 7, '2023-09-13', 'Cabinet approves 75 lakh additional Ujjwala connections', 'The Union Cabinet approved extending PMUY to provide 75 lakh additional LPG connections during FY 2023-24 to FY 2025-26. The release said this would increase the total number of PMUY beneficiaries to 10.35 crore.', 'target', '75 lakh', 'additional LPG connections', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1957091');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (172, 7, '2023-12-18', 'Delivery of LPG cylinders to urban slum dwellers', 'The release explains that PMUY provides deposit-free LPG connections to eligible poor households, including qualifying urban slum residents. It reports that 9.59 crore PMUY connections had been released as of September 30, 2023.', 'update', '9.59 crore', 'PMUY connections', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1987811');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (173, 7, '2024-03-07', 'Continuation of targeted subsidy for PMUY consumers in FY 2024-25', 'The Union Cabinet approved continuation of a targeted subsidy of Rs.300 per 14.2 kg cylinder for up to 12 refills per year during FY 2024-25. The release stated that more than 10.27 crore PMUY beneficiaries were eligible and that the total expenditure would be Rs.12,000 crore.', 'update', '12000', 'crore rupees', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2012354');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (174, 7, '2024-07-25', 'Aadhaar authentication improves targeting under PAHAL and Ujjwala', 'The release says Aadhaar-based authentication is being used to identify, authenticate and remove duplicate beneficiaries under PMUY and PAHAL. It describes the measure as a way to improve the accuracy and efficiency of subsidy delivery.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleseDetail.aspx?PRID=2036865');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (175, 7, '2024-08-08', '75 lakh additional PMUY connections completed', 'The Ministry reported that Oil Marketing Companies had completed releasing the additional 75 lakh PMUY connections approved in September 2023. As of July 1, 2024, the country had 10.33 crore LPG connections under PMUY.', 'achievement', '75 lakh', 'additional PMUY connections', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=2043041');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (176, 7, '2024-12-09', 'Distribution of LPG connections to eligible beneficiaries', 'The release outlines eligibility categories and verification mechanisms for receiving PMUY connections, including Aadhaar authentication and duplicate-checking systems. It reported 10.33 crore PMUY beneficiaries as of November 1, 2024.', 'update', '10.33 crore', 'PMUY beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2082375');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (177, 7, '2025-01-07', 'Year-end review: PMUY reaches 10.33 crore connections', 'The Ministry''s year-end review reported that PMUY had released 10.33 crore LPG connections. It also stated that approximately 222 crore LPG refills had been delivered to PMUY households since the scheme began.', 'achievement', '10.33 crore', 'PMUY LPG connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2090844');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (178, 7, '2025-04-03', 'Government steps to ensure affordable LPG', 'The release summarizes the expansion of Ujjwala 2.0 and the subsequent 75 lakh connection program, noting that both targets had been achieved. It reported 10.33 crore PMUY beneficiaries as of March 1, 2025.', 'achievement', '10.33 crore', 'PMUY beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2118208');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (179, 7, '2025-07-28', 'Government steps to encourage better LPG consumption by PMUY beneficiaries', 'The release describes measures intended to make LPG more affordable and encourage sustained use among PMUY beneficiaries, including subsidies, smaller-cylinder options and awareness campaigns. It reported that average per-capita consumption increased to 4.47 refills in FY 2024-25.', 'update', '4.47', 'average LPG refills per PMUY beneficiary household in FY 2024-25', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149224');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (180, 7, '2025-08-08', 'Continuation of targeted PMUY subsidy for FY 2025-26', 'The Union Cabinet approved a targeted subsidy of Rs.300 per 14.2 kg cylinder for up to nine refills per year for PMUY beneficiaries during FY 2025-26. The approved expenditure was Rs.12,000 crore, with about 10.33 crore PMUY connections reported as of July 1, 2025.', 'update', '12000', 'crore rupees', 'https://pib.gov.in/PressReleseDetailm.aspx?PRID=2154132');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (181, 7, '2025-09-22', 'Government approves 25 lakh additional Ujjwala connections', 'The Government approved the release of 25 lakh additional deposit-free LPG connections under PMUY during FY 2025-26. The measure was intended to clear pending applications and advance universal access to clean cooking fuel.', 'target', '25 lakh', 'additional LPG connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2169676');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (182, 9, '2021-09-25', 'SAUBHAGYA completes four years with 2.82 crore households electrified', 'The Ministry of Power reported that 2.82 crore households had been electrified under SAUBHAGYA through March 31, 2021. It also stated that previously unwilling households in seven states were later covered after expressing willingness to receive connections.', 'achievement', '2.82 crore', 'households electrified', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1757927');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (183, 9, '2022-03-24', 'SAUBHAGYA implementation status shows 2.86 crore households electrified', 'The government reported that all seven states with subsequently identified willing households had achieved 100% household electrification by March 31, 2021. Overall, 2.86 crore households had been electrified through SAUBHAGYA and associated support under DDUGJY.', 'update', '2.86 crore', 'households electrified', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1809294');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (184, 9, '2022-03-29', 'Guidelines issued for leftover households identified before SAUBHAGYA', 'The Ministry of Power said that approximately 19.09 lakh households identified before March 31, 2019 had initially declined connections but later expressed willingness to receive them. Guidelines were issued to cover any remaining households under the Revamped Distribution Sector Scheme, while states and union territories signed commitments related to 24x7 power supply.', 'update', '19.09 lakh', 'households that later expressed willingness for electrification', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1811047');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (185, 9, '2022-12-15', 'Rural electrification update reports 2.86 crore SAUBHAGYA connections', 'The Ministry of Power stated that 2.817 crore households had been electrified under SAUBHAGYA through March 2021, with additional households subsequently covered. The total reported number of households electrified reached 2.86 crore.', 'achievement', '2.86 crore', 'households electrified', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1883918');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (186, 9, '2023-03-14', 'SAUBHAGYA electrified 2.86 crore households and closed in 2022', 'The government reported that 2.86 crore households were electrified under SAUBHAGYA, including households that became willing to receive connections after initially declining. The scheme was reported as closed on March 31, 2022, with further left-out electrification to be addressed through RDSS.', 'achievement', '2.86 crore', 'households electrified', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1906743');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (187, 9, '2023-03-16', 'SAUBHAGYA scheme electrified 2.86 crore households', 'The Ministry of Power reiterated that 2.86 crore households had been electrified under SAUBHAGYA, including additional households that later expressed willingness for connections. It also reported that the scheme had closed on March 31, 2022, after sanctioned works were completed.', 'achievement', '2.86 crore', 'households electrified', 'https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1907728');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (188, 9, '2024-08-01', 'Household electrification under SAUBHAGYA reaches 2.86 crore', 'The Ministry of Power stated that all willing un-electrified rural households and all willing poor urban households had been provided electricity connections under SAUBHAGYA. The total number of households provided connections was reported as 2.86 crore, with RDSS support available for households left out.', 'achievement', '2.86 crore', 'households provided electricity connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2040101');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (189, 9, '2024-11-28', 'Maharashtra SAUBHAGYA electrification details reported', 'The government reported that approximately 2.86 crore households had been electrified nationally under SAUBHAGYA through March 31, 2022, and that all sanctioned works were complete. In Maharashtra, 589,242 households were electrified through grid and off-grid modes.', 'update', '589242', 'Maharashtra households electrified', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2078460');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (190, 9, '2025-08-18', 'SAUBHAGYA period completed with 2.86 crore households electrified', 'The Ministry of Power stated that all sanctioned SAUBHAGYA works had been completed and the scheme stood closed as of March 31, 2022. States reported that approximately 2.86 crore households received electricity connections, while remaining eligible households are being supported through RDSS and other programs.', 'achievement', '2.86 crore', 'households electrified', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157549');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (191, 10, '2023-12-11', 'Jal Jeevan Mission milestone: over 10 crore rural households connected', 'The Ministry of Jal Shakti reported that more than 10 crore rural households had received tap-water connections under Jal Jeevan Mission since its launch. Rural household coverage had exceeded 70 percent, compared with about 17 percent at the start of the mission.', 'achievement', '10', 'crore additional rural household tap-water connections', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2023/dec/doc20231211283801.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (192, 10, '2024-08-14', 'Jal Jeevan Mission reaches over 15 crore rural households', 'The government reported that Jal Jeevan Mission had provided 11.82 crore additional tap-water connections by August 12, 2024. Total rural household coverage exceeded 15.07 crore, representing 77.98 percent of rural households.', 'achievement', '15.07', 'crore rural households with tap-water connections', 'https://pib.gov.in/PressNoteDetails.aspx?ModuleId=3&NoteId=152025&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (193, 10, '2025-02-01', 'Jal Jeevan Mission provides tap water to 15 crore rural families', 'The Ministry of Jal Shakti stated that Jal Jeevan Mission had connected more than 15 crore rural households to tap water. Coverage was reported at 79.74 percent of rural households, up from 16.7 percent in August 2019.', 'achievement', '15', 'crore rural households with tap-water connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098651');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (194, 10, '2025-03-24', 'Current status of Jal Jeevan Mission', 'The government reported that about 12.30 crore additional rural households had received tap-water connections under Jal Jeevan Mission by March 17, 2025. More than 15.53 crore households, or 80.20 percent of rural households, were reported to have tap-water supply at home.', 'update', '15.53', 'crore rural households with tap-water supply', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2114280');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (195, 10, '2025-03-24', 'Surveys under Jal Jeevan Mission', 'The Ministry described the monitoring and assessment activities used to verify household tap-water coverage and functionality under Jal Jeevan Mission. The release emphasized state-level reporting, field verification and assessment of whether connections provide regular and quality-compliant water.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2114292');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (196, 10, '2025-03-27', 'Jal Jeevan Mission targets extension through 2028', 'The government said the mission''s proposed extension through 2028 would focus on completing remaining works and improving infrastructure quality and operations and maintenance. The extended approach would emphasize community participation and sustainable, citizen-centric water delivery.', 'target', '2028', 'target year for the proposed mission extension', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2115688');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (197, 10, '2025-04-03', 'Safe and pure water in rural areas', 'The Ministry reported that approximately 12.33 crore additional rural households had received tap-water connections by March 31, 2025. More than 15.56 crore households, or 80.38 percent of rural households, were reported to have tap-water supply at home.', 'achievement', '15.56', 'crore rural households with tap-water supply', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2118242');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (198, 10, '2025-07-24', 'Challenges under Jal Jeevan Mission', 'The government reported that approximately 12.43 crore additional rural households had been provided tap-water connections, taking total coverage above 15.67 crore households as of July 21, 2025. It identified water scarcity, contamination, difficult terrain, limited technical capacity and delays in clearances as major implementation challenges.', 'update', '15.67', 'crore rural households with tap-water supply', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2147698');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (199, 10, '2025-07-28', 'Jal Jeevan Mission proposed extension until 2028', 'The Ministry reported that about 12.44 crore additional rural households had received tap-water connections by July 23, 2025. It said the government was actively considering extending Jal Jeevan Mission until 2028 with enhanced funding and a stronger focus on infrastructure quality and maintenance.', 'target', '2028', 'proposed mission extension year', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149208');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (200, 10, '2025-07-28', 'Fluoride-affected habitations decline under Jal Jeevan Mission', 'The Ministry reported a decline in fluoride-affected habitations from 7,996 in April 2019 to 248 as of July 23, 2025. It attributed the response to source diversification, piped-water schemes and interim community purification measures in affected areas.', 'achievement', '248', 'fluoride-affected habitations reported as of 2025-07-23', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149210');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (201, 10, '2025-08-21', 'Nal Se Jal Mission reaches 81 percent rural household coverage', 'The Ministry reported that around 12.45 crore additional rural households had received tap-water connections by August 18, 2025. Overall coverage was reported at approximately 15.69 crore households, or 81.02 percent of rural households, with more than 2.63 lakh villages classified as Har Ghar Jal.', 'achievement', '15.69', 'crore rural households with tap-water supply', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2159041');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (202, 10, '2026-01-29', 'Tap water to all rural households', 'The government reported that about 12.56 crore additional rural households had received tap-water connections by January 24, 2026. More than 15.79 crore households, representing 81.56 percent of rural households, were reported to have tap-water supply, while almost the entire approved central budget had been utilized.', 'achievement', '15.79', 'crore rural households with tap-water supply', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2220143&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (203, 10, '2026-02-02', 'Impact of Jal Jeevan Mission', 'The Ministry reported that more than 15.79 crore rural households had tap-water connections as of January 29, 2026, with 189 districts and 2,50,021 villages reported as Har Ghar Jal. It also cited estimates that universal safe-water coverage could save women 5.5 crore hours daily and prevent nearly 400,000 diarrhoeal deaths.', 'achievement', '5.5', 'crore women-hours potentially saved per day', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2222149&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (204, 10, '2026-03-09', 'Implementation status of Jal Jeevan Mission', 'The government reported that more than 12.58 crore additional rural households had received tap-water connections by March 3, 2026. Overall household coverage stood at about 15.82 crore, or 81.71 percent, while an independent functionality assessment found that 76 percent of surveyed household connections were functional.', 'update', '76', 'percent of assessed household tap connections found functional', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2237014&lang=1&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (205, 10, '2026-03-22', 'Jal Jeevan Mission 2.0 guidelines released', 'The Department of Drinking Water and Sanitation released the operational guidelines for Jal Jeevan Mission 2.0 during the culmination of Jal Mahotsav 2026. The revised phase shifts emphasis from rapid infrastructure creation toward sustainability, functionality, accountability and long-term rural water service delivery through December 2028.', 'launch', '2028', 'end year of the extended JJM 2.0 period', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2243565&lang=2&reg=3');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (206, 3, '2026-06-07', 'West Bengal Set to Become the 36th State/UT to Implement Ayushman Bharat Pradhan Mantri Jan Arogya Yojana', 'The National Health Authority and the Government of West Bengal were scheduled to sign a Memorandum of Understanding for implementing AB PM-JAY in the state. The implementation would make West Bengal the 36th State/Union Territory covered by the scheme and extend health coverage of up to ₹5 lakh per family per year to eligible beneficiaries.', 'target', '36th', 'State/Union Territory', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2270056');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (207, 3, '2026-06-08', 'West Bengal Becomes 36th State/UT to Implement Ayushman Bharat PM-JAY', 'West Bengal became the 36th State/Union Territory to implement Ayushman Bharat PM-JAY after the National Health Authority signed an MoU with the state government. The inclusion is expected to extend health-assurance benefits to approximately 1.43 crore families and improve access to cashless treatment nationwide.', 'launch', '1.43', 'crore families', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2270375');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (208, 4, '2025-11-19', '21st Instalment of PM-KISAN: Direct Benefit Transfer of ₹18,000 crore to 9 crore farmers with focus on calamity-affected states', 'The 21st PM-KISAN instalment provides approximately ₹18,000 crore through Direct Benefit Transfer to nearly 9 crore farmers. The release highlights Aadhaar-based e-KYC, digital land records, the PM-KISAN portal, Kisan-eMitra and the PM-KISAN mobile app as tools supporting transparent delivery and farmer access.', 'achievement', '₹18,000 crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2191651');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (209, 4, '2025-11-19', 'Prime Minister Shri Narendra Modi releases the 21st instalment of PM-KISAN', 'The 21st instalment of PM-KISAN was released in Coimbatore, Tamil Nadu, providing approximately ₹18,000 crore in direct financial assistance to around 9 crore eligible farmers. The release states that more than ₹3.70 lakh crore had been disbursed to over 11 crore farmer families through the scheme’s first 20 instalments.', 'achievement', '9 crore', 'farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2191922');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (210, 4, '2025-11-19', '21st Instalment of PM-KISAN', 'The backgrounder describes the 21st PM-KISAN instalment as a ₹18,000-crore Direct Benefit Transfer for approximately 9 crore farmers, with particular focus on calamity-affected states. It also notes that more than ₹3.70 lakh crore had been disbursed to over 11 crore farmer families since the scheme began.', 'achievement', '9 crore', 'farmers', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2025/nov/doc20251120700401.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (211, 4, '2025-12-05', 'PM-KISAN and PMFBY Benefits extended to farmers in Maharashtra; PMFBY covers 93.81 lakh applications in Maharashtra', 'The release reports that the 21st PM-KISAN instalment benefited more than 9.34 crore farmers nationwide, including 4,63,142 beneficiaries in Kolhapur district. It states that over ₹4.09 lakh crore had been disbursed through 21 instalments, including ₹1,993.66 crore released to farmers in Kolhapur district.', 'update', '₹4.09 lakh crore', 'lakh crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2199678');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (212, 4, '2026-03-19', '22nd Instalment of PM-KISAN: Direct Benefit Transfer of over ₹18,640 crore to 9.32 crore farmers', 'The release states that more than ₹18,640 crore was transferred as the 22nd PM-KISAN instalment to over 9.32 crore farmers, including more than 2.15 crore women beneficiaries. The instalment was disbursed on March 13, 2026, from Guwahati, Assam, and total scheme disbursements had exceeded ₹4.27 lakh crore through 21 instalments.', 'achievement', '₹18,640 crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2242295');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (213, 4, '2026-06-20', '23rd Instalment of PM-KISAN: Direct Benefit Transfer of over ₹18,880 crore to 9.44 crore farmers', 'The 23rd PM-KISAN instalment transferred more than ₹18,880 crore in direct financial assistance to over 9.44 crore farmers, including 2.18 crore women farmers. The release says the instalment was disbursed on June 20, 2026, at Tarakeswar in Hooghly, West Bengal, and that cumulative disbursements had exceeded ₹4.46 lakh crore.', 'achievement', '₹18,880 crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2275744');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (214, 5, '2026-07-22', 'Beti Bachao Beti Padhao Scheme helps to address Child Sex Ratio and related issues of empowerment of girls and women', 'The scheme has expanded nationwide under Mission Shakti’s SAMBAL vertical through multisectoral interventions focused on behavioural and social change. The national Sex Ratio at Birth improved from 918 in 2014-15 to 929 in 2024-25, while girls’ secondary-level gross enrolment ratio rose to 83.4% in 2025-26.', 'update', '929', 'sex ratio at birth', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2287683');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (215, 7, '2025-12-01', 'PAHAL (DBTL) Scheme Delivers Improved Efficiency, Transparency, and Consumer-Centric Reforms', 'The release states that biometric Aadhaar authentication had been completed for 69% of existing PMUY beneficiaries as of November 1, 2025. It also reports that 8.63 lakh PMUY connections had been terminated through deduplication and related verification measures.', 'update', '69%', 'existing PMUY beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2197009');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (216, 7, '2025-12-04', 'Government Approves 25 Lakh Additional LPG Connections Under PMUY for FY 2025-26', 'The Government approved 25 lakh additional LPG connections under PMUY during FY 2025-26 to clear pending applications and achieve saturation of LPG access. The release also says eligibility was simplified to allow adult women from poor households to apply through a Deprivation Declaration.', 'target', '25 lakh', 'LPG connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2198768');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (217, 7, '2025-12-26', 'Year End Review 2025: Ministry of Petroleum & Natural Gas — Ujjwala Yojana Continues to Expand Clean Cooking Access across the Country', 'The Ministry reported that PMUY beneficiaries reached about 10.35 crore as of December 1, 2025. It also highlighted the approval of 25 lakh additional connections, simplified eligibility procedures, and a targeted subsidy of ₹300 per 14.2 kg cylinder for up to nine refills annually.', 'update', '10.35 crore', 'PMUY beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2208694');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (218, 9, '2026-02-02', 'Pradhan Mantri Sahaj Bijli Har Ghar Yojana', 'Under Saubhagya, 286 lakh households were electrified across the country against an estimated 300 lakh un-electrified households, and all States reported 100% electrification of willing households identified before March 31, 2019. The release also updates electrification works sanctioned under the Revamped Distribution Sector Scheme for additional households, including PVTG, tribal, Scheduled Caste, and remote-area households.', 'update', '286 lakh', 'households', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2222219');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (219, 11, '2023-12-04', 'Cleaning and Conservation of Rivers', 'The Ministry of Jal Shakti stated that river cleaning and rejuvenation are continuous processes, with the Central Government supporting States and Union Territories through the Namami Gange Programme for the Ganga and its tributaries. The release also described sewage-treatment approaches, monitoring systems, and innovations such as the Hybrid Annuity Model and One City-One Operator concept.', 'update', '22,500', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1982444');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (375, 42, '2023-12-12', 'PROPERTY CARDS', 'The Ministry of Panchayati Raj reported that states had prepared 1.63 crore property cards under the SVAMITVA Scheme as of 6 December 2023. Drone surveys had been completed in 2,88,942 villages, and ₹354.52 crore had been released under the scheme.', 'achievement', '1.63', 'crore property cards', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1985348');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (220, 11, '2025-03-07', 'A Holistic Approach for Cleanliness of River Ganga', 'The release describes Namami Gange as an integrated conservation mission focused on pollution abatement, conservation, and rejuvenation of the Ganga. It states that the programme was extended through March 2026 with a budgetary outlay of ₹22,500 crore and aims to improve sewage treatment, water quality, and industrial-waste regulation.', 'target', '22,500', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2109078');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (221, 11, '2025-03-07', 'Restoring the divine Glory of River Ganga: Namami Gange Programme achieves significant milestones', 'The Ministry of Jal Shakti reported progress in pollution abatement, ecological restoration, capacity building, and community engagement under Namami Gange. It stated that the programme had created 3,446 MLD of sewage-treatment capacity and completed 127 projects and 152 sewage-treatment plants.', 'achievement', '3,446', 'MLD', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2109118');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (222, 11, '2025-04-11', 'Namami Gange Mission 2.0: 7 major sewerage infrastructure projects completed in Uttar Pradesh, Bihar and Delhi in the 2nd half of FY 2024-25', 'Seven major sewerage-infrastructure projects were completed under Namami Gange Mission 2.0 in Uttar Pradesh, Bihar, and Delhi during the second half of financial year 2024-25. Their commissioning raised the programme’s total sewage-treatment capacity to 3,722 MLD and the number of commissioned STPs to 157.', 'achievement', '7', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2121047');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (223, 11, '2025-04-29', 'Unique Success of the Namami Gange Mission: The Return of the Red-Crowned Roofed Turtle to the Ganga After Three Decades', 'The release reported the reintroduction of the endangered Red-Crowned Roofed Turtle into the Ganga ecosystem after no confirmed report of an adult in the river’s main channel for about 30 years. Twenty turtles were transferred from the Garhaita Turtle Conservation Center and released into the Haiderpur Wetland, with sonic devices attached for monitoring.', 'achievement', '20', 'turtles', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2125277');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (224, 11, '2025-07-31', 'TARGETS ACHIEVED UNDER NAMAMI GANGE MISSION', 'The National Mission for Clean Ganga reported that 212 sewerage-infrastructure projects had been taken up to remediate polluted river areas, with a treatment capacity of 6,540 MLD. The release stated that 136 STP projects with a capacity of 3,780 MLD had been completed and made operational.', 'achievement', '3,780', 'MLD', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2150716');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (225, 11, '2025-07-31', 'ALLOCATION OF FUNDS UNDER NMCG', 'The Ministry of Jal Shakti stated that the Namami Gange Programme was extended through March 2026 and outlined its budgetary allocations since inception. Total allocation from financial year 2014-15 through 2025-26 was reported at ₹26,824.86 crore, including ₹3,400 crore in Budget Estimates for 2025-26.', 'update', '26,824.86', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2150722');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (226, 13, '2024-07-22', 'UNDER PRADHAN MANTRI KAUSHAL VIKAS YOJANA SCHEME, since 2015 till 30.6.2024, 1.48 crore candidates have been trained/oriented', 'The Ministry of Skill Development and Entrepreneurship reported that 1.48 crore candidates had been trained or oriented under PMKVY from its launch in 2015 through June 30, 2024. It also stated that 24.3 lakh of 56.88 lakh candidates certified under the first three versions were reported placed, a 42.8% placement rate.', 'achievement', '1.48', 'crore candidates', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2034984');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (227, 13, '2024-08-05', 'Under Pradhan Mantri Kaushal Vikas Yojana, skill development training has been imparted through Short-Term Training and up-skilling and re-skilling through Recognition of Prior Learning', 'The release said that 24.38 lakh candidates had been reported placed under PMKVY 1.0 to 3.0 as of June 30, 2024, including both self-employed and wage-employed candidates. It noted that placement tracking was delinked from PMKVY 4.0.', 'update', '24.38', 'lakh candidates placed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2041499');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (228, 13, '2025-02-01', 'Building a Future-Ready India', 'The release described PMKVY as a flagship Skill India Mission programme providing free short-duration training and incentives for skill certification. It reported that the scheme had trained or oriented 1.48 crore candidates since 2015 through June 30, 2024, while PMKVY 4.0 was being implemented for financial years 2022–2026.', 'achievement', '1.48', 'crore candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098551');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (229, 13, '2025-03-26', '1,60,33,081 candidates have been trained/oriented under the PMKVY scheme from 2015 to 2024', 'The Ministry reported that 1,60,33,081 candidates had been trained or oriented under PMKVY from 2015 through December 31, 2024. The release also stated that the reported placement rate among Short-Term Training-certified candidates through PMKVY 3.0 was 43%, while PMKVY 4.0 emphasizes career pathways rather than placement tracking.', 'achievement', '1,60,33,081', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2115272');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (230, 13, '2025-07-28', 'Flagship Skills Mission', 'The release stated that 24,37,887 candidates were reported placed nationwide under the Short-Term Training component of PMKVY 1.0, 2.0 and 3.0. It added that PMKVY 4.0 focuses on helping trained candidates choose varied career paths and includes digital tools such as the Skill India Digital Hub.', 'achievement', '24,37,887', 'candidates placed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149333');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (231, 13, '2025-08-06', 'Skill Development in Future Technologies and Job Placement', 'The Ministry reported that PMKVY had aligned more than 200 new-age and future-skills job roles with Industry 4.0 requirements, including AI/ML, robotics, electric vehicles, mechatronics and drone technology. Up to June 30, 2025, 4,32,712 candidates had been trained in these PMKVY job roles.', 'achievement', '4,32,712', 'candidates trained', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2153012');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (232, 14, '2022-12-07', 'Department for Promotion of Industry and Internal Trade (DPIIT) recognizes 59,787 entities as startups in the last five years', 'DPIIT recognized 59,787 entities as startups during 2017–2021 under the Startup India initiative. As of 30 November 2022, the total number of DPIIT-recognized startups had reached 84,102 across 56 sectors.', 'achievement', '59,787', 'startups recognized during 2017–2021', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1881492');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (233, 14, '2022-12-16', 'DPIIT-recognized startups create over 8.6 lakh direct jobs since the launch of Startup India', 'DPIIT-recognized startups self-reported creating 863,608 direct jobs from the launch of Startup India through 30 November 2022. The release states that 84,012 entities had been recognized as startups by DPIIT as of that date.', 'achievement', '8.6 lakh', 'direct jobs', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1884256');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (234, 14, '2023-04-05', 'More than 92,000 entities recognized as startups since launch of Startup India', 'DPIIT had recognized 92,683 entities as startups under the Startup India initiative as of 28 February 2023. The release also reports that 26,542 entities were recognized during 2022 alone.', 'achievement', '92,683', 'DPIIT-recognized startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1913977');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (235, 14, '2024-02-02', 'DPIIT recognises 1,17,254 startups as on 31st December 2023', 'The number of DPIIT-recognized startups increased to 117,254 as of 31 December 2023. These startups had reportedly created more than 12.42 lakh direct jobs, with at least one recognized startup present in every State and Union Territory.', 'achievement', '1,17,254', 'DPIIT-recognized startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2002100');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (236, 14, '2023-12-26', '2023 Year End Review for Department for Promotion of Industry and Internal Trade', 'The DPIIT year-end review reported that more than 1.14 lakh startups across all 36 States and Union Territories had created more than 12 lakh jobs. It also stated that Alternative Investment Funds supported under the Fund of Funds for Startups had invested ₹17,272 crore in 915 startups.', 'update', '17,272', 'crore invested in startups', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1990377');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (237, 14, '2024-07-26', 'Government undertakes various efforts to promote and support startups; more than 1.4 lakh startups recognized by DPIIT', 'The Government described initiatives under Startup India, including the Startup India Action Plan, the Seed Fund Scheme, and credit-support measures. DPIIT had recognized 140,803 entities as startups as of 30 June 2024.', 'update', '1,40,803', 'DPIIT-recognized startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2037579');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (238, 14, '2024-07-29', 'Government initiatives to promote startups across the country', 'The release outlines initiatives implemented by government departments to promote startups, including programs under the Startup India initiative. It reports 140,803 DPIIT-recognized startups and more than 15.5 lakh direct jobs as of 30 June 2024.', 'update', '15.5 lakh', 'direct jobs', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2038380');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (239, 14, '2024-08-06', '15.53 lakh direct jobs created by recognized startups', 'DPIIT-recognized startups had self-reported creation of 1,553,288 direct jobs as of 30 June 2024. The release provides year-wise job figures and attributes the results to the Startup India initiative and related government support programs.', 'achievement', '15.53 lakh', 'direct jobs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2042116');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (240, 14, '2024-08-09', 'Over 1 lakh 40 thousand recognized start-ups in the country; over 67 thousand have at least one woman director', 'As of 30 June 2024, DPIIT had recognized 140,803 entities as startups under the Startup India initiative. The release states that 67,499 recognized startups had at least one woman director and that recognized startups had created more than 15.53 lakh direct jobs.', 'achievement', '67,499', 'startups with at least one woman director', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2043805');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (241, 14, '2024-12-25', 'Startup Nation: India — The Future Hub of Global Entrepreneurship', 'The release highlights India’s growth as a major startup ecosystem and reports 157,066 startups recognized by DPIIT as of 25 December 2024. It also notes more than 73,000 recognized startups with at least one woman director and describes support measures including funding, compliance simplification, and the BHASKAR platform.', 'update', '1,57,066', 'DPIIT-recognized startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2087835');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (242, 14, '2025-02-01', 'India’s Startup Revolution: 1.57 lakh startups and 17.28 lakh jobs mark a decade of progress', 'The release reports 157,706 DPIIT-recognized startups as of 31 December 2024, alongside more than 17.28 lakh direct jobs. It also states that 75,935 recognized startups had at least one woman director.', 'achievement', '17.28 lakh', 'direct jobs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098452');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (243, 14, '2025-12-02', 'The Department for Promotion of Industry and Internal Trade recognises 1,97,692 startups under Startup India initiative', 'DPIIT had recognized 197,692 entities as startups under the Startup India initiative as of 31 October 2025. The release presents the recognition figure as part of the Government’s continuing effort to strengthen startup growth and the recognition framework.', 'update', '1,97,692', 'DPIIT-recognized startups', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2197662');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (244, 14, '2026-02-13', 'Startup India recognises 2.07 lakh ventures, creates 21.9 lakh jobs; Government expands funding push', 'As of 31 December 2025, DPIIT had recognized 207,135 startups, which had generated more than 21.9 lakh direct jobs. The release also reports funding and support through the Fund of Funds for Startups, the Startup India Seed Fund Scheme, and the Credit Guarantee Scheme for Startups.', 'achievement', '21.9 lakh', 'direct jobs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2227597');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (245, 13, '2025-08-11', 'Climate-Resilient Employment Planning', 'The Ministry of Skill Development and Entrepreneurship states that PMKVY includes agriculture and allied-sector job roles addressing climate-related challenges such as heat stress, crop failure and desertification. These programs are intended to support labour transition and climate-resilient livelihoods in vulnerable regions.', 'achievement', '10,87,743', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2155053');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (246, 13, '2025-12-08', 'PMKVY Training and Employment Outcomes', 'The Ministry of Skill Development and Entrepreneurship reports that PMKVY 4.0 uses market-oriented and demand-driven training, with on-the-job training embedded in industry-relevant courses. The release also explains that placement tracking applied to the first three PMKVY versions, while PMKVY 4.0 focuses on helping trained candidates pursue varied career paths.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2200387');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (247, 13, '2026-01-23', 'Year End Review 2025: Ministry of Skill Development and Entrepreneurship', 'The Ministry’s year-end review states that PMKVY 4.0 had trained candidates across 38 sectors and 36 States by December 2025. It also highlights expanded future-skill courses, Skill Hubs, institutional participation and convergence with other national missions.', 'achievement', '27.08', 'lakh candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2217881');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (248, 13, '2026-02-02', 'Skill India Digital Hub', 'The release describes the Skill India Digital Hub as a platform integrating training, assessment, certification and related skilling services. It reports that PMKVY 4.0 trained and certified candidates in the Chatra Parliamentary Constituency of Jharkhand, alongside broader onboarding of candidates and stakeholders onto the platform.', 'update', '1,590', 'PMKVY 4.0 candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2222120');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (249, 13, '2026-03-11', 'Generating Job-Ready Youth under Pradhan Mantri Kaushal Vikas Yojana', 'The Ministry reports that PMKVY has trained or oriented candidates nationwide since 2015, with certified candidates forming a substantial portion of the total. For PMKVY 1.0 to 3.0, the release reports placements among Short-Term Training candidates, while PMKVY 4.0 emphasizes career choice, self-employment and wage employment through industry-relevant courses and on-the-job training.', 'achievement', '1.64', 'crore candidates trained/oriented', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2238230');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (250, 13, '2026-03-18', 'Skill Development in AI, Digital and Emerging Technologies', 'The Ministry states that PMKVY 4.0 offers courses in artificial intelligence, machine learning, robotics, drones, industrial IoT and other emerging fields. According to Skill India Digital Hub data, candidates had been trained in futuristic job roles, with funding allocated for digital-skills training.', 'achievement', '5.10', 'lakh candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2241726');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (251, 13, '2026-03-30', 'Jobs for Skill Trained Youth', 'The Ministry reports cumulative PMKVY training figures through December 2025 and explains that placement tracking was conducted for the Short-Term Training component of PMKVY 1.0 to 3.0. It also cites an evaluation showing an increase in the combined share of employed and self-employed respondents after PMKVY 4.0 training.', 'achievement', '45.4%', 'employed or self-employed STT respondents after training', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2246880');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (252, 13, '2026-07-20', 'Strengthening Skill Development Ecosystem', 'The Ministry outlines measures under PMKVY 4.0 to expand quality, transparency and industry relevance through the Skill India Digital Hub and industry-led training. It highlights future-skill training in areas including artificial intelligence, robotics, cloud computing, IoT and green technologies, while noting reported placements under PMKVY 1.0 to 3.0.', 'update', '24.38', 'lakh candidates reported placed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2286589');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (253, 16, '2023-08-16', 'Union Cabinet approves expansion of the Digital India programme with an outlay of ₹14,903 crore', 'The Union Cabinet approved expansion of the Digital India programme with a total outlay of ₹14,903 crore. The expansion includes reskilling 6.25 lakh IT professionals, training 2.65 lakh people in information security, adding 540 UMANG services, deploying nine supercomputers, and supporting 1,200 startups in Tier 2 and Tier 3 cities.', 'target', '14,903', 'crore', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1949427');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (254, 16, '2024-09-10', 'Ministry of Electronics and Information Technology launches Phase III of capacity-building initiatives under Digital India vision', 'MeitY launched the third phase of its capacity-building initiatives under the Digital India vision. The programmes cover Digital Public Infrastructure, artificial intelligence and machine learning, digital governance, data management, and management of large digital transformation projects; the regional programme began with 32 participants.', 'launch', '32', 'participants', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2053495');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (255, 16, '2025-01-28', 'Future Ready: India’s Digital Economy to Contribute One-Fifth of National Income by 2029-30', 'The Ministry of Electronics and Information Technology reported that India’s digital economy accounted for 11.74% of GDP in 2022-23 and employed 14.67 million workers. It is projected to grow to nearly one-fifth of national income by 2029-30, driven by digital platforms, artificial intelligence, cloud services, and wider digitalisation.', 'target', '20', 'percent of national income', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2097125');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (256, 18, '2022-03-24', 'AMRUT focuses on development of infrastructure in the water sectors; States/UTs have taken up 5,850 projects worth ₹81,283 crore under AMRUT', 'The release states that AMRUT covers water supply, sewerage and septage management, storm-water drainage, non-motorized transport, and green spaces. States and Union Territories had taken up 5,850 projects worth ₹81,283 crore, with 4,158 projects completed and 126 lakh water tap and 95 lakh sewer connections provided.', 'achievement', '5850', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1809157');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (257, 18, '2022-03-31', 'AMRUT 2.0 aims to provide water supply through functional taps to all households in statutory towns and coverage of sewerage/septage management', 'AMRUT 2.0 is intended to provide universal functional tap-water coverage in all statutory towns and sewerage or septage-management coverage in the 500 cities covered under the first phase of AMRUT. The scheme has an indicative outlay of ₹2,99,000 crore, including a central outlay of ₹76,760 crore, for five years.', 'target', '299000', 'crore', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1811880');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (258, 18, '2022-08-01', 'The Central allocation of ₹66,750 crore for AMRUT 2.0 projects has been distributed', 'The Ministry stated that the central allocation for AMRUT 2.0 projects had been distributed among States and Union Territories for the full mission period. Allocations were determined using an equitable formula based mainly on urban population and area.', 'update', '66750', 'crore', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1846993');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (259, 18, '2022-12-08', 'STATUS OF AMRUT', 'The release reports that all State and Union Territory State Annual Action Plans under AMRUT had been approved for ₹77,640 crore, including ₹35,990 crore in committed central assistance. States and Union Territories had taken up 5,873 projects worth ₹82,222 crore, with 4,676 projects completed.', 'achievement', '5873', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1881751');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (260, 18, '2023-03-20', 'SUCCESS OF AMRUT', 'The release describes AMRUT as having been subsumed under AMRUT 2.0, while funding for ongoing and eligible AMRUT projects continued through March 2023. It reports approved State Annual Action Plans totaling ₹77,640 crore and notes that project implementation was monitored through Apex Committee reviews, independent monitoring agencies, and a dedicated portal.', 'achievement', '77640', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1908856');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (261, 18, '2023-03-27', 'STATUS OF AMRUT 2.0', 'AMRUT 2.0 extends the objective of universal water-supply coverage from 500 AMRUT cities to all statutory towns and focuses on water security and sewerage or septage management. State Water Action Plans covering 6,527 projects worth ₹1,29,636 crore had been approved, including plans for 148 lakh new tap connections and 33.42 lakh new sewer connections.', 'update', '6527', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1911162');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (262, 18, '2023-12-11', 'Planned development in Urban Areas', 'The release describes AMRUT’s GIS-based master-plan initiative for the 500 AMRUT cities, reporting final GIS databases for 443 towns and notified master plans for 180 towns. Under AMRUT 2.0, a GIS-based master-plan scheme was launched for Class-II towns and approved for 675 towns with an outlay of ₹631 crore.', 'launch', '675', 'towns', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1984976');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (263, 18, '2024-08-08', 'IMPACT OF AMRUT ON INFRASTRUCTURE AND SERVICES', 'The Ministry reported that AMRUT had grounded 5,996 projects worth ₹83,345 crore, with works worth ₹77,691 crore physically executed. The mission had provided 189 lakh water tap connections and 149 lakh sewer connections, exceeding targets of 139 lakh and 145 lakh respectively.', 'achievement', '189', 'lakh water tap connections', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2043167');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (264, 18, '2024-11-28', 'SALIENT FEATURES OF AMRUT 2.0', 'The release states that AMRUT 2.0 had approved 8,998 projects worth ₹1,89,458.55 crore, including operations and maintenance costs. Contracts had been awarded for 4,916 projects worth ₹85,114.01 crore, while ₹11,756.13 crore in central assistance had been released to States and Union Territories.', 'update', '8998', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2078409');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (265, 18, '2025-02-06', 'Gender Equality And Empowerment Of Women For Urban Planning', 'The release reports the use of SCADA and other smart technologies in AMRUT water-supply and sewerage projects, including implementation in 230 water-supply and 146 sewerage projects. It also states that 57,134 functionaries had been trained under AMRUT against a target of 45,000, and highlights the AMRUT Mitra initiative involving women’s self-help groups.', 'achievement', '57134', 'functionaries trained', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100340');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (266, 18, '2025-03-27', 'UPGRADATION OF STPs', 'Under AMRUT, 890 sewerage and septage-management projects worth ₹34,505 crore had been grounded, creating or augmenting 4,447 MLD of sewage-treatment capacity, including 1,437 MLD for recycling or reuse. Under AMRUT 2.0, 592 projects worth ₹67,607.67 crore had been approved, covering 6,739 MLD of treatment capacity.', 'achievement', '4447', 'MLD sewage-treatment capacity', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2115832');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (267, 13, '2026-07-27', 'Skilling for Space and Geospatial Sectors', 'The Ministry of Skill Development and Entrepreneurship is promoting skill development in space and geospatial technologies through PMKVY, NAPS and related initiatives. IN-SPACe has introduced 11 short-term space-technology courses, through which more than 1,000 candidates have been trained nationwide.', 'achievement', 'over 1,000', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2289890');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (268, 16, '2025-03-19', 'Government of India Expands AI-Driven Skilling; India AI Mission Gains Momentum with 67 Proposals for Indigenous AI Models; Digital India Bhashini Initiative Boosts AI-Powered Vernacular Language Accessibility', 'The release highlights the Government’s AI-for-All approach and progress under the IndiaAI Mission. It reports that 67 proposals were received for indigenous foundation models, while the Digital India Bhashini initiative is advancing access to AI-powered services in Indian languages.', 'achievement', '67', 'proposals', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113095');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (269, 16, '2025-04-27', 'NIELIT Signs MoUs with 8 Visionary Organizations to Propel Digital India Initiatives', 'NIELIT signed memorandums of understanding with eight organizations to strengthen education, skilling, research, and innovation in electronics and information technology. The collaborations cover joint research, curriculum development, capacity building, training, and emerging technologies.', 'achievement', '8', 'organizations', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2124706');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (270, 16, '2025-12-12', 'Government’s Initiatives to Make Information Technology Accessible to Citizens Residing in Rural, Hilly and Remote Areas of the Country; Digital India Programme Bridging the Urban-Rural Divide', 'The release describes Digital India initiatives aimed at expanding digital infrastructure, delivering government services online, and improving digital literacy in rural, hilly, and remote areas. As of October 2025, 5.67 lakh Common Services Centres were functional nationwide, including 4.41 lakh at the Gram Panchayat level.', 'achievement', '5.67 lakh', 'functional Common Services Centres', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2202905');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (271, 19, '2022-07-27', 'Development of Rural Roads', 'The release states that PMGSY-III was launched in 2019 to consolidate 1,25,000 km of Through Routes and Major Rural Links connecting habitations to markets, higher secondary schools and hospitals. As of July 21, 2022, 7,93,568 km of roads and 10,082 bridges had been sanctioned across PMGSY interventions, with 7,12,638 km of roads and 7,264 bridges completed.', 'update', '1,25,000', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1845369');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (272, 19, '2024-07-26', 'Ministry of Rural Development announces Major Infrastructure Boost for State of Kerala', 'The Ministry of Rural Development sanctioned 33 roads measuring 159.86 km for Kerala under PMGSY-III. The projects involve an estimated investment of Rs. 160.56 crore and are intended to improve rural connectivity and access to markets, healthcare and education.', 'target', '160.56', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2037595');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (273, 19, '2024-10-24', 'Ministry of Rural Development Announces Infrastructure Boost for North-Eastern Region with an estimated investment of Rs. 1,056.82 crore in Meghalaya under Pradhan Mantri Gram Sadak Yojana-III', 'The Ministry sanctioned 88 roads covering 782.155 km and 55 bridges under PMGSY-III for Meghalaya. The estimated investment is Rs. 1,056.82 crore, aimed at strengthening rural connectivity and access to essential services.', 'target', '1,056.82', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2067719');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (274, 19, '2024-10-24', 'Ministry of Rural Development Announces Infrastructure Boost for North-Eastern Region with an estimated investment of Rs. 54.75 crore in Nagaland under Pradhan Mantri Gram Sadak Yojana-III', 'The Ministry sanctioned 55.89 km of road length under PMGSY-III for Nagaland. The projects carry an estimated investment of Rs. 54.75 crore and are intended to improve access to healthcare, education and markets in rural areas.', 'target', '54.75', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2067723');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (275, 19, '2025-07-29', 'Infrastructure Developed under PMGSY-III', 'The release reports that 15,972 roads covering 1,22,419 km and 3,212 bridges had been sanctioned under PMGSY-III as of July 25, 2025. Of these, 11,727 roads covering 98,588 km and 1,373 bridges had been constructed across the country.', 'achievement', '98,588', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149727');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (276, 24, '2023-08-04', 'Update on Strengthening The Healthcare System', 'The Ministry of Health and Family Welfare described National Health Mission support for strengthening state and Union Territory public healthcare systems. As of July 24, 2023, 160,480 Ayushman Bharat Health and Wellness Centres had been operationalized to provide comprehensive primary healthcare.', 'achievement', '1,60,480', 'Ayushman Bharat Health and Wellness Centres', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1945741');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (277, 24, '2024-09-09', 'Health Ministry Releases "Health Dynamics of India (Infrastructure and Human Resources) 2022-23"', 'The Health Ministry released the annual Health Dynamics of India publication, formerly known as Rural Health Statistics. The publication provides state-wise information on healthcare infrastructure and human resources relevant to the National Health Mission and is intended to support planning, monitoring and policy decisions.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2053070');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (278, 24, '2024-12-17', 'Update on National Health Mission', 'The release outlines National Health Mission support for public healthcare systems through initiatives including Ayushman Arogya Mandirs, ambulance services, mobile medical units, ASHAs, dialysis and immunization programs. It reports reductions in maternal mortality, infant mortality and total fertility, along with 36.16 crore Ayushman Cards created as of December 12, 2024.', 'achievement', '36.16 crore', 'Ayushman Cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085208');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (279, 24, '2025-01-22', 'Achievements under National Health Mission (2021-24): A Milestone in Improving India’s Public Health Outcomes', 'The Ministry reported substantial progress under the National Health Mission during financial years 2021-22 through 2023-24. NHM engaged more than 12 lakh additional healthcare workers, supported 220 crore COVID-19 vaccine doses and contributed to improvements in maternal and child health, disease control and healthcare infrastructure.', 'achievement', '12 lakh', 'additional healthcare workers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2095062');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (280, 24, '2025-02-07', 'Update on Status of Healthcare Infrastructure under NHM', 'The release describes the extension of the National Health Mission for financial years 2021-22 through 2025-26 and reports progress against its health-system targets. It states that 176,325 Ayushman Arogya Mandirs had been operationalized as of January 31, 2025, while full immunization coverage reached 93.6% as of October 31, 2024.', 'update', '1,76,325', 'Ayushman Arogya Mandirs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100595');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (281, 16, '2026-03-18', 'Digital India program has enabled wider access to digital services and opportunities; 400% increase in broadband subscribers over a decade', 'The release states that the Digital India programme has expanded access to digital services and opportunities across India. Broadband subscribers increased from 25 crore in 2014-15 to 103 crore in 2024-25, representing a 400% rise.', 'achievement', '400', '% increase in broadband subscribers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2241781');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (282, 16, '2026-06-10', 'DigiLocker Experiences Massive Expansion: Electricity distribution utilities are now live for millions of consumers nationwide', 'DigiLocker has onboarded 68 electricity distribution companies and power departments across 35 States and Union Territories. The integration enables consumers to access issuer-sourced digital electricity bills through the DigiLocker application.', 'update', '68', 'electricity distribution companies and power departments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2271375');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (283, 16, '2026-06-17', 'Mahasarathi (Family ID) Now on DigiLocker: 14 Crore Citizens Get Instant Digital Access', 'The release announces that residents of Maharashtra can access their Mahasarathi Family ID through DigiLocker. The initiative provides digital access to the identity document for approximately 14 crore residents.', 'launch', '14', 'crore residents', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2273958');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (284, 16, '2026-06-27', 'Digital India Nears 11 Years, Driving India''s Next Phase of Technology-Led Growth through Artificial Intelligence, Semiconductor Manufacturing, Digital Public Infrastructure and Affordable Digital Connectivity', 'The release reviews Digital India''s progress and highlights investments in semiconductors, artificial intelligence, digital public infrastructure and connectivity. It reports that ₹1.64 lakh crore has been approved across 12 semiconductor projects and that a shared compute facility with more than 45,000 GPUs is strengthening India''s AI ecosystem.', 'achievement', '1.64', 'lakh crore approved across semiconductor projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2278453');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (285, 16, '2026-07-11', '11 Years of Digital India: eSaras Online Market & Melas Strengthening Rural Livelihoods through Digital Commerce', 'The release describes eSaras, developed by the Digital India Corporation under MeitY in collaboration with the Ministry of Rural Development, as a digital marketplace for rural women-led enterprises and producer organisations. It reports that the platform supports more than 8.99 crore registered Self-Help Group members and offers over 1,400 products.', 'achievement', '8.99', 'crore registered SHG members', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2283704');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (286, 25, '2022-02-07', 'Focus on Universal Immunization: Dr. Mansukh Mandaviya launches Intensified Mission Indradhanush (IMI) 4.0', 'The Union Health Minister launched Intensified Mission Indradhanush 4.0 to cover partially vaccinated and unvaccinated children and pregnant women. The campaign was planned in three rounds across 416 districts in 33 States and Union Territories.', 'launch', '416', 'districts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1796099');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (287, 25, '2023-08-08', 'Update on Mission Indradhanush', 'The release reports that Intensified Mission Indradhanush 4.0 was conducted in 416 high-focus districts during 2022. It also states that six States or Union Territories achieved 100% full immunization coverage and 17 States achieved coverage above 90% under HMIS 2022-23.', 'update', '416', 'districts', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1946705');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (288, 25, '2023-10-12', 'Intensified Mission Indradhanush 5.0 campaign with special focus on improvement of Measles and Rubella vaccination coverage will conclude all three rounds on 14 October 2023', 'The release says IMI 5.0 was being conducted across all districts for the first time and expanded eligibility to children up to five years of age. During the first two rounds, more than 34.69 lakh children and 6.55 lakh pregnant women had received vaccine doses as of September 30, 2023.', 'update', '34,69,705', 'children', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1966931');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (289, 25, '2024-07-18', 'Myth vs. Facts: Media reports highlighting high number of zero-dose children in India paint an incomplete picture of India’s immunization efforts', 'The release states that 5.46 crore children and 1.32 crore pregnant women had been vaccinated under Mission Indradhanush through 2023. It also reports that full immunization coverage for the country was 93.23% in FY 2023-24.', 'achievement', '5.46', 'crore children', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2034080');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (290, 25, '2024-12-17', 'Update on Mission Indradhanush: More than 5.46 crore children and 1.32 crore pregnant women have been vaccinated in all phases of Mission Indradhanush conducted so far', 'The release describes Mission Indradhanush as a catch-up vaccination campaign for children and pregnant women missed by routine immunization services. It reports that 5.46 crore children and 1.32 crore pregnant women had been vaccinated across all phases conducted in the country.', 'achievement', '5.46', 'crore children', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085204');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (291, 26, '2023-02-03', 'Utilization of Funds Under POSHAN Abhiyaan', 'The Ministry of Women and Child Development reported that, as of 31 March 2022, funds had been allocated to States and Union Territories under POSHAN Abhiyaan since the scheme’s launch in 2018. The release presented the financial utilization position of the programme.', 'update', '5,40,295.40', 'lakh rupees allocated', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1896116');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (292, 26, '2023-03-19', '5th Poshan Pakhwada celebrations begin tomorrow', 'The Ministry announced that the fifth Poshan Pakhwada would be held from 20 March to 3 April 2023 nationwide. The campaign focused on popularising Shree Anna, holding Swasth Balak Spardha activities, and promoting Saksham Anganwadis through Jan Andolan and Jan Bhagidari.', 'launch', '15', 'days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1908478');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (293, 26, '2023-03-24', 'MISSION POSHAN 2.0', 'The release described Mission POSHAN 2.0 as an integrated nutrition support programme building on POSHAN Abhiyaan. It highlighted improvements in nutrition quality and testing, technology-enabled monitoring through Poshan Tracker, diet diversity, food fortification, and promotion of millets.', 'update', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1910097');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (294, 26, '2023-08-31', 'Ministry of Women and Child Development celebrating the 6th Rashtriya Poshan Maah throughout September 2023', 'The Ministry announced the sixth Rashtriya Poshan Maah for September 2023 under the life-cycle approach of Mission Poshan 2.0. The campaign focused on improving awareness and action around nutrition during pregnancy, infancy, childhood, and adolescence under the theme of a nutrition-rich, educated, and empowered India.', 'launch', '6th', 'Rashtriya Poshan Maah', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1953762');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (295, 26, '2023-09-04', 'Close to 10 lakh activities witnessed across the country on the 1st day of Rashtriya Poshan Maah 2023', 'The Ministry reported that the first day of Rashtriya Poshan Maah 2023 saw nearly 10 lakh activities nationwide. Activities included Mission LiFE nutrition initiatives, exclusive breastfeeding and complementary-feeding awareness, and other Jan Andolan efforts.', 'achievement', '10', 'lakh activities', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1954582');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (296, 26, '2024-02-29', 'Poshan Utsav: Celebrating Nutrition to promote good nutrition behavior', 'The Ministry organized Poshan Utsav to promote good nutrition practices and highlight efforts to combat malnutrition. The event included the release of the Poshan Utsav Book and the announcement of a Cartoon Coalition to communicate nutrition messages to children.', 'launch', '75', 'million children measured monthly', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2010436');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (297, 26, '2024-08-31', 'Union Minister Smt Annpurna Devi launches 7th Rashtriya Poshan Maah 2024', 'The seventh Rashtriya Poshan Maah was launched in Gandhinagar, Gujarat, under Mission Poshan 2.0. Its focus themes included anaemia, growth monitoring, complementary feeding, Poshan Bhi Padhai Bhi, technology for better governance, and the Ek Ped Maa Ke Naam initiative.', 'launch', '7th', 'Rashtriya Poshan Maah', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2050437');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (298, 26, '2024-09-18', 'Rashtriya Poshan Maah 2024 emphasises consumption of balanced diet', 'The Ministry stated that the seventh Rashtriya Poshan Maah was promoting balanced diets and healthy nutrition practices. The campaign also addressed breastfeeding, complementary feeding, the first 1,000 days, sanitation, diarrhoea, and anaemia through community engagement and inter-ministerial collaboration.', 'update', '150', 'grams of fruit in the cited daily balanced-diet example', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2059025');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (299, 26, '2024-09-29', 'Smt. Annpurna Devi to grace closing ceremony of 7th Rashtriya Poshan Maah 2024 at Ranchi tomorrow', 'The Ministry announced the closing ceremony of the seventh Rashtriya Poshan Maah and reported that around 12 crore activities had been conducted by States and Union Territories during the campaign. The release also said that more than 11,000 Saksham Anganwadi Centres would be inaugurated virtually.', 'achievement', '12', 'crore activities', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2060026');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (300, 26, '2025-01-31', 'Year End Review: Achievements of Ministry of Women and Child Development, Government of India, 2024', 'The Ministry’s year-end review reported progress under Mission Saksham Anganwadi and POSHAN 2.0, including digital nutrition monitoring through Poshan Tracker and community sensitisation activities. It stated that Poshan Tracker was tracking more than 10 crore beneficiaries and that over 30 crore community sensitisation activities were conducted in 2024.', 'achievement', '10', 'crore beneficiaries', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2098874');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (301, 28, '2022-12-07', 'Universalisation of quality Education under SSA', 'The Ministry of Education describes Samagra Shiksha as an integrated scheme covering school education from pre-school through Class 12. It outlines the scheme’s alignment with NEP 2020 and its focus on equitable access, foundational literacy and numeracy, inclusion, teacher education, and vocational education.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1881444');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (302, 28, '2024-08-07', 'Quality Education', 'The Ministry of Education states that Samagra Shiksha supports quality and inclusive education for children from pre-school to Class 12. It provides assistance for school grants, uniforms and textbooks, ICT initiatives, remedial teaching, KGBVs, residential schools, hostels, and support for children with special needs.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2042674');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (303, 28, '2024-07-29', 'Accessibility and Inclusivity in Education for Divyangs', 'The Ministry of Education explains that Samagra Shiksha includes a dedicated inclusive-education component for children with special needs. Support includes assessment, assistive devices, transportation, Braille and large-print materials, stipends for girls with special needs, therapeutic interventions, and barrier-free school infrastructure.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2038623');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (304, 28, '2024-07-23', 'Shri Dharmendra Pradhan hails Budget 2024-25 as pivotal milestone on India''s path to becoming a developed nation by 2047', 'The Union Education Minister highlighted increased education-related allocations in the Union Budget 2024-25, including additional funding for Samagra Shiksha. The release presents the allocation as part of broader efforts to improve access to education, skilling, employment, and human-capital development.', 'achievement', '4500', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2036125');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (305, 28, '2025-01-09', 'Year End Review 2024: Department of School Education & Literacy', 'The Ministry of Education reports Samagra Shiksha achievements from 2018-19 through 2024-25, including school upgrades, strengthened schools, ICT and digital initiatives, vocational-education coverage, KGBV upgrades, and construction of girls’ toilets. The scheme continues to support universalization of school education from pre-primary through Class 12.', 'achievement', '80105', 'schools strengthened', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2091737');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (306, 28, '2025-02-01', 'Union Education Minister lauds historic Budget 2025-26', 'The Ministry of Education states that the Union Budget 2025-26 increased the allocation for Samagra Shiksha compared with the 2024-25 revised estimate. The release places the increase within a wider expansion of education, connectivity, innovation, and school infrastructure initiatives.', 'achievement', '4240', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098805');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (307, 29, '2024-12-06', 'Government has approved the Centrally Sponsored Scheme ‘Pradhan Mantri Poshan Shakti Nirman (PM POSHAN)’ earlier known as ‘National Programme for Mid-Day Meal in Schools’', 'The release states that PM POSHAN provides hot cooked meals to eligible children in Government and Government-aided schools from 2021-22 to 2025-26. It also highlights additional features including Balvatika coverage, Tithi Bhojan, School Nutrition Gardens, mandatory social audits, locally sourced foods, and meal provision during disasters.', 'update', '2021-22 to 2025-26', 'scheme period', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2082323');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (308, 29, '2024-12-09', 'Enhancement of ‘Material Cost’ under the Pradhan Mantri Poshan Shakti Nirman (PM POSHAN) Scheme', 'The Ministry of Education enhanced PM POSHAN material costs by 13.70% with effect from December 1, 2024. Rates increased from ₹5.45 to ₹6.19 per meal for Balvatika and primary classes, and from ₹8.17 to ₹9.29 for upper-primary classes; the Centre will bear an additional ₹425.62 crore in 2024-25.', 'update', '13.70%', 'increase', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2082529');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (309, 29, '2025-04-10', 'Enhancement of ‘Material Cost’ under the Pradhan Mantri Poshan Shakti Nirman (PM POSHAN) Scheme', 'The Ministry of Education announced a 9.50% enhancement in PM POSHAN material costs, applicable nationwide from May 1, 2025. The revised rates are ₹6.78 per student per day for Balvatika and primary classes and ₹10.17 for upper-primary classes, with an estimated additional central expenditure of ₹954 crore in 2025-26.', 'update', '9.50%', 'increase', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2120666');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (310, 30, '2023-02-01', 'Ministry of Youth Affairs and Sports receives Budget allocation of Rs. 3397.32 crore for FY 2023-24, with an increase of 11% over FY 2022-23; substantial increase in budget outlay for Khelo India', 'The Ministry received a budget allocation of Rs. 3397.32 crore for FY 2023-24, representing an 11% increase over the previous year. The allocation for the Khelo India programme was increased to Rs. 1000 crore.', 'update', '1000', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1895711');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (311, 30, '2023-03-06', 'Khelo India Dus Ka Dum tournament to be organized in 10 cities to celebrate International Women’s Day', 'The Ministry of Youth Affairs and Sports announced the Khelo India Dus Ka Dum tournament as a women-focused sports initiative. The tournament was scheduled to be held in 10 cities from March 10 to 31, 2023.', 'launch', '10', 'cities', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1904904');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (312, 30, '2022-12-20', 'Year End Review: Events organized under the Khelo India Scheme', 'The Department of Sports reported that the fourth Khelo India Youth Games and the second Khelo India University Games had been organized successfully. It also noted approval of the Khelo India Scheme for continuation through the 15th Finance Commission cycle from 2021-22 to 2025-26.', 'achievement', '2', 'Khelo India Games editions', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1885086');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (313, 30, '2023-11-26', 'First-ever Khelo India Para Games 2023 logo and mascot Ujjwala launched', 'The Union Minister for Youth Affairs and Sports launched the logo and mascot Ujjwala for the inaugural Khelo India Para Games. The release said the event would expand the Khelo India platform to identify and support talented para athletes.', 'launch', '11', 'Khelo India Games held since 2018', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1979984');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (314, 30, '2023-12-10', 'Union Minister Shri Anurag Singh Thakur to inaugurate first-ever Khelo India Para Games 2023', 'The inaugural Khelo India Para Games were scheduled in New Delhi from December 10 to 17, 2023. More than 1400 players from 32 states and Union Territories and the Services Sports Board were set to compete across seven para-sport disciplines.', 'launch', '1400', 'players', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1984775');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (315, 30, '2024-02-08', 'Over Rs. 30.83 crore released to Khelo India Athletes in 2023-24 under scholarship scheme', 'The Sports Authority of India released Rs. 30.83 crore to Khelo India Athletes during 2023-24, including the fourth-quarter out-of-pocket allowance for 2571 athletes. The release stated that close to 3000 athletes receive support for training, coaching, diet, equipment, medical insurance and allowances.', 'update', '30.83', 'crore', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2004017');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (316, 30, '2024-07-22', 'Promoting sports talent in small towns through various government schemes', 'The Ministry reported that the Khelo India Scheme was supporting 32 State Centres of Excellence and 1059 Khelo India Centres, with 302 accredited academies. It also stated that 2737 athletes had been identified and that each identified sportsperson could receive financial assistance of Rs. 6.28 lakh per year.', 'update', '2737', 'athletes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2035316');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (317, 30, '2024-07-25', 'Khelo India''s role in boosting India''s Olympic and Asian Games performance', 'The Ministry said 124 Khelo India Athletes were part of India’s 2022 Asian Games contingent and contributed 42 of the country’s 106 medals. It also reported that 28 Khelo India Athletes were included in India’s 117-member Paris 2024 Olympic contingent.', 'achievement', '42', 'medals', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2036939');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (318, 30, '2024-08-01', 'Promotion of sports through Khelo India Scheme', 'The Ministry stated that the Khelo India Scheme had been extended for five years from 2021-22 to 2025-26 and described its five components covering infrastructure, competitions and talent development, centres and academies, the Fit India Movement, and inclusiveness through sports. It reported that Khelo India Athletes had set 5939 national and 1424 international records in the past two years and the current year.', 'achievement', '5939', 'national records', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2040298');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (319, 30, '2024-11-28', 'Implementation of Khelo India Scheme', 'The Ministry reported approval of 323 new sports infrastructure projects with a sanctioned cost of Rs. 3073.97 crore. It also reported 1041 Khelo India Centres, 32 State Centres of Excellence, 301 accredited academies and 2781 Khelo India Athletes receiving programme support.', 'achievement', '323', 'sports infrastructure projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2078544');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (320, 30, '2024-12-02', 'Impact of Khelo India Scheme', 'The Ministry stated that the Khelo India Scheme supported athletes across 21 sports, including para-athletics, through coaching, equipment, medical care and monthly allowances. It reported that 2781 Khelo India Athletes had been identified, including 124 who contributed 42 medals at the 2022 Asian Games and 28 who were part of India’s Paris 2024 Olympic contingent.', 'achievement', '21', 'sports', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2079836');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (321, 31, '2022-12-08', 'Under UDAN, 453 routes have commenced, operationalizing 70 airports including 2 water aerodromes and 9 heliports', 'The Ministry of Civil Aviation reported that 453 UDAN routes had commenced, connecting 70 airports, water aerodromes and heliports as of November 29, 2022. More than 2.15 lakh UDAN flights had operated and over 1.1 crore passengers had benefited from the scheme.', 'achievement', '453', 'routes', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1881867');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (322, 31, '2023-02-13', '73 airports have been operationalized under the UDAN scheme till January 2023', 'The Ministry of Civil Aviation stated that 73 unserved or underserved airports, including heliports and water aerodromes, had been operationalized under UDAN as of January 31, 2023. Approximately Rs. 2,355 crore in Viability Gap Funding had been released to selected airline operators.', 'achievement', '73', 'airports, heliports and water aerodromes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1898741');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (323, 31, '2023-03-16', '469 routes connecting 74 airports operationalised under UDAN Scheme', 'As of February 28, 2023, 469 UDAN routes connecting 74 unserved and underserved airports had been operationalized. The release also reported that around Rs. 2,433 crore in Viability Gap Funding had been released to selected airline operators.', 'achievement', '469', 'routes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1907608');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (324, 31, '2023-07-27', '479 RCS-UDAN routes operational connecting 74 airports, including 2 water aerodromes and 9 heliports', 'The Ministry of Civil Aviation reported that 479 UDAN routes were operational as of June 30, 2023, connecting 74 airports, water aerodromes and heliports. More than 123 lakh passengers had benefited, while Rs. 2,729.11 crore in Viability Gap Funding had been released.', 'achievement', '479', 'routes', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1943198');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (325, 31, '2023-10-26', 'UDAN Version 5: 5.0, 5.1 and 5.2', 'The Ministry of Civil Aviation highlighted six years of UDAN and reported that more than 130 lakh passengers had benefited from the scheme. It also described successive versions of UDAN, including changes expanding helicopter connectivity, tourism routes and operational flexibility.', 'update', '130', 'lakh passengers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1971506');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (326, 31, '2024-02-08', '519 routes operationalised under RCS-UDAN Scheme, including 53 tourism and 48 helicopter routes', 'The Ministry of Civil Aviation reported that 519 UDAN routes had been operationalized, including tourism and helicopter routes. More than 133.86 lakh passengers had benefited, 2.56 lakh flights had operated, and 13 airlines had commenced UDAN operations.', 'achievement', '519', 'routes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2004057');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (327, 31, '2024-10-20', 'The Journey of UDAN: Soaring Towards Inclusivity in Indian Aviation', 'The release reviewed UDAN''s development since its launch in 2016 and its role in improving affordable regional air connectivity. It described the scheme''s market-driven model, Viability Gap Funding and concessions provided by airport operators and governments to support service to underserved regions.', 'update', '7', 'years', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2066445');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (328, 31, '2025-01-03', 'Year End Review 2024: UDAN turns 8, connecting India with 619 routes and 88 operational airports', 'The Ministry of Civil Aviation''s year-end review reported that UDAN had connected 88 operational airports through 619 routes by the end of 2024. The review presented this expansion as part of broader improvements in India''s regional air connectivity and aviation infrastructure.', 'achievement', '619', 'routes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2089984');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (329, 31, '2025-04-26', 'UDAN Scheme: Connecting India, One Flight at a Time', 'The Ministry of Civil Aviation reported that 625 UDAN routes had been operationalized, connecting 90 airports, including water aerodromes and heliports. More than 1.49 crore passengers had benefited, and Rs. 4,023.37 crore had been disbursed as Viability Gap Funding.', 'achievement', '625', 'routes', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2124459');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (330, 31, '2026-03-25', 'Cabinet approves Modified UDAN to deepen regional connectivity and expand inclusive air access across India', 'The Union Cabinet approved the launch and implementation of Modified UDAN for a ten-year period from FY 2026-27 to FY 2035-36. The scheme has a total outlay of Rs. 28,840 crore and proposes development of 100 airports, support for approximately 441 aerodromes and 200 modern helipads.', 'launch', '28840', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2245471');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (331, 32, '2024-02-08', 'Bharatmala Pariyojana', 'Under Phase-I of Bharatmala Pariyojana, 34,800 km of National Highway length was planned for development. By December 2023, 26,418 km had been awarded and about 15,549 km had been completed; projects in Andhra Pradesh and Telangana were also reported at bidding or awarded stages.', 'update', '26,418 awarded; 15,549 completed', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2004013');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (332, 32, '2024-07-31', 'BHARATMALA PARIYOJANA', 'The release states that Bharatmala Pariyojana projects cover economic corridors, inter-corridors, feeder routes, national corridor efficiency improvements, border and international connectivity, coastal and port connectivity, and expressways. It also says the programme is intended to improve connectivity and reduce logistics costs, with progress monitored through regular reviews.', 'update', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2039507');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (333, 32, '2024-12-05', 'IMPACT OF BHARATMALA PARIYOJANA', 'Bharatmala Pariyojana was approved to develop 34,800 km of roads at an estimated cost of Rs. 5.35 lakh crore to improve connectivity and reduce logistics costs. As of October 31, 2024, projects covering 26,425 km had been awarded and 18,714 km had been constructed; an IIM Bangalore study on the programme''s socioeconomic impact was under way.', 'achievement', '26,425 awarded; 18,714 constructed', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2081189');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (334, 32, '2024-12-18', 'Parliament Question: - Status of Ambitious Bharatmala Pariyojana', 'The release reports progress under Phase-I of Bharatmala Pariyojana, which covers 34,800 km. As of October 31, 2024, projects covering 26,425 km had been awarded and 18,714 km had been constructed; expenditure by NHAI under the programme reached Rs. 4.72 lakh crore up to November 30, 2024.', 'achievement', '26,425 awarded; 18,714 constructed', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085551');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (335, 32, '2025-03-13', 'IMPLEMENTATION OF BHARATMALA PARIYOJAN', 'The release states that 26,425 km of Bharatmala Pariyojana projects had been awarded as of February 28, 2025, of which 19,826 km had been constructed. It also reports that 6,669 km of high-speed greenfield corridors had been awarded and 4,610 km completed, alongside the adoption of technologies such as LIDAR, drones, and automated machine-aided construction.', 'achievement', '26,425 awarded; 19,826 constructed', 'km', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2111286');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (336, 34, '2023-08-02', 'Production Linked Incentive Schemes for 14 key sectors aim to enhance India’s manufacturing capabilities and exports', 'The press release states that PLI schemes covering 14 key sectors were announced with an outlay of Rs. 1.97 lakh crore to strengthen manufacturing capabilities and exports. It notes that 733 applications had been selected, including 176 MSMEs, and that the schemes were expected to attract investment, improve efficiency and create employment.', 'target', '1.97 lakh crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1945155');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (337, 34, '2024-12-21', 'Scaling New Heights: How the PLI Scheme is Reshaping Industries', 'The release reports that, as of August 2024, PLI schemes across 14 sectors had attracted Rs. 1.46 lakh crore in investment, generating incremental production or sales of more than Rs. 12.50 lakh crore. It also reports employment of over 9.5 lakh people, exports exceeding Rs. 4 lakh crore and 764 approved applications.', 'achievement', '1.46 lakh crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2086811');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (338, 34, '2025-03-22', 'PLI scheme incentivizes domestic manufacturing, increases production, creates new jobs and boosts exports', 'The release reports that PLI schemes across 14 sectors had generated Rs. 1.61 lakh crore in investment, Rs. 14 lakh crore in production and Rs. 5.31 lakh crore in exports. It also states that the schemes had generated 11.5 lakh jobs, with 764 applications approved and 176 MSME beneficiaries.', 'achievement', '1.61 lakh crore', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2114011');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (339, 35, '2023-10-24', 'PM acknowledges transformative impact of PM SVANidhi', 'The Prime Minister highlighted State Bank of India research describing PM SVANidhi as financially empowering and inclusive. The research noted the scheme’s role in supporting women and marginalized street vendors through formal credit.', 'achievement', '43%', 'women beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1970506');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (340, 35, '2023-10-26', 'PM-SVANidhi promoting inclusive entrepreneurship', 'The release reported that PM-SVANidhi had disbursed ₹9,152 crore in loans and promoted inclusive entrepreneurship among street vendors. It also described repayment and progression patterns across the scheme’s three loan tranches.', 'achievement', '₹9,152 crore', 'loans disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1971579');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (341, 35, '2025-02-01', 'PM SVANIDHI with enhanced loans from banks, and UPI linked credit cards with ₹30,000 limit', 'The Union Budget 2025-26 proposed enhanced bank loans under PM SVANidhi and UPI-linked credit cards for street vendors. The credit cards were announced with a limit of up to ₹30,000.', 'update', '₹30,000', 'UPI-linked credit-card limit', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098352');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (342, 35, '2025-08-27', 'Cabinet approves restructuring and extension of lending period beyond 31.12.2024 of PM Street Vendors AtmaNirbhar Nidhi (PM SVANidhi) Scheme', 'The Union Cabinet approved restructuring PM SVANidhi and extending its lending period until March 31, 2030. The restructured scheme includes higher loan amounts, UPI-linked RuPay credit cards, digital cashback incentives, and broader socio-economic support for vendors and their families.', 'update', '1.15 crore', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2161157');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (343, 35, '2025-10-24', 'Union Minister reviews progress of PM SVANidhi Scheme with States, UTs and Banks', 'The Union Minister for Housing and Urban Affairs reviewed implementation of PM SVANidhi with representatives of States, Union Territories, banks, and related departments. The review reaffirmed the government’s focus on timely credit delivery and effective implementation through the banking and local-government systems.', 'update', '33', 'States and Union Territories', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2182258');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (344, 35, '2025-12-20', 'SVANidhi: Empowering Street Vendors', 'The backgrounder described the restructured PM SVANidhi scheme, including its extended lending period through March 2030 and enhanced credit facilities. It stated that the scheme aims to benefit 1.15 crore street vendors, including 50 lakh new beneficiaries.', 'target', '50 lakh', 'new beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2206995');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (345, 37, '2022-03-10', 'Rural development Secretary chairs a webinar on Captive Employment Policy under Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY)', 'The Ministry of Rural Development held a webinar to promote the DDU-GKY Captive Employer initiative, which links industry demand with training and assured placement for rural poor youth. More than 16 Sector Skill Councils and over 180 stakeholders participated.', 'update', '16 Sector Skill Councils and 180+ stakeholders', 'participants', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1804850');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (346, 37, '2022-03-15', 'Deen Dayal Upadhyay-Grameen Kaushal Yojana in North Eastern Region', 'The release describes DDU-GKY as a placement-linked skilling programme for rural poor youth aged 15–35 in the North Eastern Region. It notes the scheme’s inclusion provisions, including earmarking 50% of funds for SCs and STs and 15% for minorities.', 'update', '50%', 'funds earmarked for SCs and STs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1806265');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (347, 37, '2022-03-29', 'Review of Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY): More than 7 lakh candidates placed from 2014-15', 'The Ministry reported that more than 7 lakh candidates had been placed under DDU-GKY since 2014-15, with 1.28 lakh candidates undergoing training at the time of the release. For 2021-22, the programme targeted training 2.80 lakh candidates and placing 1.96 lakh.', 'target', '2.80 lakh trained; 1.96 lakh placed', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1810966');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (348, 37, '2023-03-27', 'Big boost to rural employment as more than 31,000 jobs on the way under DDU-GKY', 'The Ministry of Rural Development announced MoUs with 19 captive employers under the Recruit, Train and Deploy model. The employers were given a target to train and provide gainful employment to 31,067 rural poor youths, with a minimum salary of ₹10,000 per month for at least six months.', 'target', '31,067', 'rural youth', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1911122');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (349, 37, '2023-03-28', 'Union Minister Shri Giriraj Singh initiates ‘Captive Employment’ initiative under Deen Dayal Upadhyaya Kaushalya Yojana (DDU-GKY), paving the way for greater industry participation in skilling rural poor youth', 'The Minister onboarded 19 captive employers under DDU-GKY to train rural poor youth and provide employment in their own establishments or subsidiaries. The first phase was intended to train and place more than 31,000 rural youth.', 'launch', '19', 'captive employers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1911639');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (350, 37, '2023-06-27', 'Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY): Empowering Rural Youth and Fostering Inclusive Development', 'The release states that DDU-GKY had trained 14.51 lakh candidates and placed 8.70 lakh candidates since inception, based on data through May 31, 2023. It also reports that ₹7,015.61 crore had been released under the programme through April 30, 2023.', 'achievement', '14.51 lakh trained; 8.70 lakh placed', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1935711');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (351, 37, '2024-12-17', 'Beneficiaries under Deen Dayal Upadhyaya Grameen Kaushalya Yojana - DDU-GKY', 'The Ministry reported that 16,90,046 candidates had been trained and 10,97,265 placed under DDU-GKY from FY 2014-15 through November 2024. It stated that 65% of candidates had secured gainful employment after completing training and outlined enhanced provisions under DDU-GKY 2.0.', 'achievement', '10,97,265', 'candidates placed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085248');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (352, 37, '2025-07-25', 'Role of NRLM in Enhancing Skill Development and Employment Opportunities', 'The Ministry reported that DDU-GKY had trained 17,50,784 candidates and placed 11,48,247 candidates since inception through June 2025. The release also describes DDU-GKY as a placement-linked programme for rural poor youth aged 15–35, with jobs intended to provide regular wages at or above minimum wages.', 'achievement', '17,50,784 trained; 11,48,247 placed', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148466');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (353, 38, '2023-07-27', 'Atal Bhujal Yojana and Jal Jeevan Mission', 'Atal Bhujal Yojana is being implemented in water-stressed Gram Panchayats across 229 administrative blocks or talukas in 80 districts of seven states. The release states that Rs. 1,688.90 crore had been released to the participating states as of July 12, 2023, with implementation based on community participation and performance indicators.', 'update', '1688.90', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1943352');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (354, 38, '2025-07-24', 'Implementation of Atal Bhujal Yojana', 'The scheme is being implemented in 8,203 water-stressed Gram Panchayats across 80 districts in seven states through a community-led approach to sustainable groundwater management. The release reports that around 81,000 supply-side structures were constructed or renovated and approximately 9 lakh hectares were brought under efficient water-use practices.', 'achievement', '9', 'lakh hectares', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2147817');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (355, 38, '2025-08-07', 'Implementation and Expansion of Atal Bhujal Yojana', 'The release reports progress under the community-led groundwater management scheme, including public disclosure of groundwater data and preparation of Water Budgets and Water Security Plans across all 8,203 participating Gram Panchayats. Around 81,700 supply-side structures were constructed or renovated, and about 9 lakh hectares were brought under efficient water-use practices.', 'achievement', '81700', 'structures', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2153573');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (356, 38, '2025-08-21', 'Expansion of Atal Bhujal Yojana', 'Atal Bhujal Yojana is being implemented in seven states and benefits 8,203 water-stressed Gram Panchayats through demand- and supply-side groundwater interventions. From October 2021 to December 2024, around 9.78 lakh beneficiaries received assistance or subsidies for efficient water-use practices, while approximately 81,700 water-conservation and groundwater-recharge structures were constructed or renovated.', 'achievement', '9.78', 'lakh beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2159049');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (357, 38, '2025-12-11', 'Coverage under Atal Bhujal Yojana', 'Atal Bhujal Yojana was implemented as a pilot scheme across 8,203 priority water-stressed Gram Panchayats in seven states. Its stated objective was to improve groundwater management through community participation, demand-side interventions, stronger local institutions, and incentives for groundwater conservation.', 'update', '8203', 'Gram Panchayats', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2202306');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (358, 40, '2022-07-25', 'National Apprenticeship Promotion Scheme', 'The release describes NAPS objectives, including promoting on-the-job training, encouraging establishments to enroll apprentices, and expanding opportunities for MSMEs and underserved regions. It reports around 13.38 lakh apprentices engaged since the scheme began and says the government planned to transfer its stipend contribution directly to apprentices’ bank accounts through DBT.', 'update', '13.38', 'lakh apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1844727');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (359, 40, '2022-07-02', 'MSDE launches DBT scheme to extend direct monetary support to apprentices', 'The Ministry announced that NAPS would use Direct Benefit Transfer to send the government’s stipend contribution directly to apprentices’ bank accounts through NSDC. The government contribution was set at 25% of the stipend, subject to a maximum of Rs. 1,500 per month, and more than 12 lakh apprentices had been engaged at the time.', 'launch', '12', 'lakh apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1838842');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (360, 40, '2023-08-12', 'Shri Dharmendra Pradhan launches DBT in NAPS to strengthen apprenticeship ecosystem in India', 'The Union Minister launched Direct Benefit Transfer under NAPS and disbursed approximately Rs. 15 crore to one lakh apprentices. The release also states that 25 lakh youth had been engaged as apprentices since NAPS began in 2016, as of 31 July 2023.', 'launch', '15', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1948017');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (361, 40, '2025-05-26', 'Central Apprenticeship Council recommends 36% Increase in Stipend for Youth under National Apprenticeship Promotion Scheme and National Apprenticeship Training Scheme', 'The Central Apprenticeship Council recommended a 36% increase in the stipend range for NAPS and NATS apprentices, from ₹5,000–₹9,000 to ₹6,800–₹12,300. The recommendation also proposed biennial adjustment of stipends based on changes in the Consumer Price Index.', 'update', '36', 'percent increase', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2131391');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (362, 40, '2025-07-28', 'Apprenticeship Reforms and the Central Apprenticeship Council’s Recommendations', 'The release reports that 8,52,376 apprentices were undergoing training under NAPS-2 as of 30 June 2025, including 1,95,680 women. It also outlines portal upgrades, revised guidelines, strengthened monitoring, financial support for apprenticeship melas, and efforts to expand establishment participation.', 'update', '8,52,376', 'apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149336');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (363, 40, '2025-08-18', 'Status of Apprentice Scheme', 'The release states that NAPS-2 had a physical target of 13 lakh apprentices for financial year 2025–26, with 3.99 lakh engaged through July 2025. It also reports 41,95,703 apprentices engaged nationwide from FY 2018–19 through July 2025, of whom 21,47,122 had completed training.', 'target', '13', 'lakh apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157511');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (364, 40, '2026-03-23', 'NATIONAL APPRENTICESHIP AND TRAINING SCHEMES', 'The release explains that NAPS, launched in 2016 and continued as NAPS-2 from 2022–23, is one of the government’s two flagship apprenticeship schemes. It reports that 11.84 lakh apprentices were engaged under NAPS in 2025, alongside 5.23 lakh under NATS.', 'achievement', '11.84', 'lakh apprentices', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2243987');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (365, 41, '2023-03-16', 'PM-KUSUM - Grid-connected solar power plants of 89.45 MW capacity installed; 2.09 lakh agriculture pumps have been solarized', 'As of 28 February 2023, 89.45 MW of grid-connected solar power plants had been installed and 2.09 lakh agriculture pumps had been solarized under PM-KUSUM. The reported installations were estimated to reduce carbon dioxide emissions by 0.67 million tonnes and diesel consumption by 143 million litres annually.', 'achievement', '89.45', 'MW', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1907703');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (366, 41, '2023-03-21', '2,08,648 farmers have benefitted from PM-KUSUM scheme', 'The Ministry of New and Renewable Energy reported that 2,08,648 farmers had benefited from the PM-KUSUM scheme. The release described the scheme''s implementation and support for solar pumps and solarization of agricultural pumps.', 'achievement', '2,08,648', 'farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1909267');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (367, 41, '2023-07-20', 'Availability of low-cost financing for farmers and state share of funds is a major challenge in implementation of the PM-KUSUM Scheme', 'The release outlined PM-KUSUM targets of 10 GW under Component A, 20 lakh standalone solar water pumps under Component B, and solarization of 15 lakh existing grid-connected agricultural pumps under Component C. As of 30 June 2023, 113.08 MW had been installed under Component A and about 2.45 lakh pumps had been installed or solarized under Components B and C combined.', 'update', '2.45 lakh', 'pumps', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1941150');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (368, 41, '2023-08-09', 'Progress of Implementation of PM-KUSUM Yojana', 'The release stated that PM-KUSUM targets 30.8 GW of solar capacity addition by 31 March 2026, supported by ₹34,422 crore in central financial assistance. Its components include 10,000 MW of decentralized solar plants, 20 lakh standalone solar pumps, and solarization of 15 lakh grid-connected agricultural pumps.', 'target', '30.8', 'GW', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1947138');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (369, 41, '2022-12-15', 'Steps by MNRE to implement PM-KUSUM scheme', 'The Ministry described implementation measures for PM-KUSUM, including extending the scheme through 31 March 2026 and increasing eligible pump capacity for certain farmers from 7.5 HP to 15 HP. The scheme targets 30.8 GW of solar capacity addition with total central financial support of ₹34,422 crore.', 'update', '30.8', 'GW', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1883920');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (370, 41, '2023-12-07', 'Major ongoing Renewable Energy Schemes and Programmes', 'The Ministry listed PM-KUSUM among its major ongoing renewable energy programmes. The scheme promotes small grid-connected solar power plants, standalone solar agricultural pumps, and solarization of existing grid-connected agricultural pumps, benefiting farmers, states, and distribution companies.', 'update', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1983766');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (371, 41, '2024-08-06', 'PM-KUSUM SCHEME', 'The release described the three PM-KUSUM components: decentralized solar power plants, standalone solar agricultural pumps, and solarization of grid-connected agricultural pumps. As of 30 June 2024, 4,11,222 farmers had benefited from the scheme nationwide, including 51,097 farmers in Uttar Pradesh according to state-provided information.', 'achievement', '4,11,222', 'farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2042069');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (372, 41, '2025-09-17', 'GST on Renewable Energy Devices Rationalised to 5% to Accelerate India’s Clean Energy Transition; Farmers under PM-KUSUM to Save ₹1,750 Crore on 10 Lakh Solar Pumps with GST Cut', 'The release said the GST reduction on renewable-energy devices would lower the cost of PM-KUSUM solar pumps. It estimated that a 5 HP solar pump would become cheaper by nearly ₹17,500 and that farmers could collectively save ₹1,750 crore across 10 lakh pumps.', 'update', '1,750', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2167486');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (373, 41, '2025-12-16', 'PM-KUSUM Empowers Farmers as ‘Urjadata’, Reaching Over 20 Lakh Beneficiaries', 'The release reported that PM-KUSUM had reached more than 20 lakh beneficiaries and highlighted income opportunities from leasing land for solar plants. It stated that farmers could earn up to ₹80,000 per hectare per year from land leasing and save about ₹60,000 annually on diesel through solar pumps.', 'achievement', '20 lakh', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2204463');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (374, 41, '2025-12-10', 'PM-KUSUM Registers Significant Progress: 10,203 MW Installed and ₹7,106 Crore Released Till November 2025', 'As of 30 November 2025, 10,203 MW had been installed under all components of PM-KUSUM and ₹7,106 crore had been released. The Ministry also reported revised implementation guidelines, priority for small and marginal farmers and micro-irrigation users, and outreach activities to expand the scheme.', 'achievement', '10,203', 'MW', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2201309');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (376, 42, '2024-07-31', 'Survey and Mapping with improvised Technology', 'The Ministry of Panchayati Raj stated that SVAMITVA uses drone technology to survey inhabited rural areas and provide household owners with legal property records. As of 19 July 2024, drone surveys had been completed in 3.12 lakh villages and 2.03 crore property cards had been prepared in 1.30 lakh villages.', 'update', '2.03', 'crore property cards', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2039633');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (377, 42, '2024-12-26', 'Empowering Rural India', 'The Ministry of Panchayati Raj announced that 57 lakh SVAMITVA property cards would be distributed on 27 December 2024 across 46,351 villages in 10 states and two Union Territories. The release also reported that drone surveys had been completed in 3.17 lakh villages and 2.19 crore property cards had been prepared for nearly 1.49 lakh villages.', 'target', '57', 'lakh property cards', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2088066');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (378, 42, '2025-01-18', 'Empowering Rural India with Legal Land Ownership 65 Lakh SVAMITVA Property Cards Distributed', 'The Ministry of Panchayati Raj reported that 65 lakh SVAMITVA property cards were distributed across more than 50,000 villages in 10 states and two Union Territories on 18 January 2025. The cards provide rural property owners with records of rights intended to support access to credit, reduce disputes, and improve village planning.', 'achievement', '65', 'lakh property cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2094019');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (379, 42, '2025-01-18', 'Prime Minister Shri Narendra Modi Distributes 65 lakh Property Cards under SVAMITVA Scheme; Total Property Cards Distributed Reach 2.25 Crore Milestone', 'Prime Minister Narendra Modi presided over the distribution of 65 lakh property cards under the Ministry of Panchayati Raj’s SVAMITVA Scheme. The distribution covered more than 50,000 villages across 10 states and two Union Territories, bringing the total number of distributed property cards to 2.25 crore.', 'achievement', '2.25', 'crore property cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2094040');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (380, 42, '2025-04-23', 'Building a Self-Reliant India 5 Years of SVAMITVA Scheme', 'On the scheme’s fifth anniversary, the Ministry of Panchayati Raj reported that more than 2.42 crore property cards had been created for 1.61 lakh villages. Drone surveys had been completed in 3.20 lakh villages, covering an estimated 68,122 square kilometres.', 'achievement', '2.42', 'crore property cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2123886');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (381, 46, '2024-08-09', 'Cabinet approves implementation of the Pradhan Mantri Awaas Yojana–Gramin (PMAY-G) during FY 2024-25 to 2028-29', 'The Union Cabinet approved continuation of PMAY-G through FY 2028-29, including assistance for constructing two crore additional pucca houses with basic amenities. The approval carries a total outlay of ₹3,06,137 crore and is expected to benefit nearly 10 crore people.', 'target', '2 crore', 'additional houses', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2043921');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (382, 46, '2024-11-20', 'Celebrating Awaas Diwas 2024: Empowering Rural India through Pradhan Mantri Awaas Yojana-Gramin', 'The Ministry of Rural Development highlighted PMAY-G’s expansion by two crore additional houses for FY 2024-29, supported by a total outlay of ₹3,06,137 crore. The release also reported that 74% of sanctioned houses were owned solely or jointly by women and that nearly three lakh rural masons had been trained.', 'update', '2 crore', 'additional houses', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2075171');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (383, 46, '2024-12-03', 'Automatic exclusion criteria for Pradhan Mantri Awas Yojana-Gramin scheme beneficiaries', 'The Ministry of Rural Development described revised automatic-exclusion criteria for identifying beneficiaries in the new PMAY-G phase, including removal of exclusions related to motorized two-wheelers, fishing boats, landline phones and refrigerators. The monthly household-income exclusion threshold was increased from ₹10,000 to ₹15,000, while 3.21 crore houses had been sanctioned and more than 2.67 crore completed at the time of the release.', 'update', '10', 'automatic-exclusion criteria', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2080091');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (384, 46, '2025-02-07', 'Achievement of targets under PMAY-G', 'The Ministry reported that all houses under the original 2.95-crore PMAY-G target had been sanctioned by March 31, 2024. As of February 2, 2025, States and Union Territories had received a cumulative target of 3.79 crore houses, with 3.34 crore sanctioned and 2.69 crore completed.', 'achievement', '2.69 crore', 'houses completed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100662');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (385, 46, '2025-03-18', 'Transparency and Accountability under PMAY-G', 'The release explained that PMAY-G beneficiaries are identified using housing-deprivation parameters, exclusion criteria, Gram Sabha verification and an appellate process. It also described the Awaas+ 2024 app, which supports assisted and self-surveys, Aadhaar-based e-KYC, face authentication, geotagged photos and AI/ML-based monitoring.', 'update', '2 crore', 'additional rural houses', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112200');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (386, 46, '2025-03-21', 'Beneficiaries of Pradhan Mantri Awas Yojana (Rural)', 'The Ministry reported that PMAY-G had a cumulative target of 3.79 crore houses as of March 17, 2025, of which 3.56 crore had been sanctioned and 2.72 crore completed. The release also noted that at least 60% of targets are earmarked for Scheduled Caste and Scheduled Tribe households, subject to beneficiary availability and verification.', 'achievement', '2.72 crore', 'houses completed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113753');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (387, 47, '2023-05-10', 'India Achieves Another Major Sanitation Milestone - 50% Villages Are Now ODF Plus Under Swachh Bharat Mission Grameen Phase II', 'The press release states that 50% of India’s villages had achieved ODF Plus status under Phase II of the Swachh Bharat Mission Grameen. Nearly 3 lakh villages had declared themselves ODF Plus, supporting the mission’s 2024-25 goals.', 'achievement', '50%', 'villages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1923036');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (388, 47, '2023-09-28', 'Uttar Pradesh Achieves 100% ODF Plus Coverage under Swachh Bharat Mission Grameen', 'Uttar Pradesh achieved ODF Plus status in all 95,767 villages under Phase II of the Swachh Bharat Mission Grameen. Of these, 81,744 were ODF Plus Aspiring, 10,217 were ODF Plus Rising and 3,806 were ODF Plus Model villages.', 'achievement', '95,767', 'villages', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1961678');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (389, 47, '2024-02-17', 'Vini Mahajan Inaugurates National Conference on JJM & SBM-G at Lucknow, Uttar Pradesh', 'The Department of Drinking Water and Sanitation inaugurated a national conference on Jal Jeevan Mission and Swachh Bharat Mission-Grameen in Lucknow. The conference focused on the missions’ progress, sustainability, convergence and achieving Sampoorna Swachhta.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2006765');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (390, 47, '2024-11-12', 'C.R. Patil Holds Review Meeting of North-Eastern States at Guwahati, Assam', 'A review meeting assessed progress under the Swachh Bharat Mission-Grameen in the North-Eastern states. The release reported that 51% of villages in the region had achieved ODF Plus Model status, with Sikkim reaching 100% coverage.', 'update', '51%', 'villages in the North-East', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2072869');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (406, 49, '2020-02-05', 'Soil Health Card scheme of Central Govt: A success story', 'The release says 11.69 crore Soil Health Cards were distributed to farmers during the scheme’s second phase over two years. It also reports that the use of chemical fertilizers declined by 10 percent.', 'achievement', '11.69', 'crore Soil Health Cards', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1601990');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (391, 47, '2025-03-24', 'Parliament Question: Objectives Achieved under Swachh Bharat Mission', 'The release reported that 5,64,096 of India’s 5,86,788 villages had declared themselves ODF Plus as of 17 March 2025. It also stated that 5,03,585 villages had solid waste management coverage and 5,22,462 had liquid waste management coverage.', 'achievement', '5,64,096', 'ODF Plus villages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2114291');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (392, 47, '2025-08-18', 'ODF Plus Village under Swachh Bharat Mission', 'The release explained the criteria and verification process for declaring villages ODF Plus under SBM (Gramin). It described the Aspiring, Rising and Model stages, including requirements for solid and liquid waste management, visual cleanliness and third-party verification for Model villages.', 'update', '3', 'ODF Plus stages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157441');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (393, 47, '2025-08-29', 'Conference on Swachh Bharat Mission-Grameen (SBM-G) Progress & Brainstorming on SBM-G Next Phase', 'The Department of Drinking Water and Sanitation announced a roundtable conference to review SBM-G progress and develop priorities for its next phase. The release reported over 11.93 crore individual household latrines, 2.62 lakh community sanitary complexes, 4.76 lakh ODF Plus Model villages, more than 950 functional GOBARdhan projects and 124 faecal sludge treatment plants.', 'target', '4.76 lakh', 'ODF Plus Model villages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2161880');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (394, 36, '2023-03-28', 'Update on Aspirational District Program in targeted districts: Aspirational Districts have shown improvement with respect to the Health and Nutrition indicators', 'NITI Aayog reported that Aspirational Districts had generally improved on Health and Nutrition indicators. The programme uses convergence of existing schemes, monthly performance assessments, and challenge-based funding to address critical gaps.', 'update', '30%', 'weightage assigned to Health and Nutrition', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1911472');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (395, 36, '2024-11-18', 'Namsai Climbs from 97th to 12th: A Success Story of Aspirational Districts Programme', 'The release highlighted Namsai district’s progress under the Aspirational Districts Programme, including its improvement from 97th to 12th place in rankings. It also cited 100% conversion of health centres and initiatives to improve maternal care, early childhood education, and school infrastructure.', 'achievement', '97th to 12th', 'ranking positions', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2074266');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (396, 36, '2024-09-18', 'Cabinet approves Pradhan Mantri Janjatiya Unnat Gram Abhiyan', 'The Cabinet approved a mission aimed at saturation coverage of tribal-majority villages and tribal families, including villages in Aspirational Districts. The mission has a total outlay of ₹79,156 crore and is expected to cover around 63,000 villages benefiting more than 5 crore tribal people.', 'target', '63,000', 'villages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2055996');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (397, 36, '2024-07-04', '‘Sampoornata Abhiyan’ launched by NITI Aayog to attain saturation in key social-sector indicators', 'NITI Aayog launched a three-month nationwide campaign to achieve 100% saturation of 12 key social-sector indicators in Aspirational Districts and Blocks. Launch events were organised across all 112 Aspirational Districts and 500 Aspirational Blocks, covering health, nutrition, agriculture, social development, and education.', 'launch', '112 districts and 500 blocks', 'Aspirational Districts and Aspirational Blocks', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2024/jul/doc202471346701.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (398, 48, '2023-02-09', 'Pradhan Mantri Krishi Sinchayee Yojana', 'The release describes PMKSY''s components and reports that continuation of the HKKP component for 2021–26 was approved. It sets targets of creating 4.5 lakh hectares of irrigation potential through surface minor irrigation and repair, renovation and restoration of water bodies, alongside coverage of 30.23 lakh hectares under CAD&WM.', 'target', '4.5 lakh', 'hectares of irrigation potential', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1897710');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (399, 48, '2023-08-07', 'Pradhan Mantri Krishi Sinchayee Yojana', 'The release reports that PMKSY implementation for 2021–22 to 2025–26 was approved with an overall outlay of ₹93,068.56 crore, including ₹37,454 crore in central assistance. It also states that 14,966 water-harvesting structures were created or rejuvenated and about 18,033 hectares were brought under irrigation in West Bengal under the Watershed Development component during 2015–2023.', 'update', '93,068.56', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1946492');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (400, 48, '2024-01-04', 'Year End Review – Department of Water Resources, River Development and Ganga Rejuvenation, Ministry of Jal Shakti', 'The year-end review reports progress under the PMKSY-Har Khet Ko Pani component in 2023. It states that 29,777 wells were constructed, 87,243 hectares of command area were created, and 67,902 small and marginal farmers benefited.', 'achievement', '29,777; 87,243; 67,902', 'wells; hectares; farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1993077');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (401, 48, '2025-03-28', 'Cabinet approves inclusion of Kosi Mechi Intra-State Link Project of Bihar under Pradhan Mantri Krishi Sinchai Yojana-Accelerated Irrigation Benefits Programme (PMKSY-AIBP)', 'The Cabinet approved inclusion of Bihar''s Kosi Mechi Intra-State Link Project under PMKSY-AIBP, with an estimated project cost of ₹6,282.32 crore and central support of ₹3,652.56 crore. The project is expected to provide 2,10,516 hectares of additional annual Kharif-season irrigation in four Bihar districts.', 'launch', '2,10,516', 'hectares of additional annual irrigation', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2116180');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (402, 48, '2025-04-09', 'Cabinet approves Modernization of Command Area Development and Water Management as a sub-scheme of Pradhan Mantri Krishi Sinchayee Yojana for the period 2025-2026', 'The Union Cabinet approved the Modernization of Command Area Development and Water Management (M-CADWM) as a PMKSY sub-scheme for 2025–2026. The initiative received an initial total outlay of ₹1,600 crore to modernize irrigation-water supply networks and support efficient farm-level water delivery.', 'launch', '1,600', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2120360');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (403, 48, '2025-07-24', 'Pradhan Mantri Krishi Sinchayee Yojana', 'The release provides an update on PMKSY implementation and notes that underground distribution pipelines totaling about 55,290 km helped avoid acquiring approximately 76,594 hectares of land. It also states that dashboard-based monitoring and SCADA-supported distribution have helped improve project oversight and water-use efficiency.', 'update', '55,290', 'km of underground pipelines', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2147696');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (404, 48, '2025-07-28', 'Projects Approved under (M-CADWM)', 'The Ministry reported that proposals were being processed for projects under the M-CADWM sub-scheme of PMKSY. Pilot projects were planned to cover approximately 75,000 hectares through underground piped irrigation, with a total scheme outlay of ₹1,600 crore, including ₹1,100 crore in central outlay.', 'target', '75,000', 'hectares of farmland', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149303');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (405, 48, '2025-12-01', 'Modernisation of Command Area Development and Water Management', 'The release states that M-CADWM was approved as a PMKSY sub-scheme for pilot projects across States and Union Territories. It reports approval of 34 clusters in 23 States and Union Territories for the pilot phase.', 'update', '34', 'clusters in 23 States/UTs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2197174');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (407, 49, '2020-02-07', 'Improving Soil Productivity and Fertility', 'The release describes the Soil Health Card Scheme’s objective of providing farmers with soil nutrient information and fertilizer recommendations every two years. It highlights the 2019–20 Model Villages pilot, which involved farm-level soil sampling with farmer participation, along with training, demonstrations and farmer campaigns.', 'update', '5.50', 'lakh demonstrations', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1602379');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (408, 49, '2020-02-17', 'Soil health card Scheme Completes 5 years on 19-2-2020; Soil health Cards issued every 2 years to Farmers; Soil health leads to Sustainable Farming', 'The release reviews the scheme’s five-year implementation and explains that Soil Health Cards provide nutrient-status information and recommendations for improving soil fertility. It reports that 10.74 crore cards were distributed during the first cycle and 11.69 crore during the second cycle.', 'achievement', '11.69', 'crore Soil Health Cards in Cycle II', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1603379');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (409, 49, '2020-02-18', 'Soil Health Card Day to be Observed Tomorrow; Deteriorating Soil Health Leads to Stagnation in Agricultural Productivity; Soil Health Leads to Sustainable Farming', 'The release announces Soil Health Card Day and explains that the scheme is intended to issue cards to farmers every two years to address nutrient deficiencies. It emphasizes soil testing as a means to reduce cultivation costs through appropriate fertilizer use and support sustainable farming.', 'launch', '2', 'years between Soil Health Card cycles', 'https://pib.gov.in/PressReleaseIframePage.aspx?PRID=1603569');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (410, 49, '2020-02-19', 'Soil Health Card Scheme helped India achieve surplus capacity in foodgrain production: Shri Narendra Singh Tomar', 'At a National Workshop on Soil Health Card Day, the Agriculture Minister said the scheme had contributed to India achieving surplus foodgrain production capacity. The release states that more than 11 crore Soil Health Cards had been issued in two phases and that cards provide soil-health status and crop-specific nutrient recommendations.', 'achievement', '11', 'crore-plus Soil Health Cards', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1603758');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (411, 49, '2022-03-22', 'SOIL HEALTH CARD SCHEME', 'The release explains that Soil Health Cards promote balanced fertilizer use and recommend biofertilizers, micronutrients and organic manures. It also reports the establishment of soil-testing laboratories and describes training and demonstrations intended to improve farmer awareness of soil health management.', 'update', '7,523', 'soil-testing laboratories', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1808329');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (412, 49, '2023-08-11', 'New Soil Health Card Scheme', 'The Government introduced technological improvements to the Soil Health Card Scheme, including a revamped portal integrated with geographic information systems so test results can be captured and viewed on maps. The mobile application was enhanced with geolocation, QR-code linking and direct transfer of test results from geo-mapped laboratories, with the new system rolled out from April 2023.', 'launch', '56', 'training sessions for States', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1947891');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (413, 49, '2023-12-19', 'Soil Health Management and Soil Health Card Schemes', 'The release reports that 23.58 crore Soil Health Cards had been distributed to farmers. It also states that the Soil Health Management and Soil Health Card schemes were merged into the Soil Health & Fertility component of the Rashtriya Krishi Vikas Yojana.', 'update', '23.58', 'crore Soil Health Cards', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1988294');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (414, 50, '2024-10-03', '13,822 Jan Aushadhi Kendras have been established across the country; medicines worth Rs. 6,100 crores sold through PMBJP, leading to estimated savings of Rs. 30,000 crores', 'As of September 30, 2024, a total of 13,822 Jan Aushadhi Kendras had been established nationwide. The release said medicines worth Rs. 6,100 crore had been sold through the scheme over the previous 10 years, generating estimated savings of Rs. 30,000 crore for citizens compared with branded medicines.', 'achievement', '13,822', 'Jan Aushadhi Kendras', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2061631');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (415, 50, '2025-03-01', 'Union Minister inaugurates week-long celebrations of Jan Aushadhi Diwas 2025 by flagging off vehicles carrying information about PMBJP', 'The Union Minister inaugurated the week-long Jan Aushadhi Diwas 2025 celebrations and flagged off a Rath and 10 vehicles to disseminate information about the scheme. The release stated that 15,000 Jan Aushadhi Kendras had been opened by February 28, 2025, and that the government had set a target of 25,000 Kendras by March 31, 2027.', 'achievement', '15,000', 'Jan Aushadhi Kendras', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2107206');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (416, 50, '2025-03-02', 'Jan Aushadhi - Virasat Ke Saath: Second day of celebrations for Jan Aushadhi Diwas 2025', 'The second day of Jan Aushadhi Diwas 2025 featured heritage walks at 25 monuments across the country to spread awareness about affordable generic medicines. More than 500 free health camps, or Jan Arogya Melas, were also organized, particularly for senior citizens.', 'achievement', '25', 'heritage sites', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2107569');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (417, 50, '2025-03-03', 'Jan Aushadhi-Bal Mitra Participation: Third day of celebrations for Jan Aushadhi Diwas 2025', 'The third day of the celebrations involved Bal Mitra activities in 30 major cities across 30 states to raise awareness among children about quality generic medicines available through Jan Aushadhi Kendras. Nutraceutical products such as Poshan were distributed to participating children.', 'update', '30', 'cities and states', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2107805');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (418, 50, '2025-03-07', 'Jan Aushadhi Diwas celebrated with week-long events; more than 200 new Jan Aushadhi Kendras opened, taking the total to 15,291', 'The seventh Jan Aushadhi Diwas was observed nationwide under the theme “Jan Aushadhi: Daam Kam, Dawai Uttam,” concluding week-long awareness activities held from March 1 to 7, 2025. The release reported that more than 200 new Kendras had opened during the period, taking the nationwide total to 15,291.', 'achievement', '15,291', 'Jan Aushadhi Kendras', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2109203');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (419, 52, '2023-10-27', 'National Event on Pradhan Mantri Matru Vandana Yojana (PMMVY) held in Mumbai; new PMMVY portal launched and direct benefit cash transfer released to 8,14,612 beneficiaries', 'A national PMMVY event was held in Mumbai, where a comprehensive user manual and the new PMMVYsoft MIS portal were launched. Direct benefit cash transfers totaling Rs 321.57 crore were released to 8,14,612 beneficiaries.', 'launch', '8,14,612', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1972286');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (420, 52, '2024-01-19', 'Year End Review-2023: Ministry of Women and Child Development', 'The Ministry reported that more than 64,000 POSHAN Abhiyaan and PMMVY beneficiaries shared their experiences during the Viksit Bharat Sankalp Yatra, with more than 92,000 on-the-spot registrations conducted under various Ministry schemes. The review also highlighted the additional Rs 6,000 benefit for a second girl child and the development of the PMMVY portal and mobile app.', 'update', '92,000', 'on-the-spot registrations', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1998748');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (421, 52, '2024-12-13', 'Under PMMVY, maternity benefits are provided to eligible women; husband’s Aadhaar is not mandatory', 'The Ministry stated that PMMVY maternity benefits are available to eligible women aged 18 years and 7 months to 55 years. It also clarified that a husband’s Aadhaar is not mandatory for receiving benefits under the Mission Shakti version of PMMVY, supported by the PMMVYSoft system.', 'update', '18 years 7 months–55 years', 'eligible age range', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2084399');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (422, 52, '2025-03-19', 'Over 53.76 Lakh Beneficiaries Covered Under PMMVY Scheme in FY 2023-24', 'The Ministry reported that 53,76,728 beneficiaries were covered under PMMVY during financial year 2023-24. The release also described the Rs 5,000 benefit for the first child and the Rs 6,000 benefit for a second child when the second child is a girl.', 'achievement', '53.76 lakh', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112761');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (423, 52, '2025-08-04', 'Special Registration Drive for Pradhan Mantri Matru Vandana Yojana Extended Till August 15, 2025; 4.05 Cr Women Receive Benefits Since Inception', 'The Ministry extended the special door-to-door registration and awareness drive for PMMVY until August 15, 2025. It reported that more than 4.05 crore beneficiaries had received at least one maternity-benefit instalment, totaling Rs 19,028 crore, through direct benefit transfer up to July 31, 2025.', 'update', '4.05 crore', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2152087');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (424, 53, '2023-04-14', 'National Agriculture Market (e-NAM) — One Nation One Market for Agricultural produce', 'The explainer describes e-NAM as a pan-India electronic trading portal linking Agricultural Produce Market Committee mandis into a unified national market. It highlights transparent online bidding, real-time price discovery, quality assaying and online payments for agricultural produce.', 'update', '30', 'lakh rupees maximum assistance per market', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2023/apr/doc2023414181301.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (425, 53, '2024-02-20', 'eNAM: Transforming Agricultural Trade into a Seamless Experience', 'The factsheet reports that e-NAM had integrated 1,389 mandis across 23 States and 4 Union Territories. It also records more than 1.77 crore registered farmers, 2.53 lakh traders and cumulative trade valued at approximately ₹3.19 lakh crore as of the stated reporting periods.', 'achievement', '1389', 'mandis', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2024/feb/doc2024220312801.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (426, 53, '2024-08-06', 'Farmer enrolment on e-NAM platform', 'The Ministry outlined measures to increase and simplify farmer enrolment on e-NAM, including registration at mandi premises, online portal and mobile-app registration, awareness campaigns and a toll-free helpline. The release reported 1,77,55,957 farmers enrolled across States and Union Territories.', 'update', '1,77,55,957', 'farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2042241');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (427, 53, '2024-12-20', 'Implementing of National Agriculture Market (e-NAM) Platform', 'The release states that e-NAM enables online trading of agricultural and horticultural commodities through competitive bidding and transparent price discovery. As of October 31, 2024, 1,389 mandis were integrated, with 1.78 crore farmers, 2.62 lakh traders and more than 4,250 FPOs registered; cumulative trade was reported at ₹3.79 lakh crore.', 'achievement', '3.79', 'lakh crore rupees cumulative trade', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2086484');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (428, 53, '2025-02-06', 'e-NAM Platform expanded to boost agricultural trade with addition of 10 new commodities and their tradable parameters', 'The Department of Agriculture and Farmers’ Welfare approved tradable parameters for 10 additional commodities, expanding the range of commodities covered by e-NAM. The total number of commodities with formulated tradable parameters consequently reached 231.', 'update', '231', 'commodities', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100393');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (429, 53, '2025-03-18', 'Encouraging Farmers to Participate in e-NAM Platform', 'The release describes online registration, training, helpline support, FPO aggregation and the farm-gate module as measures to encourage small and marginal farmers to use e-NAM. It reported 4,392 FPOs onboarded and tradable parameters finalized for 231 commodities as of February 28, 2025, while also describing plans for e-NAM 2.0.', 'update', '4392', 'FPOs onboarded', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112409');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (430, 53, '2025-07-25', 'Registration of FPOs, Farmers and Traders on e-NAM Platform', 'The release reported that 1,522 mandis had been integrated with e-NAM by June 30, 2025. It recorded 1,79,41,613 farmers, 2,67,719 traders and 4,518 FPOs registered, with cumulative agricultural-produce trade valued at ₹4,39,941 crore.', 'achievement', '4,39,941', 'crore rupees cumulative trade', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148525');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (431, 53, '2025-07-29', 'Agricultural Markets Linked to e-NAM', 'The release stated that 1,522 mandis had been integrated with the e-NAM portal as of June 30, 2025. It reported trade of 12.03 crore metric tonnes of agricultural commodities and 49.15 crore countable units, including coconut, betel leaf, sweet corn, lemon and bamboo.', 'achievement', '1522', 'mandis', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149699');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (432, 53, '2025-08-01', 'Farmers Registered on e-NAM Platform', 'The release reported that e-NAM had onboarded 1,522 mandis and registered 1,79,41,613 farmers, 2,67,719 traders and 4,518 FPOs as of June 30, 2025. It placed the cumulative value of agricultural produce traded on the platform at ₹4,39,941 crore.', 'achievement', '1,79,41,613', 'farmers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2151361');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (433, 53, '2025-10-08', 'e-NAM Platform Expanded: 09 New Commodities Added to Boost India’s largest digital agri-trade platform', 'The Department of Agriculture and Farmers’ Welfare added nine commodities to e-NAM in response to demand from farmers, traders and other stakeholders. The additions increased the total number of tradable agricultural commodities on the platform to 247.', 'update', '247', 'tradable commodities', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2176507');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (434, 54, '2020-12-30', 'Year End Review 2020 – Ministry of Power', 'The release states that DDUGJY had a total outlay of Rs. 75,893 crore, including Rs. 43,033 crore for DDUGJY and Rs. 32,860 crore for the rural electrification component. Projects costing Rs. 44,416 crore had been sanctioned in 33 States and Union Territories, with additional infrastructure sanctioned to support household electrification.', 'update', '75893', 'crore rupees', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1684579');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (435, 54, '2022-03-29', 'Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY) for rural electrification works', 'The release describes DDUGJY’s rural electrification components, including feeder separation, strengthening of sub-transmission and distribution infrastructure, metering, and village electrification. It notes that the scheme was launched in December 2014 for rural electrification works across the country.', 'launch', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1811049');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (436, 54, '2022-12-13', 'Villages electrified under Deendayal Upadhyaya Gram Jyoti Yojana (DDUGJY)', 'The release says that all villages and all willing households had been electrified by March 31, 2019, as reported by State Governments, through DDUGJY and Saubhagya. It also states that 2.86 crore households were electrified under Saubhagya, including households that became willing later.', 'achievement', '2.86', 'crore households', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1883110');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (437, 54, '2022-12-15', 'Rural Electrification Schemes', 'The release outlines DDUGJY’s objectives of electrifying un-electrified Census 2011 villages and strengthening rural distribution infrastructure through lines, metering, and feeder segregation. It also reports that 2.86 crore households had been electrified under Saubhagya after additional household electrification was sanctioned.', 'update', '2.86', 'crore households', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1883918');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (438, 54, '2023-02-07', 'Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY) scheme under Ministry of Power strengthens the electricity distribution system across the country', 'The release reports that DDUGJY strengthened electricity distribution through new and augmented substations, feeder separation, transformers, transmission lines, and village electrification. It states that 18,374 villages were electrified under the scheme.', 'achievement', '18374', 'villages', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1897040');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (439, 54, '2023-03-16', 'STATUS OF DDUGJY - A total of 18,374 villages were electrified under the scheme', 'The release states that all inhabited un-electrified Census 2011 villages had been electrified by April 28, 2018 under DDUGJY. It reports 18,374 villages electrified nationwide and says the scheme stood closed as of March 31, 2022.', 'achievement', '18374', 'villages', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1907722');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (440, 54, '2024-02-06', 'Nearly 88,000 households of Particularly Vulnerable Tribal Groups to be provided electricity under PM JANMAN', 'The release reports that 18,374 villages were electrified under the rural electrification programme, including 2,763 villages electrified through renewable resources. It also states that 2.86 crore households were electrified under Saubhagya.', 'achievement', '2763', 'villages electrified through renewable resources', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2003176');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (441, 54, '2024-07-25', 'DDUGJY', 'The release explains DDUGJY’s components and reports that Tamil Nadu’s sanctioned works included substations, feeder separation, distribution lines, meters, and household connections. It states that all physical works in Tamil Nadu were completed by December 31, 2020 and that the scheme stands closed.', 'update', '1195856', 'consumer energy meters', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2036987');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (442, 54, '2024-08-08', 'BENEFICIARIES UNDER DDUGJY', 'The release describes DDUGJY’s provision of electricity connections to BPL households and other rural households, including households left out under Saubhagya. It provides State-wise and year-wise household electrification details and notes that the scheme was closed on March 31, 2022.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2043155');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (443, 55, '2023-07-21', 'Update on Digital Healthcare Mechanism', 'The Ayushman Bharat Digital Mission supports integration of India''s digital health infrastructure through applications such as the ABHA app and Aarogya Setu. The release also describes assisted and offline ABHA creation, open standards, the ABDM sandbox, and initiatives to accelerate digital-health adoption.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1941463');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (444, 55, '2023-08-01', 'Update on Digital Healthcare Platforms: Electronic Health Record Standards under Ayushman Bharat Digital Mission aim to facilitate interoperability of healthcare information', 'The Ministry of Health and Family Welfare has notified Electronic Health Record standards to promote interoperability across healthcare information systems. The National Health Authority has also issued privacy, data-management, authentication, and sandbox-related guidelines for applications integrated with the ABDM ecosystem.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1944592');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (445, 55, '2023-07-25', 'National Digital Health Ecosystem', 'The release states that ABDM aims to create an interoperable digital-health platform and longitudinal electronic health records for citizens. It highlights the Union Health Ministry''s holistic approach to protecting the digital-health system from critical security threats and notes the role of the Health Data Management Policy in safeguarding privacy and data protection.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1942715');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (446, 55, '2024-02-06', 'Update on Ayushman Bharat Digital Mission: More than 52.5 Crore ABHA IDs created', 'More than 52.5 crore Ayushman Bharat Health Account numbers had been created under ABDM. The release explains that ABHA is a voluntary 14-digit health identifier intended to support interoperable health data and longitudinal electronic health records.', 'achievement', '52.5', 'crore ABHA IDs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2003068');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (447, 55, '2024-04-04', 'Explainer on Ayushman Bharat Health Accounts (ABHA)', 'ABHA is described as an integral component of ABDM and a 14-digit unique number that enables digital access to and sharing of health records. The explainer says individuals can enroll voluntarily and free of cost to participate in the ABDM digital-health ecosystem.', 'update', '14', 'digits', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2017129');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (448, 55, '2024-09-27', 'Ayushman Bharat Digital Mission marks a Transformative Three-Year Journey towards enabling Digital Health', 'ABDM completed three years since its launch, using digital public infrastructure to promote interoperable, secure, and citizen-centric healthcare. The release reports that more than 67 crore ABHA accounts had been created and outlines key components including the ABHA, healthcare professional, and health facility registries.', 'achievement', '67', 'crore ABHA accounts', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2059537');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (449, 55, '2024-12-06', 'Update on Ayushman Bharat Digital Mission', 'As of November 27, 2024, more than 68.97 crore ABHAs had been created, 3.49 lakh health facilities registered on the Health Facility Registry, 5.23 lakh healthcare professionals registered on the Healthcare Professional Registry, and 45.37 crore health records linked with ABHA. The release also reports progress on microsites, Scan and Share, Scan and Pay, and model ABDM facilities.', 'achievement', '68.97', 'crore ABHAs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2081482');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (450, 55, '2024-12-17', 'Update on Ayushman Bharat Digital Mission', 'As of December 10, 2024, more than 71.16 crore ABHAs had been created, with over 3.54 lakh health facilities and 5.37 lakh healthcare professionals registered in the relevant ABDM registries. More than 45.99 crore health records had also been linked with ABHA, while participation in ABDM remained voluntary.', 'achievement', '71.16', 'crore ABHAs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085201');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (451, 56, '2023-11-29', 'Free Foodgrains for 81.35 crore beneficiaries for five years: Cabinet Decision', 'The Cabinet approved free food grains under the Pradhan Mantri Garib Kalyan Anna Yojana for about 81.35 crore beneficiaries for five years beginning January 1, 2024. The initiative covers rice, wheat and coarse grains, with an estimated food subsidy of Rs. 11.80 lakh crore over the five-year period.', 'update', '81.35', 'crore beneficiaries', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1980686');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (452, 56, '2024-10-09', 'Cabinet approves continuation of supply of free Fortified Rice under Pradhan Mantri Garib Kalyan Anna Yojana (PMGKAY) and other welfare schemes from July, 2024 to December, 2028', 'The Union Cabinet approved continuation of the universal supply of fortified rice under PMGKAY and other government welfare schemes from July 2024 through December 2028. The initiative is fully funded by the Government of India and aims to address anaemia and micronutrient deficiencies.', 'update', '100', 'percent universal coverage', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2063447');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (453, 56, '2024-12-20', 'Year-End Review of Department of Food and Public Distribution–2024', 'The 2024 review states that free food grain distribution under PMGKAY was extended for five years from January 1, 2024, following the initial one-year period that began in 2023. It reports that approximately 80.67 crore people were receiving food grains free of cost against intended coverage of 81.35 crore persons.', 'achievement', '80.67', 'crore persons', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2086345');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (454, 57, '2022-11-04', 'Aibawk cluster in the Aizawl, Mizoram becomes the first cluster to be completed under the Shyama Prasad Mukherji Rurban Mission', 'The Aibawk Rurban cluster in Mizoram became the first cluster completed under the Shyama Prasad Mukherji Rurban Mission. It completed all planned projects, including improvements to roads, footpaths, drainage, water supply, market access, livelihoods, tourism and social infrastructure.', 'achievement', '48', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1873772');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (455, 51, '2023-04-05', 'Increase in MGNREGS Funds', 'The Ministry reported that employment demand under Mahatma Gandhi NREGS reached 6.90 crore households in FY 2022-23, with 6.89 crore households offered employment as of March 31, 2023. The revised allocation for FY 2022-23 was increased to Rs. 89,400 crore from the budget estimate of Rs. 73,000 crore.', 'update', '89,400', 'crore rupees', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1914156');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (456, 51, '2023-10-20', 'Minister of Rural Development and Panchayati Raj Shri Giriraj Singh briefs media and launches brochures on “9 Years’ achievements of Rural Development”', 'The Minister said there was no deficit of funds under MGNREGS and that additional funds had been sought from the Ministry of Finance. The release also reported that 2,644 crore person-days had been generated under NREGA during the preceding nine years, with more than Rs. 6.63 lakh crore released as the central share.', 'achievement', '2,644', 'crore person-days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1969449');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (457, 51, '2024-12-03', 'Mahatma Gandhi National Rural Employment Guarantee Scheme ensuring 100 days of wage employment for rural households', 'The release reiterates that Mahatma Gandhi NREGS provides at least 100 days of guaranteed wage employment to rural households whose adult members volunteer for unskilled manual work. It reported 25.68 crore registered workers in FY 2023-24 and 25.17 crore registered workers as of November 29, 2024, in FY 2024-25.', 'update', '100', 'days of guaranteed employment', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2080090');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (458, 51, '2024-12-31', 'Year End Review 2024: Achievement of the Department of Rural Development', 'The Department reported that 196.30 crore person-days were generated under MGNREGA in FY 2024-25 through December 11, 2024. The release highlighted digital and monitoring interventions including NMMS, GeoMGNREGA, the Aadhaar Payment Bridge System and the JALDOOT App.', 'achievement', '196.30', 'crore person-days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2088996');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (459, 51, '2025-02-04', 'Removal of workers from Mahatma Gandhi National Rural Employment Guarantee Scheme', 'The Ministry stated that deletion or updating of job cards is conducted by States and Union Territories, which must ensure that eligible households are not removed. It reported that 86,17,887 active workers were deleted or cancelled in FY 2022-23 and 68,86,532 in FY 2023-24 for reasons including fake or duplicate cards and permanent relocation.', 'update', '86,17,887', 'active workers deleted or cancelled', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099773');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (460, 51, '2025-02-07', 'RURAL DISTRESS SHOWCASED BY RISE IN HOUSEHOLDS UNDER MGNREGS', 'The release describes MGNREGS as a demand-driven scheme providing at least 100 days of guaranteed wage employment. It also reports that Project UNNATI had trained 82,799 MGNREGS workers as of December 31, 2024, against a project objective of training 2 lakh workers.', 'achievement', '82,799', 'workers trained', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2100660');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (461, 51, '2025-03-11', 'REFORMS IN MGNREGS', 'The Ministry said MGNREGS is implemented through the NREGASoft transaction-based management information system, covering job cards, work approvals, muster rolls, measurements and DBT payments. The release also described monitoring and evaluation arrangements intended to strengthen transparency, accountability and proper use of funds.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2110306');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (462, 51, '2025-03-11', 'APP-BASED ATTENDANCE SYSTEM', 'The Ministry stated that attendance at MGNREGS worksites is to be captured through the NMMS App using two time-stamped, geo-tagged photographs per day, subject to specified exceptions. Attendance captured through the app reached 95.21% in the first fortnight and 96.37% in the second fortnight of FY 2024-25 to date.', 'update', '96.37', 'percent attendance captured', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2110305');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (463, 51, '2025-03-19', 'Effective implementation of Mahatma Gandhi National Rural Employment Guarantee Scheme in the current decade', 'The release compared MGNREGA performance before and after 2014, reporting 3,029 crore person-days generated between FY 2014-15 and FY 2024-25, versus 1,660 crore in the preceding period. It also stated that Rs. 7,81,302 crore had been released during FY 2014-15 to FY 2024-25, resulting in the creation of 8.07 crore rural assets.', 'achievement', '3,029', 'crore person-days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112680');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (464, 51, '2025-03-21', 'Expanding Scope of Mahatma Gandhi National Rural Employment Guarantee Scheme', 'The Ministry explained that Scheduled Tribe households in forest areas meeting specified conditions can receive an additional 50 days of wage employment beyond the standard 100 days. It also noted that up to 50 additional days may be provided in drought- or natural-calamity-affected notified rural areas.', 'target', '50', 'additional days of employment', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113754');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (465, 51, '2025-03-25', 'Fund for Mahatma Gandhi National Rural Employment Guarantee Scheme', 'The Ministry reported a budget allocation of Rs. 86,000 crore for MGNREGS in FY 2024-25, describing it as the highest budget-estimate allocation since the scheme began. The same allocation was retained for FY 2025-26, with additional funds to be sought when required by employment demand.', 'target', '86,000', 'crore rupees', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2114882');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (466, 51, '2025-04-04', 'WORKING OF MGNREGS', 'The Ministry described MGNREGS as a demand-driven wage employment scheme providing livelihood security to rural households when better employment is unavailable. It stated that pending and admissible liabilities up to FY 2023-24 had been released to the States and Union Territories, while providing state-wise person-day and wage-fund data through March 2025.', 'update', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2118849');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (467, 51, '2025-07-25', 'EMPLOYMENT GENERATION UNDER MGNREGA', 'The Ministry reported that 3.83 crore households availed themselves of MGNREGS employment in FY 2025-26 as of July 21, 2025. During the same period, the scheme generated 106.77 crore person-days, alongside measures intended to improve timely wage payments.', 'achievement', '106.77', 'crore person-days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148473');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (468, 51, '2025-07-25', 'BUDGET ALLOCATION UNDER MGNREGA', 'The release listed budget estimates, revised estimates and funds released under MGNREGS for the previous five financial years. It stated that Rs. 86,000 crore was allocated for FY 2024-25 and retained for FY 2025-26, while 99.79% of eligible rural households had been offered employment against their demand as of July 22, 2025.', 'target', '99.79', 'percent of eligible households offered employment', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148475');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (469, 51, '2025-07-22', 'ISSUES RELATING TO WAGES UNDER MGNREGS', 'The Ministry reported that more than 96% of fund transfer orders had consistently been generated within 15 days of muster-roll closure during the previous five financial years. It also stated that all pending wage liabilities up to FY 2024-25 had been cleared and that wage payments are made directly through DBT.', 'update', '96', 'percent of FTOs generated within 15 days', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2146874');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (470, 51, '2025-07-22', 'Cancellation Of Fake Job Cards Under MGNREGS', 'The Ministry reported that 759,362 fake job cards were deleted in FY 2022-23, 289,626 in FY 2023-24 and 58,826 in FY 2024-25. It stated that States and Union Territories are primarily responsible for investigating and taking action against irregularities in scheme implementation.', 'update', '759,362', 'fake job cards deleted', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2146877');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (471, 33, '2024-02-09', 'Growth of Indian Maritime Sector', 'The Government says the Sagarmala Programme includes projects for port modernization, RoRo/RoPax and tourism jetties, port connectivity, fishing harbours, and skill development. A total of 839 projects valued at approximately ₹5.8 lakh crore were identified for implementation, of which 241 projects worth about ₹1.22 lakh crore had been completed.', 'achievement', '839', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2004338');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (472, 33, '2024-07-26', 'Sagarmala Projects', 'The Ministry provided details of Sagarmala-funded projects and financial assistance to states and Union Territories, including port infrastructure, coastal berths, road and rail connectivity, fishing harbours, and cruise terminals. Under the scheme, 130 projects with a total project cost of ₹9,580 crore were listed, with ₹3,714 crore sanctioned.', 'update', '130', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2037358');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (473, 33, '2024-07-26', 'Sagarmala Projects: Transforming Andhra Pradesh with more than Rs.7000 Crore Investment', 'The Ministry reported that 29 new proposals from Andhra Pradesh, worth approximately ₹3,300 crore, had been received under the Sagarmala Programme. It also stated that 13 projects valued at about ₹2,500 crore were receiving financial assistance, while projects undertaken by Visakhapatnam Port Authority and IWAI represented combined investment of ₹4,600 crore.', 'update', '7000', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2037516');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (474, 33, '2025-03-21', 'SAGARMALA SCHEME', 'The Ministry reported that 119 projects costing ₹9,407 crore had been undertaken for partial funding under the Sagarmala Scheme. Of these, 72 projects had been completed, while eight projects worth ₹273 crore were receiving assistance in Kerala.', 'achievement', '119', 'projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113674');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (475, 33, '2025-07-22', 'Sagarmala Programme in Tamilnadu', 'The Ministry provided a state-wise update on Sagarmala-funded projects in Tamil Nadu, covering port infrastructure, coastal berths, fishing harbours, skill development, and coastal community development. The listed projects included completed and under-implementation works with details of project costs, sanctioned funds, and funds released.', 'update', '148', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2146790');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (476, 6, '2023-07-31', '6,23,10,598 loans sanctioned under Pradhan Mantri MUDRA Yojana (PMMY) in FY 2022-23', 'The Ministry of Finance stated that 6,23,10,598 PMMY loans were sanctioned in FY 2022-23, compared with 5,37,95,526 in FY 2021-22. The scheme provides collateral-free institutional credit of up to Rs. 10 lakh to eligible micro and small enterprises.', 'achievement', '6,23,10,598', 'loans', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1944393');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (477, 6, '2024-07-22', 'FEMALE LABOUR FORCE PARTICIPATION RATE (LFPR) ROSE TO 37 PER CENT IN 2022-2023 FROM 23.3 PER CENT IN 2017-2018', 'The Economic Survey 2023-24 reported that around 68 percent of loans sanctioned under Pradhan Mantri Mudra Yojana had gone to women entrepreneurs as of May 2024. The release presented this figure alongside broader indicators of women''s financial and economic empowerment.', 'achievement', '68', 'percent of PMMY loans sanctioned to women', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2034928');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (478, 6, '2024-10-25', 'Loan limit under Pradhan Mantri Mudra Yojana (PMMY) increased to Rs.20 lakh from the current Rs.10 lakh', 'The Ministry of Finance announced that the PMMY loan limit was increased from Rs. 10 lakh to Rs. 20 lakh. A new Tarun Plus category was introduced for borrowers who had successfully repaid previous Tarun loans, with guarantee coverage provided through the Credit Guarantee Fund for Micro Units.', 'update', '20 lakh', 'maximum loan limit', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2068019');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (479, 6, '2024-10-29', 'Pradhan Mantri Mudra Yojana Loan Limit Raised to ₹20 Lakh from ₹10 Lakh', 'The release reiterated that the PMMY loan ceiling had been raised to ₹20 lakh from ₹10 lakh, effective October 24, 2024. It also described the Tarun Plus category for eligible repeat borrowers and the expanded guarantee coverage under CGFMU.', 'update', '20 lakh', 'maximum loan limit', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2069170');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (480, 6, '2025-04-07', 'A Decade of Growth with PM Mudra Yojana Fueling grassroots entrepreneurship and expanding financial inclusion', 'The release marked ten years of PMMY and stated that the scheme had sanctioned over 52 crore loans worth ₹32.61 lakh crore since its launch. It highlighted the scheme''s role in expanding institutional credit access for non-corporate, non-farm micro and small enterprises, including women-led businesses.', 'achievement', '₹32.61 lakh crore', 'sanctioned loan value', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2119781');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (481, 6, '2025-04-08', 'Pradhan Mantri Mudra Yojana (PMMY) — completes 10 glorious Years of empowering Small and Micro Entrepreneurs', 'The Ministry of Finance stated that PMMY had extended more than 52.37 crore loans amounting to over ₹33.65 lakh crore during its first decade. The release also noted that the scheme provides collateral-free loans of up to ₹20 lakh, including through the newly introduced Tarun Plus category.', 'achievement', '₹33.65 lakh crore', 'loan value extended', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2119954');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (482, 8, '2023-08-28', 'Pradhan Mantri Jan Dhan Yojana (PMJDY) - National Mission for Financial Inclusion, completes nine years of successful implementation', 'More than 50 crore beneficiaries had been brought into the formal banking system under PMJDY since its launch. Total deposits stood at Rs. 2,03,505 crore as of 16 August 2023, with about 56% of account holders being women and about 67% of accounts located in rural and semi-urban areas.', 'achievement', '50.09', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1952793');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (483, 8, '2024-08-05', '52.81 crore PM Jan-Dhan accounts with deposit balance of Rs. 2,30,792 crore opened as on 19.07.2024 under PMJDY', 'The Ministry of Finance reported that 52.81 crore Jan-Dhan accounts had been opened under PMJDY as of 19 July 2024, with deposits totaling Rs. 2,30,792 crore. Women held 55.6% of these accounts, while 66.6% were located in rural and semi-urban areas.', 'update', '52.81', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2041903');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (484, 8, '2024-08-28', 'Pradhan Mantri Jan Dhan Yojana (PMJDY) — National Mission for Financial Inclusion — completes a decade of successful implementation', 'PMJDY completed ten years, with more than 53.14 crore beneficiaries brought into the formal banking system. Deposits in PMJDY accounts reached Rs. 2,31,236 crore, and 36.14 crore RuPay cards had been issued as of 14 August 2024.', 'achievement', '53.14', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2049231');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (485, 8, '2025-02-01', 'Driving Financial Empowerment', 'The Ministry of Finance highlighted PMJDY as a major financial-inclusion initiative, reporting more than 54.58 crore accounts and deposits of Rs. 2.46 lakh crore by January 2025. The release also noted growth in insurance, pension, and entrepreneurship schemes supporting financial security and inclusive growth.', 'achievement', '54.58', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098435');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (486, 8, '2025-02-10', 'Special campaigns have been launched for enrolling individuals under various financial inclusion Schemes', 'The government reported that 54.58 crore Jan-Dhan accounts had been opened as of 15 January 2025, including 30.37 crore accounts held by women. It also described special campaigns, banking correspondents, and digital banking units intended to expand access to financial inclusion and credit-linked schemes.', 'update', '54.58', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2101428');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (487, 8, '2025-03-18', 'A total of 55.02 crore Jan-Dhan accounts have been opened till 7th March 2025', 'The Ministry of Finance stated that 55.02 crore Jan-Dhan accounts had been opened by 7 March 2025, of which 36.63 crore were in rural and semi-urban areas. The release also reported progress under related insurance, pension, Mudra, and Stand-Up India financial-inclusion schemes.', 'update', '55.02', 'crore accounts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112321');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (488, 12, '2023-03-23', 'Union Agriculture Minister Shri Tomar launches DigiClaim for claim disbursal through National Crop Insurance Portal (NCIP)', 'The Ministry launched the DigiClaim module under PMFBY to electronically disburse insurance claims through the National Crop Insurance Portal. Claims totaling ₹1,260.35 crore were disbursed to insured farmers in six states on the launch date, while cumulative PMFBY claim disbursals had reached ₹1.32 lakh crore.', 'launch', '1260.35', 'crore claims disbursed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1909895');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (489, 12, '2023-07-21', 'Centre launches technological advancements in crop insurance to empower farmers and streamline operations in PMFBY', 'The Ministry launched the YES-Tech Manual, WINDS portal and AIDE/Sahayak door-to-door enrollment app under PMFBY and related crop-insurance schemes. YES-Tech had been tested and piloted in 100 districts to support technology-based yield estimation and more accurate claim assessment.', 'launch', '100', 'districts', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1941597');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (490, 12, '2023-12-08', 'Enrollment of Farmers and Claim Settlement under Pradhan Mantri Fasal Bima Yojana', 'The release reported that 435 lakh farmer applications were enrolled under PMFBY during Rabi 2022-23 and 689 lakh during Kharif 2023, based on data available up to November 30, 2023. It also stated that ₹3,878 crore in claims had been paid to 7.8 lakh farmer applications for Rabi 2022-23.', 'update', '435 lakh; 689 lakh', 'farmer applications enrolled', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1984068');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (491, 12, '2024-03-06', 'Enrolment under PMFBY increases by 27% in the current year so far', 'The release stated that 56.80 crore farmer applications had been enrolled under PMFBY since its implementation and that more than 23.22 crore farmer applicants had received claims. Farmers had paid approximately ₹31,139 crore in premiums against claims exceeding ₹1,55,977 crore, equivalent to about ₹500 in claims for every ₹100 paid as premium.', 'achievement', '56.80 crore', 'farmer applications enrolled', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2011791');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (492, 12, '2024-08-06', 'Revival of Fasal Bima Yojana', 'The Ministry reported that PMFBY coverage in 2023-24 had reached an all-time high and that the scheme had become the world''s largest in terms of farmer applications insured. Of ₹1,67,475 crore in reported claims, ₹1,63,519 crore, or 98%, had been paid.', 'achievement', '98%', 'reported claims paid', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2042245');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (493, 12, '2025-02-04', 'Insurance Claims by Farmers', 'The release provided details on crop-insurance claims under PMFBY and RWBCIS and reported that farmer applications under the schemes had reached an all-time high in 2023-24. Applications grew 35.12% year-on-year in 2022-23 and 27.50% in 2023-24.', 'update', '27.50%', 'year-on-year growth in farmer applications', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099760');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (494, 12, '2025-01-01', 'Cabinet approves modification/addition of features and provisions in PMFBY and RWBCIS', 'The Union Cabinet approved continuation of PMFBY and RWBCIS through 2025-26 with an overall outlay of ₹69,515.71 crore for 2021-22 to 2025-26. It also approved a ₹824.77 crore Fund for Innovation and Technology to support initiatives such as YES-Tech and WINDS.', 'target', '69,515.71', 'crore total outlay', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2089250');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (495, 12, '2025-02-17', 'Pradhan Mantri Fasal Bima Yojana turns nine: Empowering Annadata and Protecting Livelihoods', 'The release marked PMFBY''s ninth anniversary and described the scheme''s role in protecting farmers against crop losses caused by natural calamities. It highlighted the Cabinet-approved continuation of PMFBY and RWBCIS through 2025-26 with a total budget of ₹69,515.71 crore, along with technology-based tools for crop-yield estimation and claim assessment.', 'achievement', '69,515.71', 'crore budget through 2025-26', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2104175');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (496, 12, '2025-07-25', 'Implementation of PMFBY', 'The Ministry reported that the number of farmers enrolled under PMFBY increased from 3.17 crore in 2022-23 to 4.19 crore in 2024-25, a 32% rise and the highest level since the scheme began. The release also noted that 6.5% of 2024-25 applications related to tenant farmers, 17.6% to marginal farmers and 48% to loanee farmers.', 'achievement', '32%', 'increase in farmers enrolled', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148513');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (497, 17, '2023-08-09', 'Make in India initiative to make India a hub for manufacturing, design and innovation', 'The release says foreign direct investment equity inflow in the manufacturing sector increased by 57% during 2014–2022 compared with 2006–2014, attributing the rise to the Make in India initiative. It also describes policy measures including PLI schemes, investment facilitation, and initiatives to strengthen domestic manufacturing. ([pib.gov.in](https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1947211))', 'achievement', '57', 'percent', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1947211');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (498, 17, '2023-12-26', '2023 Year End Review for Department for Promotion of Industry and Internal Trade', 'The DPIIT year-end review reports that Make in India 2.0 is focused on 27 sectors to develop India as a manufacturing hub. It also highlights PLI progress, including more than ₹95,000 crore in reported investment, ₹7.80 lakh crore in production or sales, and over 6.4 lakh direct and indirect jobs through September 2023. ([pib.gov.in](https://pib.gov.in/PressReleasePage.aspx?PRID=1990377))', 'achievement', '27', 'sectors', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1990377');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (499, 17, '2024-09-30', 'Business Reforms Action Plan 2024 to further strengthen Make in India; bring seamless business regulatory framework across India', 'DPIIT announced BRAP 2024 to strengthen the Make in India initiative by creating a more seamless and efficient business regulatory framework. The plan emphasizes reducing approval times, expanding online service delivery, reducing compliance burdens, and using digital platforms to improve India’s investment environment. ([pib.gov.in](https://pib.gov.in/PressReleasePage.aspx?PRID=2060200))', 'target', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2060200');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (500, 17, '2024-10-04', 'Advancing industrial growth and empowering local economy main focus of DPIIT in the first 100 days of government', 'The release describes DPIIT initiatives supporting Make in India, including 12 new world-class industrial smart cities under the National Industrial Corridor Development Programme. It also highlights PM Ekta Malls for local products and a Public Procurement (Make in India) Order requiring items with sufficient domestic capacity to be sourced from local suppliers. ([pib.gov.in](https://pib.gov.in/PressReleasePage.aspx?PRID=2062126))', 'achievement', '12', 'industrial smart cities', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2062126');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (501, 17, '2024-12-20', '2024 Year End Review for Department for Promotion of Industry and Internal Trade', 'The DPIIT year-end review reports major manufacturing achievements under the PLI scheme, which supports the Make in India and self-reliance agenda. It records ₹1.46 lakh crore in investment, ₹12.50 lakh crore in production or sales, ₹4 lakh crore in exports, and 9.5 lakh direct and indirect jobs. ([pib.gov.in](https://pib.gov.in/PressReleasePage.aspx?PRID=2086347))', 'achievement', '1.46', 'lakh crore investment', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2086347');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (502, 20, '2023-09-01', 'More than 6.62 crore subscribers under National Pension System (NPS) and Atal Pension Yojana (APY); assets under management cross Rs. 10 lakh crore', 'The Ministry of Finance reported that the combined subscriber base of NPS and APY had exceeded 6.62 crore. Their combined assets under management also crossed Rs. 10 lakh crore.', 'achievement', '6.62 crore', 'subscribers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1954021');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (503, 20, '2024-10-08', 'Gross enrolments under Atal Pension Yojana (APY) cross 7 crore mark, with over 56 lakh enrolments in current Financial Year 2024-25', 'Total gross enrolments under APY crossed 7 crore. More than 56 lakh new enrolments were recorded during Financial Year 2024-25 at the time of the release.', 'achievement', '7 crore', 'gross enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2063311');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (504, 20, '2025-02-01', 'Transformative schemes boost financial inclusion, insurance, and entrepreneurship', 'The Ministry of Finance stated that APY enrolments reached 7.33 crore by January 2025. More than 89.95 lakh new APY enrolments were recorded in Financial Year 2024-25.', 'update', '7.33 crore', 'APY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098435');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (505, 20, '2025-03-18', 'Financial inclusion schemes show substantial progress, including Atal Pension Yojana', 'The Ministry of Finance reported that APY enrolments stood at 7.49 crore as of March 7, 2025. The release described APY as part of the government''s broader financial inclusion initiatives.', 'update', '7.49 crore', 'APY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112321');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (506, 20, '2025-05-09', 'Three Jan Suraksha Schemes complete 10 years of providing social security cover', 'The three Jan Suraksha schemes, including APY, completed ten years since their launch. More than 7.66 crore individuals had subscribed to APY as of April 23, 2025.', 'achievement', '7.66 crore', 'APY subscribers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2127981');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (507, 20, '2025-07-25', 'Atal Pension Yojana (APY) achieves major milestone, gross enrolments surpass 8 crore', 'Gross APY enrolments surpassed 8 crore, with 39 lakh new subscribers added during Financial Year 2025-26. The milestone coincided with the scheme''s tenth anniversary.', 'achievement', '8 crore', 'gross enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2148460');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (508, 20, '2025-08-25', 'PFRDA hosts Atal Pension Yojana Annual Felicitation Programme; APY marks a decade of success', 'APY gross enrolments crossed 8.11 crore as of August 21, 2025, including more than 1.17 crore new subscribers in Financial Year 2024-25. Women accounted for 55% of enrolments during that financial year.', 'achievement', '8.11 crore', 'gross enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2160620');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (509, 20, '2025-10-09', 'Assets under Management of NPS and APY cross ₹16 lakh crore; subscriber base surpasses 9 crores', 'The combined assets under management of NPS and APY crossed ₹16 lakh crore. Their combined subscriber base also exceeded 9 crore.', 'achievement', '₹16 lakh crore', 'combined AUM', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2177002');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (510, 20, '2025-12-01', 'Atal Pension Yojana reaches 8.34 crore enrolments; women account for 48%', 'The Ministry of Finance reported gross APY enrolment of 8,34,13,738 as of October 31, 2025. Women represented 48% of enrolments, while the scheme continued to provide guaranteed pension benefits after age 60.', 'update', '8.34 crore', 'gross enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2197218');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (511, 20, '2025-12-15', 'Atal Pension Yojana reaches the poorest of the poor, with majority enrolments in the lower pension slab', 'A total of 8,45,17,419 subscribers had enrolled under APY as of November 30, 2025. The ₹1,000 monthly pension slab accounted for 86.91% of gross enrolments, indicating strong participation among lower-income subscribers.', 'update', '8,45,17,419', 'subscribers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2204271');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (512, 20, '2026-01-21', 'Cabinet approves continuation of Atal Pension Yojana and extension of funding support through 2030-31', 'The Union Cabinet approved continuation of APY through Financial Year 2030-31. It also approved continued funding support for promotional and developmental activities and gap funding.', 'target', '2030-31', 'financial year', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2216727');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (513, 21, '2023-05-09', 'Pradhan Mantri Suraksha Bima Yojana (PMSBY), PMJJBY and APY complete 8 years of providing social security cover', 'The Ministry of Finance reported that the three Jan Suraksha schemes had expanded affordable insurance and pension coverage. PMSBY had recorded about 34.2 crore enrolments by 26 April 2023.', 'achievement', '34.2 crore', 'PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1922622');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (514, 21, '2023-07-25', '1,19,224 claims paid under Pradhan Mantri Suraksha Bima Yojana (PMSBY) scheme', 'The Ministry of Finance stated that PMSBY is available to bank and post-office account holders aged 18 to 70 years. As of 28 June 2023, insurers had paid 1,19,224 claims and rejected 30,549 claims since the scheme began.', 'achievement', '1,19,224', 'claims paid', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1942515');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (515, 21, '2025-02-01', 'Driving Financial Empowerment', 'The Ministry of Finance highlighted progress in financial inclusion and insurance coverage. PMSBY had covered 49.12 crore people, with ₹2,994.75 crore processed against accident claims.', 'achievement', '49.12 crore', 'people covered', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2098435');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (516, 21, '2025-03-18', 'A total of 55.02 crore Jan-Dhan accounts have been opened; cumulative PMSBY enrolment is 50.30 crore', 'The Ministry of Finance reported that cumulative PMSBY enrolment reached 50.30 crore as of 7 March 2025. The release also described PMSBY’s accidental death and disability cover of up to ₹2 lakh at an annual premium of ₹20.', 'achievement', '50.30 crore', 'cumulative PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2112321');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (517, 21, '2025-05-09', 'Three Jan Suraksha Schemes complete 10 years of providing social security cover', 'The Ministry of Finance marked the tenth anniversary of PMSBY, PMJJBY and APY. PMSBY had recorded more than 51.06 crore enrolments and paid ₹3,121.02 crore for 1,57,155 claims as of 23 April 2025.', 'achievement', '51.06 crore', 'cumulative PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2127981');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (518, 21, '2025-07-31', 'Nationwide Financial Inclusion Saturation Campaign sees significant progress in the first month', 'The Ministry of Finance reported that the campaign organized nearly 1 lakh camps during its first month to expand access to financial-inclusion schemes. These camps generated 12,36,548 new PMSBY enrolments and helped settle claims under PMJJBY and PMSBY.', 'achievement', '12,36,548', 'new PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2150999');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (519, 21, '2025-08-18', 'Financial Inclusion is Government’s Key Priority; Financial Inclusion Saturation Campaign reaches 2.7 lakh Panchayats and ULBs', 'The Ministry of Finance reiterated that PMSBY provides ₹2 lakh cover for accidental death or total permanent disability and ₹1 lakh for partial permanent disability at a ₹20 annual premium. It also announced grassroots campaigns across 2.70 lakh gram panchayats and urban local bodies and a Jansuraksha portal for scheme information.', 'target', '2.70 lakh', 'gram panchayats and ULBs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157540');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (520, 21, '2025-09-16', 'Nationwide Financial Inclusion Saturation Campaign sees significant progress', 'The Ministry of Finance reported that more than 2.3 lakh camps had been organized during the campaign’s first two and a half months. The campaign produced 1.56 crore fresh PMSBY enrolments between 1 July and 14 September 2025.', 'achievement', '1.56 crore', 'new PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2167327');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (521, 21, '2025-11-10', 'DFS successfully concludes the four-month Nationwide Financial Inclusion Saturation Campaign', 'The Department of Financial Services, Ministry of Finance, reported that the campaign concluded after organizing 2,67,345 camps across villages and towns. It recorded 2.86 crore fresh PMSBY enrolments and 92,066 claims settled under PMJJBY and PMSBY.', 'achievement', '2.86 crore', 'fresh PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2188526');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (522, 21, '2026-03-10', 'Government takes measures to increase enrolment and ensure timely disbursement of benefits under PMJJBY', 'The Ministry of Finance described measures to improve enrolment and claim payments under PMJJBY and PMSBY, including grassroots campaigns and the Jansuraksha portal. A nationwide saturation campaign was conducted across 2.70 lakh gram panchayats and urban local bodies from July through October 2025.', 'update', '2.70 lakh', 'gram panchayats and ULBs', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2237489');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (523, 21, '2026-03-16', 'Government strengthens financial inclusion ecosystem through flagship schemes', 'The Ministry of Finance reported that PMSBY had reached 57.11 crore cumulative enrolments as of 25 February 2026. The release restated that the scheme provides one-year accidental cover of ₹2 lakh for death or permanent total disability and ₹1 lakh for permanent partial disability.', 'achievement', '57.11 crore', 'cumulative PMSBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2240720');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (524, 22, '2023-04-11', 'DFS Secretary chairs meeting with Chief Secretaries to boost enrolments under PMJJBY & PMSBY during the 3-month long campaign', 'The Ministry of Finance launched a three-month campaign covering all districts from April 1 to June 30, 2023, to increase enrolment in PMJJBY and PMSBY at the Gram Panchayat level. At the time, PMJJBY had 8.3 crore active enrolments, while claims of about Rs. 15,500 crore had been paid under both schemes.', 'target', '8.3', 'crore active enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1915493');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (525, 22, '2023-10-19', 'DFS Secretary Dr. Vivek Joshi chairs review meeting on progress of Financial Inclusion Schemes with heads of PSBs and senior executives of NABARD, SIDBI, Mudra Ltd. and NPCI', 'The Department of Financial Services reviewed progress under PMJJBY and other financial-inclusion schemes with public-sector banks and financial institutions. The meeting emphasized fulfilling scheme targets and monitoring the Jan Suraksha saturation campaign conducted across Gram Panchayats from October 1 to December 31, 2023.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=1969225');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (526, 22, '2025-05-09', 'Three Jan Suraksha Schemes - Pradhan Mantri Suraksha Bima Yojana (PMSBY), Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY) and Atal Pension Yojana (APY) complete 10 years of providing social security cover', 'The three Jan Suraksha schemes completed ten years of providing affordable insurance and pension coverage. As of April 23, 2025, PMJJBY had more than 23.63 crore cumulative enrolments and had paid Rs. 18,397.92 crore in claims.', 'achievement', '23.63', 'crore cumulative enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2127981');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (527, 22, '2025-07-15', 'Nationwide Financial Inclusion Saturation Campaign sees a Significant Progress', 'The Ministry of Finance reported progress in a nationwide campaign to expand access to PMJJBY, PMSBY, APY and PMJDY. Among the reported activities, 1,83,225 new PMJJBY enrolments were recorded through camps conducted since July 1, 2025.', 'update', '1,83,225', 'new PMJJBY enrolments', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2144990');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (528, 22, '2025-08-18', 'Financial Inclusion is Government’s Key priority; Flagship schemes provide affordable insurance and health protection for all, including SC, ST, and OBCs', 'The release highlights PMJJBY as an affordable life-insurance scheme offering coverage for death from any cause to eligible people aged 18–50. It states that the scheme provides Rs. 2 lakh of insurance coverage for an annual premium of Rs. 436 and describes measures to expand outreach through grassroots campaigns and the Jan Suraksha portal.', 'update', '2', 'lakh insurance cover', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157540');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (529, 23, '2025-04-05', '9 Years of Stand-Up India: Turning Aspirations into Achievements', 'The Stand-Up India Scheme has sanctioned Rs. 61,020.41 crore since its launch, as of 17 March 2025. The release highlights growth in sanctioned loans and accounts among SC, ST, and women entrepreneurs.', 'achievement', '61020.41', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2119045');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (530, 23, '2025-07-22', 'Stand-Up India Scheme Provides Financial and Institutional Aid to the Marginalized', 'Between April 2022 and March 2025, the Stand-Up India Scheme sanctioned 126,508 loans totaling Rs. 28,996.15 crore to SC, ST, and women entrepreneurs. The scheme also provided guidance, training, mentorship, and links to skilling and entrepreneurship-support institutions.', 'achievement', '28996.15', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2146820');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (531, 23, '2024-07-29', 'Government Has Taken Various Initiatives to Promote Entrepreneurship Across Different Sections of Society', 'The release states that the Stand-Up India Scheme has been extended through 2025 and facilitates loans of Rs. 10 lakh to Rs. 1 crore for greenfield enterprises owned by SC, ST, and women entrepreneurs. As of June 2024, more than 2.35 lakh loans had been facilitated nationally, including 0.22 lakh loans sanctioned in Tamil Nadu.', 'update', '2.35', 'lakh loans', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2038403');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (532, 27, '2024-09-18', 'Cabinet approves continuation of schemes of Pradhan Mantri Annadata Aay SanraksHan Abhiyan (PM-AASHA)', 'The Union Cabinet approved continuation of the integrated PM-AASHA scheme through 2025-26 to provide remunerative prices to farmers and control price volatility for consumers. The scheme received a total financial outlay of Rs. 35,000 crore, with a 25% procurement ceiling for notified pulses, oilseeds and copra, except for 100% procurement of Tur, Urad and Masur in 2024-25.', 'update', '35000', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2055991');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (533, 27, '2024-12-18', 'Empowering Farmers Through PM-AASHA', 'Under PM-AASHA, the government procured 6.41 lakh metric tonnes of pulses during the Rabi 2023-24 season, benefiting 2.75 lakh farmers. The release states that the scheme provides price assurance for notified pulses, oilseeds and copra and supports farmers through procurement and price-deficiency mechanisms.', 'achievement', '6.41', 'LMT of pulses', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085530');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (534, 27, '2025-02-17', 'Government approves Pradhan Mantri Annadata Aay Sanrakshan Abhiyan (PM-AASHA) Scheme till 2025-26 during the 15th Finance Commission cycle', 'The government approved continuation of the integrated PM-AASHA scheme through 2025-26 and authorized procurement of Tur, Urad and Masur equivalent to 100% of state production for the 2024-25 procurement year. The release also reports approval for procurement of 13.22 LMT of Tur across nine states, with 0.15 LMT already procured and 12,006 farmers benefiting.', 'target', '100%', 'of state production', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2104121');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (535, 27, '2025-03-21', 'Measures to Reduce Dependence on Middlemen under Pradhan Mantri Annadata Aay Sanrakshan Abhiyan (PM-AASHA)', 'The release explains that PM-AASHA procurement is conducted at MSP through central nodal agencies such as NAFED and NCCF, using pre-registered farmers with legitimate land records to reduce the role of middlemen. It also states that the 25% procurement ceiling for Tur, Urad and Masur was lifted for 2023-24 and extended to 2024-25.', 'update', '25%', 'procurement ceiling', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2113721');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (536, 27, '2025-08-12', 'Pradhan Mantri Annadata Aay Sanrakshan Abhiyan (PM-AASHA)', 'The government described PM-AASHA as an integrated scheme intended to ensure remunerative prices for farmers and affordable availability of essential commodities for consumers. Its components include the Price Support Scheme, Price Stabilisation Fund, Price Deficit Payment Scheme and Market Intervention Scheme, with procurement made directly from pre-registered farmers through designated agencies.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2155528');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (537, 39, '2023-02-08', 'Network Planning Group (NPG) under PM GatiShakti recommends 63 infrastructure projects on the Principles of PM GatiShakti', 'The Network Planning Group had recommended 63 infrastructure projects based on PM GatiShakti principles. The release explains that the National Master Plan integrates geospatial infrastructure data and supports coordinated, cost-efficient planning across Ministries and States/UTs.', 'achievement', '63', 'infrastructure projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1897407');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (538, 39, '2023-12-05', '61st Network Planning Group Meeting under PM GatiShakti: Special review of infrastructure projects of various Ministries/Departments', 'The 61st Network Planning Group meeting reviewed the mapping of economic zones and the status of 100 critical infrastructure projects. The release reported that 39 line Ministries and 36 States/UTs had been onboarded, with 1,463 data layers uploaded to the National Master Plan platform.', 'update', '1463', 'data layers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1982597');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (539, 39, '2023-12-20', 'PM GatiShakti National Master Plan to provide multimodal connectivity infrastructure to various economic zones', 'The release describes PM GatiShakti as a GIS-enabled platform integrating infrastructure and project data from the Centre and States/UTs. It says economic zones such as textile, pharmaceutical, defence, electronics, industrial, fishing and agricultural clusters are being mapped to improve connectivity, competitiveness and investment decisions.', 'target', NULL, NULL, 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=1988824');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (540, 39, '2024-10-12', 'PM GatiShakti: Transforming India''s Infrastructure and Connectivity', 'The release presents PM GatiShakti as a multimodal connectivity initiative launched in 2021 to support infrastructure planning and economic growth. It highlights the use of integrated data, district-level planning and coordinated development to strengthen connectivity and support manufacturing and investment.', 'update', NULL, NULL, 'https://pib.gov.in/PressReleasePage.aspx?PRID=2064335');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (541, 39, '2024-10-12', 'PM GatiShakti National Master Plan completes 3 years of transforming India''s Infrastructure landscape', 'The release reports that PM GatiShakti has improved infrastructure planning, project execution and service delivery through geospatial integration and a whole-of-government approach. More than 44 Central Ministries and 36 States/UTs had been onboarded, with over 1,600 data layers integrated and more than 200 major projects evaluated.', 'achievement', '44', 'Central Ministries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2064378');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (542, 39, '2024-11-20', '83 meetings of Network Planning Group held so far with projects worth Rs 15.89 lakh cr', 'The Network Planning Group had held 83 meetings and evaluated 228 infrastructure projects with an estimated cumulative cost of ₹15.89 lakh crore. The release also describes progress under the National Logistics Policy and the launch of a beta District Master Plan for 27 aspirational districts under PM GatiShakti.', 'achievement', '15.89', 'lakh crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2075135');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (543, 39, '2025-08-05', 'PM GatiShakti National Master Plan Evaluates 293 Infrastructure Projects Worth ₹13.59 Lakh Crore', 'The release states that 293 infrastructure projects worth ₹13.59 lakh crore had been evaluated through the Network Planning Group mechanism. It also reports that 57 Central Ministries/Departments and all 36 States/UTs had been onboarded, with about 1,700 data layers integrated on the platform.', 'achievement', '293', 'infrastructure projects', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2152521');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (544, 43, '2023-09-04', 'The Pradhan Mantri Dakshata Aur Kushalata Sampanna Hitgrahi (PM-DAKSH) Yojana', 'The release describes PM-DAKSH’s target groups, eligibility criteria, training formats, stipends and wage compensation. It reports that 107,120 beneficiaries were trained during 2020-21 to 2022-23 and sets a target to train 169,300 candidates during 2023-24 to 2025-26.', 'target', '169,300', 'candidates', 'https://pib.gov.in/PressReleasePage.aspx?PRID=1954579');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (545, 43, '2024-07-30', 'PM-DAKSH Yojana', 'The scheme provides skill training to SC, OBC, DNT, EWS and sanitation-worker groups to improve their prospects for wage and self-employment. It was approved with an outlay of Rs. 450 crore for 2021-22 to 2025-26, including a 2024-25 budget estimate of Rs. 130 crore.', 'update', '450', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2038978');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (546, 43, '2024-08-08', 'PM-Daksh Yojana National Action Plan Aims to Skill 169,300 persons from Marginalized Community till 2025-26', 'The backgrounder explains that PM-DAKSH provides long- and short-term training, upskilling and entrepreneurship development for marginalized communities. It reports 107,120 trainees and 77,237 placements during 2020-21 to 2022-23, with 169,300 additional trainees targeted through 2025-26.', 'target', '169,300', 'persons', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2024/aug/doc202488369501.pdf');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (547, 43, '2024-12-19', 'YEAR-END REVIEW 2024: Department of Social Justice and Empowerment', 'The department’s year-end review reports that 80,185 beneficiaries received PM-DAKSH training during 2023-24. The training was delivered through 112 empanelled training institutes.', 'achievement', '80,185', 'beneficiaries', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2085973');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (548, 43, '2025-02-11', 'Parliament Question: Impact of PM-Daksh Yojana', 'The release states that PM-DAKSH was approved for five years from 2021-22 to 2025-26 and is subject to monitoring and independent evaluation. It reports 187,305 beneficiaries under the scheme up to 2023-24 and an allocation of Rs. 80 crore for 2024-25 at the revised-estimate stage.', 'achievement', '187,305', 'beneficiaries', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2101663');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (549, 43, '2025-07-29', 'Objectives of PM-DAKSH Yojana', 'The release outlines PM-DAKSH’s objective of improving the employability of SC, OBC, DNT, EWS and sanitation-worker groups through skills training. The scheme has an approved outlay of Rs. 450 crore for 2021-22 to 2025-26, including a 2025-26 budget estimate of Rs. 130 crore.', 'update', '450', 'crore', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2149715');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (550, 43, '2025-08-12', 'Skill Training under PM-DAKSH Scheme', 'The release reports that 187,305 individuals had received skill training under PM-DAKSH. Of these, 73,102 beneficiaries, or 39 percent, had received wage or self-employment, while the scheme’s guidelines require training institutes to pursue employment outcomes.', 'achievement', '73,102', 'beneficiaries employed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2155556');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (551, 43, '2025-08-19', 'Welfare Schemes', 'The release provides state-wise PM-DAKSH training data and describes the scheme’s implementation through empanelled institutes. It states that 73,150 trainees had obtained wage or self-employment after completing training and notes a separate entrepreneurship-development project for 1,800 transgender persons.', 'achievement', '73,150', 'trainees employed', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2157941');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (552, 44, '2024-06-19', 'e-Shram portal showcased during 112th International Labour Conference at Geneva, Switzerland', 'The Ministry of Labour and Employment showcased the e-Shram portal and its integrations at the 112th International Labour Conference. More than 29.67 crore unorganised workers had registered by 18 May 2024, and the Ministry said it was developing e-Shram as a one-stop solution for accessing social security schemes.', 'update', '29.67', 'crore workers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2026731');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (553, 44, '2024-07-22', 'More than 29.79 Crore Unorganized Workers have been registered on eShram Portal', 'The release states that more than 29.79 crore unorganised workers, including migrant workers, had registered on e-Shram and received e-Shram cards as of 16 July 2024. It also highlights Aadhaar-verified registration and integrations with the National Career Service, PM-SYM, Skill India Digital and myScheme portals.', 'achievement', '29.79', 'crore workers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2035283');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (554, 44, '2024-11-25', 'E-SHRAM PORTAL', 'The Ministry reported that more than 30.40 crore unorganised workers had registered on e-Shram as of 19 November 2024. The release also noted an average of about 60,000 registrations per day in October 2024 and described integrations with employment, pension, skills and government-scheme platforms.', 'achievement', '30.40', 'crore workers', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2076949');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (555, 44, '2024-12-02', 'Benefits under E-Shram Card', 'The release states that more than 30.42 crore unorganised workers had registered on e-Shram as of 26 November 2024. It describes the portal’s integrations with employment, pension, skills and welfare platforms, and notes the launch of the e-Shram One-Stop-Solution on 21 October 2024.', 'update', '30.42', 'crore workers', 'https://pib.gov.in/Pressreleaseshare.aspx?PRID=2079858');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (556, 44, '2025-02-03', 'E-Shram: One Stop Solution for Unorganised Workers; Over 30.58 Crore Unorganised Workers Registered on e-Shram Portal', 'The Ministry reported that more than 30.58 crore unorganised workers had registered on e-Shram as of 28 January 2025. During 2024, the portal recorded more than 1.23 crore registrations, while 12 schemes had been integrated or mapped and the portal had become available in 22 Indian languages.', 'achievement', '30.58', 'crore workers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2099153');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (557, 44, '2025-07-24', 'e-SHRAM ONE STOP SOLUTION', 'The Ministry reported that more than 30.94 crore unorganised workers had registered on e-Shram as of 17 July 2025, including more than 85.86 lakh workers in Andhra Pradesh. The release said that 14 central social-security and welfare schemes had been integrated or mapped with e-Shram.', 'update', '30.94', 'crore workers', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2147924');
INSERT INTO public.pib_entries (id, scheme_id, date, headline, summary, claim_type, figure, figure_unit, source_url) VALUES (558, 44, '2026-01-29', 'Social Security for Gig and Platform Workers', 'The release describes the e-Shram Aggregator Module, launched on 12 December 2024 to register aggregators and the platform workers engaged by them. It states that 12 major aggregators had been onboarded and explains that the portal is being used to support registration and social-security measures for gig and platform workers.', 'update', '12', 'aggregators', 'https://pib.gov.in/PressReleasePage.aspx?PRID=2220307');
